  [26] = "Speak with Dendrite Starblaze in the village of Nighthaven, Moonglade.",
  [27] = "Speak with Dendrite Starblaze in the village of Nighthaven, Moonglade.",
  [28] = "Find a Shrine Bauble in Lake Elune'ara, and take it to the Shrine of Remulos in northwestern Moonglade.  Once there, use the Shrine Bauble.  You must speak with Tajarri at the shrine afterwards in order to complete the trial.",
  [29] = "Find a Shrine Bauble in Lake Elune'ara, and take it to the Shrine of Remulos in northwestern Moonglade.  Once there, use the Shrine Bauble.  You must speak with Tajarri at the shrine afterwards in order to complete the trial.",
  [30] = "Find the Half Pendant of Aquatic Agility and the Half Pendant of Aquatic Endurance.  Speak with the residents of Moonglade to learn clues as to where these items may be located.  Form the Pendant of the Sea Lion from the two pendant halves.  You need to be in proximity of the Shrine of Remulos to do this.  Bring the joined pendant to Dendrite Starblaze in the village of Nighthaven, Moonglade.",
  [31] = "Return to Thunder Bluff and show Turak Runetotem the Pendant of the Sea Lion.",
