  [289] = "Kill 13 Cursed Sailors, 5 Cursed Marines and First Mate Snellig.  Bring Snellig's Snuffbox to First Mate Fitzsimmons in Menethil Harbor.",
  [290] = "Get the Intrepid Strongbox Key from Captain Halyndor.  Use the key to open the Intrepid's Locked Strongbox.",
  [291] = "Deliver Senir's report to Senator Barin Redstone in Ironforge.",
  [292] = "Bring the Cursed Eye of Paleth to Glorin Steelbrow.",
  [293] = "Bring Archbishop Benedictus the Cursed Eye of Paleth.  Benedictus is in the Cathedral of Light, in the city of Stormwind.",
  [294] = "Ormer Ironbraid at the Whelgar Excavation Site wants you to kill 10 Mottled Screechers and 10 Mottled Raptors.",
  [295] = "Ormer Ironbraid wants you to kill 10 Mottled Scytheclaw raptors and 10 Mottled Razormaw raptors then return to him at the Whelgar Excavation Site.",
  [296] = "Ormer Ironbraid at the Whelgar Excavation Site wants you to kill Sarltooth and return to him with one of his talons once the task is fulfilled.",
  [297] = "Bring Magmar Fellhew 8 Carved Stone Idols.",
  [298] = "Bring Ironband's Progress Report to Jern Hornhelm in Thelsamar.",
  [299] = "Prospector Whelgar wants you to scour the excavation site in search of the 4 missing tablet fragments: Ados, Modr, Golm and Neru.",
  [301] = "Take Ironband's Progress Report to Prospector Stormpike.",
  [302] = "Speak with Jern Hornhelm in Thelsamar.",
  [303] = "Motley Garmason at Dun Modr wants you to kill 15 Dark Iron Dwarves,  5 Dark Iron Tunnelers, 5 Dark Iron Saboteurs and 5 Dark Iron Demolitionists.",
  [304] = "Kill Balgaras the Foul and bring his ear to Longbraid the Grim outside of Dun Modr.",
  [305] = "Tarrel Rockweaver wants you to travel to the Excavation Site and contact Merrin Rockweaver.",
