  [307] = "Go to the Silver Stream Mine and collect 4 loads of Miners' Gear.  Return to Mountaineer Stormpike.",
  [309] = "Ensure Miran and the shipment arrive at the excavation site, then inform Prospector Ironband.",
  [310] = "In the basement of the Thunderbrew Distillery in Kharanos, replace a barrel of Thunder Ale with a Barrel of Barleybrew Scalder.",
  [311] = "Bring the barrel of Thunder Ale to Marleth Barleybrew at the Brewnall Village.",
  [312] = "Retrieve Tundra MacGrann's dried meats from the stolen meat locker in Old Icebeard's cave.",
