  [314] = "Rudra Amberstill wants you to slay Vagash and bring his fang to her at the Ram ranch.",
  [315] = "Bring 6 Shimmerweeds to Rejold Barleybrew in the Brewnall Village.",
  [317] = "Gather 4 Chunks of Boar Meat and 2 Thick Bear Furs, and deliver them to Pilot Bellowfiz at Steelgrill's Depot.",
  [318] = "Get a cask of Evershine from Rejold Barleybrew in Brewnall Village.",
  [319] = "Kill 6 Ice Claw Bears, 8 Elder Crag Boars, and 8 Snow Leopards, and then return to Rejold Barleybrew in Brewnall Village.",
  [320] = "Give the cask of Evershine to Pilot Bellowfiz at Steelgrill's Depot.",
  [321] = "Search the wreckage of The Flying Osprey in the Wetlands.",
