  [1999] = "Find the Dalaran Status Report and return it to Mennet Carkad in the Rogues' Quarter of the Undercity.",
  [2038] = "Find and return Bingles' supplies:  Bingles' Wrench, Bingles' Screwdriver, Bingles' Hammer, and Bingles' Blastencapper.",
