  [2078] = "Find Gelkak's First Mate, the Threshwackonator 4100, and lead it back to Gelkak.",
  [2098] = "Find and return the three pieces of Gelkak's Key to Gelkak Gyromast.",
  [2118] = "Capture a living Rabid Thistle Bear and bring it back to Tharnariun.  Should you fail to capture a Rabid Thistle Bear and lose your trap, return to Tharnariun Treetender and request another trap.",
  [2138] = "Cleanse the forest of 20 Rabid Thistle Bears and return to Tharnariun Treetender in Darkshore.",
  [2139] = "Find and kill the Den Mother.",
  [2158] = "Speak with Innkeeper Farley at the Lion's Pride Inn.",
  [2159] = "Bring the Dolanaar Delivery to Innkeeper Keldamyr.",
  [2160] = "Deliver the Crate of Inn Supplies to Tannok Frosthammer in Kharanos.",
  [2161] = "Bring Ukor's Burden to Innkeeper Grosk in Razor Hill.",
  [2178] = "Bring back 5 Strider Meat to Alanndarian Nightsong in Auberdine.",
  [2198] = "Search for the original creator of the shattered necklace to learn of its potential value.",
  [2199] = "Bring five silver bars to Talvash del Kissel in Ironforge.",
  [2200] = "Search for clues as to the current disposition of Talvash's necklace within Uldaman.  The slain paladin he mentioned was the person who has it last.",
  [2201] = "Find the ruby, sapphire, and topaz that are scattered throughout Uldaman.  Once acquired, contact Talvash del Kissel remotely by using the Phial of Scrying he previously gave you.  From the journal, you know... * The ruby has been stashed in a barricaded Shadowforge area. * The topaz has been hidden in an urn in one of the Trogg areas, near some Alliance dwarves.  * The sapphire has been claimed by Grimlok, the trogg leader.",
  [2202] = "Bring 12 Magenta Fungus Caps to Jarkal Mossmeld in Kargath.",
  [2203] = "Use the empty thaumaturgy vessels on scorched guardian dragons found in the Badlands.  Once you have them filled, bring them to Jarkal Mossmeld in Kargath.",
  [2204] = "Obtain a power source from the most powerful construct you can find in Uldaman, and deliver it to Talvash del Kissel in Ironforge.",
  [2205] = "Deliver Keryn Sylvius's package to Master Mathias Shaw at the Stormwind Barracks.",
  [2206] = "Find the Defias Dockmaster and recover the Shipping Schedule for Master Mathias Shaw.",
  [2218] = "Speak with Hulfdan Blackbeard in Ironforge.",
  [2238] = "Find Onin MacHammar by Gnomeregan.",
  [2239] = "Take Onin's Report back to Hulfdan in Ironforge.",
  [2240] = "Read Baelog's Journal, explore the hidden chamber, then report to Prospector Stormpike.",
  [2241] = "Take Jannok's Rose to Syurna in Darnassus.",
  [2242] = "Find Sethir the Ancient and bring back any clues that you may discover to Syurna.",
  [2258] = "Bring 5 Buzzard Gizzards, 10 Crag Coyote Fangs, and  5 Rock Elemental Shards to Jarkal Mossmeld in Kargath, Badlands.",
  [2259] = "Contact Erion Shadewhisper in Darnassus.",
  [2260] = "Travel to Stormwind City and seek council with Renzik \"The Shiv.\"",
  [2278] = "Speak with stone watcher and learn what ancient lore it keeps.  Once you have learned what lore it has to offer, activate the Discs of Norgannon.",
  [2279] = "Take the miniature version of the Discs of Norgannon to the Explorers' League in Ironforge.",
  [2280] = "Take the miniature version of the Discs of Norgannon to the one of the sages in Thunder Bluff.",
  [2281] = "Venture forth to Lakeshire in the Redridge Mountains and speak with Lucius.",
  [2282] = "Open Lucius's Lockbox, recover the Token of Thievery and return it to Lucius in Lakeshire.",
  [2283] = "Look for a valuable necklace within the Uldaman dig site and bring it back to Dran Droffers in Orgrimmar.  The necklace may be damaged.",
  [2284] = "Find a clue as to the gems' whereabouts in the depths of Uldaman.",
  [2298] = "Travel to Stormwind and seek out Renzik \"The Shiv.\"",
  [2299] = "Travel to Ironforge and speak with Hulfdan Blackbeard.",
  [2300] = "Travel to Stormwind and seek out Renzik \"The Shiv.\"",
  [2318] = "Find someone who can translate the paladin's journal.  The closest location that might have someone is Kargath, in the Badlands.",
  [2338] = "Let Jarkal borrow the necklace.  In exchange, he will translate the journal for you.",
  [2339] = "Recover all three gems and a power source for the necklace from Uldaman, and then bring them to Jarkal Mossmeld in Kargath.  Jarkal believes a power source might be found on the strongest construct present in Uldaman.  From the journal, you know... * The ruby has been stashed in a barricaded Shadowforge area. * The topaz has been hidden in an urn in one of the Trogg areas, near some Alliance dwarves. * The sapphire has been claimed by Grimlok, the trogg leader.",
  [2340] = "Deliver the Necklace and Gem Salvage to Dran Droffers in Orgrimmar.",
  [2341] = "Visit Jarkal Mossmeld in Kargath to see if he was successful.",
  [2342] = "Get Patrick Garrett's family treasure from their family chest in the South Common Hall of Uldaman, and bring it to him in the Undercity.",
  [2358] = "Return the Horns of Nez'ra to Arantir's Shadow in Lakeshire.",
  [2359] = "Steal the Defias Tower Key, break into the Defias Tower and uncover the contents of the Duskwood Chest. Take whatever information you find back to Mathias Shaw in Stormwind. Read Kearnen's Journal to gain insight about the tower.",
  [2360] = "Travel to Westfall and find Agent Kearnen for your debriefing.",
  [2378] = "Journey to Orgrimmar and speak with Shenthul at the Cleft of Shadow.",
  [2379] = "Speak with Zando'zan at the Cleft of Shadow.",
  [2380] = "Speak with Shenthul at the Cleft of Shadow in Orgrimmar.",
  [2381] = "Bring the Southsea Treasure back to Wrenix the Wretched in Ratchet. Do not forget to get an E.C.A.C. and Thieves' Tools from Wrenix's Gizmotronic Apparatus. You will need both of these items to complete your mission.  Should you be attacked by any unusually hostile parrots, use your E.C.A.C.!",
  [2382] = "Travel to Ratchet and speak with Wrenix the Wretched.",
  [2383] = "Read the Simple Parchment and speak to Frang in the Valley of Trials.",
  [2398] = "Find Baelog in Uldaman.",
  [2418] = "Bring 8 Dentrium Power Stones and 8 An'Alleum Power Stones to Rigglefuzz in the Badlands.",
  [2438] = "Bring the Emerald Dreamcatcher to Tallonkai Swiftroot in Dolanaar.",
  [2439] = "Take your reward voucher to Dinita Stonemantle in the Vault of Ironforge.",
  [2440] = "Take the reward voucher to Bena Winterhoof in Thunder Bluff.",
  [2458] = "Travel to the Venture Co. Tower, north of the Sludge Fen and contact the Shattered Hand's covert operative, Taskmaster Fizzule.  When the tower is in sight, use the Flare Gun to signal your arrival to Taskmaster Fizzule. Fire off TWO flares, then approach Taskmaster Fizzule and perform the Shattered /Salute.  These actions must be performed in the correct order, as Fizzule will attack and terminate any person he does not recognize.",
  [2459] = "Tallonkai Swiftroot in Dolanaar wants you to kill 7 Gnarlpine Mystics and find the Missing Jewel.",
  [2460] = "Perform the Shattered Salute on Shenthul.",
  [2478] = "Steal Silixiz's Tower Key from Foreman Silixiz, then kill two Mutated Venture Co. Drones, two Venture Co. Patrollers, and two Venture Co. Lookouts.  Assassinate Grand Foreman Gallywix and take his head, then pick the lock on Gallywix's lockbox and steal the Cache of Zanzil's Altered Mixture. Take the Cache and Gallywix's Head back to Shenthul in Orgrimmar for further instruction.",
  [2479] = "Travel to Tarren Mill in Hillsbrad Foothills and deliver the Sample of Zanzil's Mixture to Serge Hinott.  To get to Tarren Mill, take the Zeppelin to the Undercity and follow the road south through Silverpine and towards Hillsbrad. Follow the signs!",
  [2480] = "Wait for Serge Hinott to complete the cure.",
  [2498] = "Rellian Greenspyre wants you to speak with Denalan at Lake Al'Ameth.",
  [2499] = "Denalan at Lake Al'Ameth wants you to collect the Gargantuan Tumor from Oakenscowl.",
  [2500] = "Acquire the reagents Ghak Healtouch needs from the Badlands, then return to him in Thelsamar.",
  [2501] = "Use the empty thaumaturgy vessels on scorched guardian dragons found in the Badlands.  Once you have them filled, bring them to Ghak Healtouch in Thelsamar.",
  [2518] = "Priestess A'moora in the Temple of the Moon at Darnassus wants you to bring her Lady Sathrah's Silvery Spinnerets.",
  [2519] = "Sister Aquinne wants you to speak with Priestess A'moora in the Temple of the Moon.",
  [2520] = "Priestess A'moora wants you to place Lady Sathrah's silvery spinnerets at the fountain inside the temple, and then return to her.",
  [2521] = "In your journeys throughout the Blasted Lands, should you ever come across a Flawless Draenethyst Sphere, take the item back to Kum'isha the Collector.  Be warned, this gem is one of the most rare crystals in all of Azeroth. Any creature in these lands could be holding a Flawless Draenethyst Sphere.  You will be rewarded for each Flawless Draenethyst Sphere you have collected.",
  [2522] = "Find and return a Flawless Draenethyst Sphere to Kum'isha the Collector.",
  [2541] = "Bring a Shaman Voodoo Charm to Oben Rageclaw in the Ban'ethil Barrow Den.",
  [2561] = "Oben Rageclaw wants you to kill his soulless body, and then use the Voodoo Charm.",
  [2581] = "Bring three Snickerfang Jowls, two Blasted Boar Lungs, and one Scorpok Pincer to Bloodmage Drazial.",
  [2582] = "Bring three Snickerfang Jowls, two Blasted Boar Lungs, and one Scorpok Pincer to Bloodmage Drazial.",
  [2583] = "Bring three Blasted Boar Lungs, two Scorpok Pincers, and one Basilisk Brain to Bloodmage Drazial.",
  [2584] = "Bring three Blasted Boar Lungs, two Scorpok Pincers, and one Basilisk Brain to Bloodmage Drazial.",
  [2585] = "Bring three Scorpok Pincers, two Vulture Gizzards, and one Blasted Boar Lung to Bloodmage Drazial.",
  [2586] = "Bring three Scorpok Pincers, two Vulture Gizzards, and one Blasted Boar Lung to Bloodmage Drazial.",
  [2601] = "Bring ten Basilisk Brains and two Vulture Gizzards to Bloodmage Lynnore.",
  [2602] = "Bring ten Basilisk Brains and two Vulture Gizzards to Bloodmage Lynnore.",
  [2603] = "Bring ten Vulture Gizzards and two Snickerfang Jowls to Bloodmage Lynnore.",
  [2604] = "Bring ten Vulture Gizzards and two Snickerfang Jowls to Bloodmage Lynnore.",
  [2605] = "Collect a Laden Dew Gland and bring it to Marin Noggenfogger in Gadgetzan.",
  [2606] = "Marin Noggenfogger wants you to speak with Sprinkle in Gadgetzan.",
  [2607] = "Speak with Doc Mixilpixil in the cellar of the Barracks.",
  [2608] = "/Lay down to be examined by Doc Mixilpixil. How can he find the cure if he can't find the cause?",
  [2609] = "Bring Doc Mixilpixil one bundle of Simple Wildflowers, one Leaded Vial, one Bronze Tube, and one Spool of Light Chartreuse Silk Thread. The 'itis' doesn't cure itself, young $g fella:lady;. ",
  [2621] = "Speak to Dispatch Commander Ruag in Stonard.",
  [2622] = "Speak to Bengor.",
  [2623] = "Retrieve the Warchief's Orders and return them to the Fallen Hero of the Horde.",
  [2641] = "Sprinkle in Gadgetzan wants you to collect a Violet Tragan and return it to her.",
  [2661] = "Sprinkle wants to you take the Violet Powder to Marin Noggenfogger in Gadgetzan.",
  [2662] = "Marin Noggenfogger wants you to speak to him again after he creates his elixir.",
  [2681] = "Free nine Servants of Razelikh, three Servants of Sevine, three Servants of Allistarj, and three Servants of Grol. Return to the Fallen Hero when your task is complete. You must remain within close proximity of the stones or the process will fail.",
  [2701] = "Open the chest and claim your reward.",
  [2702] = "Speak to Corporal Thund Splithoof.",
  [2721] = "Find out what became of Lieutenant Kirith.",
  [2741] = " ",
  [2742] = "Escort Rin'ji out of the Quel'Danil Lodge, then find his hidden secret at the Overlook Cliffs to the east.",
  [2743] = "Return to the Fallen Hero of the Horde with your findings.",
  [2744] = "Speak with Loramus Thalipedes in Azshara.",
  [2745] = "Speak to Tyrion in Stormwind Castle.",
  [2746] = "Bring 3 Silk Cloth and 2 of Clara's Fresh Apples to Tyrion in Stormwind.",
  [2751] = "Bring two Patterned Bronze Bracers, two Bronze Greatswords, and two Sharp Claws to Orokk Omosh in Orgrimmar.",
  [2752] = "Bring four Bronze Battleaxes and four Bronze Warhammers to Orokk Omosh in Orgrimmar.",
  [2753] = "Bring four Green Iron Helms, four Green Iron Bracers, and two Green Iron Leggings to Orokk Omosh in Orgrimmar.",
  [2754] = "Bring two Solid Iron Mauls, two Silvered Bronze Boots, and two Silvered Bronze Gauntlets to Orokk Omosh in Orgrimmar.",
  [2755] = "Watch and learn the Omosh Dance of Joy.",
  [2756] = "Bring four Steel Breastplates and four Steel Plate Helms to Aturk the Anvil in Orgrimmar.",
  [2757] = "Speak with McGavan in Booty Bay.",
  [2758] = "Bring six Golden Scale Bracers to Hank the Hammer in Stormwind.",
  [2759] = "Speak with McGavan in Booty Bay.",
  [2760] = "Speak with Galvan the Ancient in Stranglethorn Vale.",
  [2761] = "Bring forty Mithril Bars and forty Iron Bars to Galvan the Ancient in Stranglethorn.",
  [2762] = "Bring forty Mithril Bars and five Truesilver Bars to Galvan the Ancient in Stranglethorn.",
  [2763] = "Bring forty Mithril Bars and four Citrines to Galvan the Ancient in Stranglethorn.",
  [2764] = "Speak with Trenton Lighthammer in Gadgetzan.",
  [2765] = "Claim your reward from Galvan the Ancient!",
  [2766] = "Take the distress beacon to Oglethorpe's homing robot in a cave near Feral Scar Vale.",
  [2767] = "Escort OOX-22/FE to the dock along the Forgotten Coast, then report to Oglethorpe Obnoticus in Booty Bay.",
  [2768] = "Bring the Divino-matic Rod to Chief Engineer Bilgewhizzle in Gadgetzan.",
  [2769] = "Speak with Wizzle Brassbolts in the Shimmering Flats.",
  [2770] = "Bring Gahz'rilla's Electrified Scale to Wizzle Brassbolts in the Shimmering Flats.",
  [2771] = "Bring two Mithril Coifs and one Ornate Mithril Shoulder to Trenton Lighthammer.",
  [2772] = "Bring two Heavy Mithril Boots and one Ornate Mithril Pants to Trenton Lighthammer.",
  [2773] = "Bring two Heavy Mithril Breastplates and one Ornate Mithril Gloves to Trenton Lighthammer.",
  [2781] = "Bring the head of Caliph Scorpidsting to Chief Engineer Bilgewhizzle in Gadgetzan.",
  [2782] = "Oran Snakewrithe, a well known scholar on matters concerning the Witherbark trolls, may be able to decipher the tablet. She is known to reside within the Magic Quarter of the Undercity.",
