  [3123] = "Travel to the Hinterlands, and locate the Wildkin. Kill 10, and use the Muisek Vessel to shrink and capture the fallen Wildkin.  Bring 10 Wildkin Muiseks and the Muisek Vessel to Witch Doctor Uzer'i in Feralas.",
  [3124] = "Kill 10 Frayfeather Hippogryphs of any type, then use the Muisek Vessel to shrink and capture them.",
