  [3372] = "Find the Mysterious Artifact being guarded by the Twilight's Hammer Idolaters in the northwest quadrant of the Searing Gorge.",
  [3373] = "Place the Essence of Eranikus in the Essence Font located in this lair in the Sunken Temple.",
  [3374] = "Bring the Oathstone of Ysera's Dragonflight and the Chained Essence of Eranikus to Itharius in the Swamp of Sorrows.  It is there that you will make your choice to aid Ysera's Dragonflight or not.",
  [3375] = "Bring a Mana Potion, Coal, and Sweet Nectar to Talvash del Kissel in Ironforge to get a replacement for Talvash's Phial of Scrying.",
  [3376] = "Bring the head of Chief Sharptusk Thornmantle to Brave Windfeather in Red Cloud Mesa.",
  [3377] = "Hear Zamael tell his tale.",
  [3378] = "Find the Prayer to Elune and take it to Astarii Starseeker in Darnassus.",
  [3379] = "Kill the group of Shadow Silk Poachers that wander the Searing Gorge. Nilith has reason to believe that there are five of them that need to be exterminated. Return to Nilith in the Searing Gorge when this task is complete.",
  [3380] = "Find Marvon Rivetseeker in Tanaris.",
  [3381] = "Bring 2 Undamaged Hippogryph Feathers to Sanath Lim-yo in Azshara if you wish to speak to his master.",
  [3382] = "Defend Captain Vanessa Beltis, her crew and the Horizon Scout's passengers against the naga attack. Captain Vanessa Beltis must survive.",
  [3385] = "Slay Trade Master Kovic and his minion Clunk. Retrieve the Trader's Satchel from his corpse and return it to Nilith.",
  [3402] = "Speak with Vizzklick in Gadgetzan.",
  [3441] = "Listen as Kalaran Windblade tells his story.",
  [3442] = "Collect 4 Hearts of Flame and 4 globes of Golem Oil and return the items to Kalaran Windblade.",
