  [3447] = "Travel into the Sunken Temple and discover the secret hidden in the circle of statues.",
  [3448] = "Speak to Tymor in Ironforge.",
  [3449] = "Using the Drawing Kit, make rubbings of the Rune of Beth'Amara, the Rune of Jin'yael, the Rune of Markri, and the Rune of Sael'hai before heading to the small island off of the southern peninsula of Azshara and signaling Pilot Xiggs Fuselighter to pick them up.",
  [3450] = "Speak to Xiggs Fuselighter in Ironforge.",
  [3451] = "Speak to Xiggs Fuselighter and get a Standard Issue Flare Gun from him in Ironforge.",
  [3452] = "Find and return a Symbol of Ragnaros to Kalaran Windblade.",
  [3453] = "Wait for Kalaran Windblade to complete the Torch of Retribution.",
  [3454] = "Take the Torch of Retribution.",
  [3461] = "Return Tymor's Drawing Kit to him in Ironforge.",
  [3462] = "Speak with Squire Maltrake.",
  [3463] = "Set the North, South, East, and West Sentry Towers on fire by using the Torch of Retribution inside each of the buildings. ",
