  [3482] = "Take this box to Kravel.",
  [3501] = "Bring Kum'isha Imperfect Draenethyst Fragments and be rewarded for each one you turn in.",
  [3502] = "Bring Kum'isha Imperfect Draenethyst Fragments. Any form of monster in the Blasted Lands could be carrying a fragment.",
  [3504] = "Deliver the Sealed Letter to Ag'tor to Ag'tor Bloodfist in Azshara.",
  [3505] = "Kill 10 Blood Elf Reclaimers, and 10 Blood Elf Surveyors before seeking out Magus Rimtori's camp. Once you've found it, look for something that might be important to her that can be used to draw her into a fight.",
  [3506] = "Destroy the arcane focusing crystal tied to Magus Rimtori and then slay her. Afterwards, take the Head of Magus Rimtori to Ag'tor Bloodfist in Azshara.",
  [3507] = "Speak to Belgrom Rockmaul in Orgrimmar.",
  [3508] = "Wait for Loramus to complete the enlightenment spell.",
  [3509] = "Speak with Lord Arkkoroc in Azshara. Begin your search at the waters edge to find the Temple of Arkkoran.",
  [3510] = "Slay Hetaera and bring back Hetaera's Bloodied Head, Hetaera's Beaten Head, and Hetaera's Bruised Head to Lord Arkkoroc.",
  [3511] = "Take the temper back to Loramus Thalipedes.",
  [3512] = "Travel to the eastern part of Winterspring and speak with Umbranse the Spiritspeaker.",
  [3513] = "Take the Runed Scroll to the northern guard tower in the Barrens.",
  [3514] = "Kill the leader of the Talon Den, Rynthariel the Keymaster.",
  [3517] = "Find the Tablet of Beth'Amara, the Tablet of Jin'yael, the Tablet of Markri, and the Tablet of Sael'hai before returning to Jediga in Azshara.",
