  [3565] = "Deliver Xylem's Note to Jediga in Azshara.",
  [3566] = "Slay Lathoric the Black and Obsidion, and return to Thorius in Ironforge with the Head of Lathoric the Black and the Heart of Obsidion. ",
  [3568] = "Fill all 4 Empty Vials at the tide pools along the coast of the Ruins of Eldarath in Azshara before returning to Chemist Cuely.",
  [3569] = "Give Cuely's Elixir to Thersa Windsong in Undercity.",
  [3578] = "Find Samantha Swifthoof.",
  [3579] = "Bring 10 Heavy Silk Bandages, 5 Fadeleaf, 10 Earthroots and 10 bottles of Refreshing Spring Water to Samantha Swifthoof.",
  [3580] = "Speak to Jorn Skyseer at the Camp Taurajo.",
  [3581] = "Speak to Saern Priderunner to learn the Plainsrunning skill.",
  [3601] = "Search the Thalassian Base Camp for Kim'jael's Compass, Scope, Stuffed Chicken and Wizzlegoober, then return them to him in Azshara.",
  [3602] = "Recover twenty Crystallized Azsharite from southern Azshara. You may use the Felhound to assist you in 'sniffing' out the location of cleverly hidden deposits.  Return to Loramus when the task is complete.",
  [3621] = "Take the Shipment to Galvan the Ancient in Stranglethorn Vale.",
  [3625] = "Wait for Galvan to finish forging the weaponry.",
  [3626] = "Return to the Fallen Hero of the Horde.",
  [3627] = "Slay Grol the Destroyer, Lady Sevine, and Archmage Allistarj. From their corpses take the Amulet of Grol, the Amulet of Sevine, and the Amulet of Allistarj.  Remember to USE your Enchanted Azsharite Fel Weaponry to weaken the triad. They cannot be killed otherwise - but use them wisely...",
  [3628] = "Destroy Razelikh the Defiler and return the Severed Horn of the Defiler to the Fallen Hero of the Horde. You will also need to return the Ward of the Defiler so that the Fallen Hero can destroy it, preventing it from ever falling into the wrong hands.",
  [3629] = "If you wish to learn more about Goblin Engineering, take the Manual of Engineering Disciplines to Nixx Sprocketspring in Gadgetzan.",
  [3630] = "If you wish to learn more about Gnome Engineering, take the Manual of Engineering Disciplines to Tinkmaster Overspark at the Gnomeregan Reclamation Facility in Dun Morogh.",
  [3631] = "Speak to Strahad Farsan in the Barrens.",
  [3632] = "If you wish to learn more about Gnome Engineering, take the Manual of Engineering Disciplines to Tinkmaster Overspark at the Gnomeregan Reclamation Facility in Dun Morogh.",
  [3633] = "If you wish to learn more about Goblin Engineering, take the Manual of Engineering Disciplines to Nixx Sprocketspring in Gadgetzan.",
  [3634] = "If you wish to learn more about Gnome Engineering, take the Manual of Engineering Disciplines to Tinkmaster Overspark at the Gnomeregan Reclamation Facility in Dun Morogh.",
  [3635] = "If you wish to learn more about Gnome Engineering, take the Manual of Engineering Disciplines to Oglethorpe Obnoticus in Booty Bay.",
  [3636] = "Archbishop Bendictus wants you to slay Amnennar the Coldbringer in Razorfen Downs.",
  [3637] = "If you wish to learn more about Gnome Engineering, take the Manual of Engineering Disciplines to Oglethorpe Obnoticus in Booty Bay.",
  [3638] = "If you agree to become a Goblin Engineer, then right-click on the Pledge of Secrecy and speak once more with Nixx Sprocketspring in Gadgetzan.",
  [3639] = "Bring 20 Big Iron Bombs, 20 Solid Dynamite, and 5 Explosive Sheep to Nixx Sprocketspring in Gadgetzan.",
  [3640] = "If you agree to become a Gnome Engineer, then right-click on the Pledge of Secrecy and speak once more with Tinkmaster Overspark at the Gnomeregan Reclamation Facility in Dun Morogh.",
  [3641] = "Bring 6 Mithril Tubes, an Accurate Scope, and 2 Advanced Target Dummies to Tinkmaster Overspark at the Gnomeregan Reclamation Facility in Dun Morogh.",
  [3642] = "If you agree to become a Gnome Engineer, then right-click on the Pledge of Secrecy and speak once more with Oglethrope Obnoticus in Booty bay.",
  [3643] = "Bring 6 Mithril Tubes, an Accurate Scope, and a 2 Advanced Target Dummies to Oglethorpe Obnoticus in Booty Bay.",
  [3661] = "Collect 15 Wildkin Feathers from the Hinterlands for Erelas Ambersky in Rut'theran Village.",
  [3681] = "Speak with Duthorian Rall in Stormwind.",
  [3701] = "Venture to the Ruins of Thaurissan in the Burning Steppes and recover information from the Thaurissan Relics. Return to Royal Historian Archesonus when you have recovered the information.",
  [3702] = "Listen to Royal Historian Archesonus recant the history of Thaurissan.",
  [3741] = "Find Hilary's Necklace, and return it to Hilary in Lakeshire.",
  [3761] = "Bring 20 Un'Goro Soil samples to Ghede on the Elder Rise of Thunder Bluff.",
  [3762] = "Speak with Arch Druid Hamuul Runetotem in Thunder Bluff.",
  [3763] = "Speak with Arch Druid Fandral Staghelm in Darnassus.",
  [3764] = "Bring 20 Un'Goro Soil samples to Jenal at the Cenarion Enclave in Darnassus.",
  [3765] = "Travel to Gershala Nightwhisper in Auberdine.",
  [3781] = "Take the Arch Druid's Seed Voucher to Mathrengyl Bearwalker in the Cenarion Enclave of Darnassus.",
  [3782] = "Take the Seed Voucher to Bashana Runetotem in Thunder Bluff.",
  [3783] = "Collect 10 Thick Yeti Furs for Umi Rumplesnicker in Everlook.",
  [3784] = "Speak with Arch Druid Hamuul Runetotem in Thunder Bluff.",
  [3785] = "Use an Evergreen Pouch with a Packet of Tharlendis Seeds and two Un'Goro Soil samples to try and cultivate samples of Morrowgrain.  Bring 10 Morrowgrain to Mathrengyl Bearwalker in Darnassus.",
  [3786] = "Use an Evergreen Pouch with a Packet of Tharlendis Seeds and two Un'Goro Soil samples to try and cultivate samples of Morrowgrain.  Bring 10 Morrowgrain to Bashana Runetotem in Thunder Bluff.",
  [3787] = "Speak with Quintis Jonespyre in Feathermoon Stronghold.",
  [3788] = "Speak with Quintis Jonespyre in Feathermoon Stronghold.",
  [3789] = "Speak with Arch Druid Fandral Staghelm in Darnassus.",
  [3790] = "Speak with Arch Druid Fandral Staghelm in Darnassus.",
  [3791] = "Bring 10 Morrowgrain to Quintis Jonespyre in Feathermoon Stronghold.",
  [3801] = "Speak with Franclorn Forgewright if you are interested in obtaining a key to the city major.",
  [3802] = "Slay Fineous Darkvire and recover the great hammer, Ironfel. Take Ironfel to the Shrine of Thaurissan and place it on the statue of Franclorn Forgewright.",
  [3821] = "Venture forth to the Burning Steppes and find out what became of Sha'ni Proudtusk.",
  [3822] = "Recover Sha'ni's Nose-Ring from Krom'Grul and return it to Thal'trak in Kargath. Search the various caves and mines in Dreadmaul Rock.",
  [3823] = "Slay 15 Firegut Ogre-Mages, 7 Firegut Ogres, and 7 Firegut Ogre Brutes, and return to Oralius when you are finished.",
  [3824] = "Find Gor'tesh, somewhere to the west of Dreadmaul Rock. Kill Gor'tesh and then take Gor'tesh's Lopped Off Head back to Oralius in Burning Steppes.",
  [3825] = "Take Gor'tesh's Lopped Off Head and place it at the top of Dreadmaul Rock. Look for a soft dirt mound to plant the pike.",
  [3841] = "Speak to Quentin in Thousand Needles.",
  [3842] = "Bring 2 Elixir of Fortitudes to Quentin in Thousand Needles.",
  [3843] = "Take your Fragile Sprite Darter Egg to the Hinterlands and speak to Agnar Beastamer, but hurry, you only have 1 hour to find him before the hatchling within the egg dies.",
  [3844] = "Look around in the pond for a clue about who this wrecked raft may belong to.",
  [3845] = "Examine the items inside the pack and bring them to their owner.",
  [3861] = "Find some Special Chicken Feed and return to your befriended chicken. When you find it, /cheer at it before trying to give it the Special Chicken Feed.",
  [3881] = "Bring a Crate of Foodstuffs and Research Equipment to Williden Marshal in Un'Goro Crater.",
  [3882] = "Bring 8 Dinosaur Bones to Spark Nilminer in Un'Goro Crater.",
  [3883] = "Use the Scraping Vial to collect a Hive Wall Sample from one of the Gorishi hive hatcheries in Un'Goro Crater.  Look for the chambers with the hanging larval spawns.  Bring the Hive Wall Sample to Hol'anyee Marshal in Un'Goro Crater.",
  [3884] = "Return the journal to Williden Marshal somewhere in Un'Goro Crater.",
  [3885] = "Escort Petra and Dadanga!",
  [3901] = "Kill 12 Rattlecage Skeletons, and then return to Shadow Priest Sarvis in Deathknell when you are done.",
  [3902] = "Search Deathknell and the vicinity for 6 pieces of Scavenged Goods, and return them to Deathguard Saltain.",
  [3903] = "Speak with Milly Osworth.",
  [3904] = "Bring 8 crates of Milly's Harvest to Milly Osworth at Northshire Abbey.",
  [3905] = "Bring the Grape Manifest to Brother Neals in Northshire Abbey.",
  [3906] = "Travel to the quarry in Blackrock Mountain and slay Overmaster Pyron. Return to Thunderheart when you have completed this assignment.",
  [3907] = "Enter Blackrock Depths and track down Lord Incendius. Slay him and return any source of information you may find to Thunderheart.",
  [3908] = "Take Linken's Sword to Donova Snowden in Winterspring.",
  [3909] = "Seek out Gregan Brewspewer in northern Feralas. From him, learn how you may acquire the Videre Elixir, then return to Donova Snowden in Winterspring.",
  [3911] = "Travel to Blackrock Depths and recover 10 Essence of the Elements. Your first inclination is to search the golems and golem makers. You remember Vivian Lagrave also muttering something about elementals.",
  [3912] = "Go to the graveyard outside Gadgetzan, and use the Videre Elixir. Follow the rest of Donova's instructions to find Gaeriyan.",
  [3913] = "Resurrect, then look for the gravestone that Gaeriyan told you to find.",
  [3914] = "Deliver Linken's Superior Sword to Linken in Un'Goro Crater.",
  [3921] = "Bring the Broken Samophlange to Wenikee Boltbucket.",
  [3922] = "Bring 15 Nugget Slugs to Wenikee Boltbucket in the Barrens.",
  [3923] = "Bring the Broken and Battered Samophlange to Rilli Greasygob in Orgrimmar.",
  [3924] = "Bring the Samophlange Manual to Rilli Greasygob in Orgrimmar.",
  [3941] = "Find J.D. Collie in the cave at Marshal's Refuge.",
  [3942] = "Find Eridan Bluewind in southern Felwood.",
  [3961] = "Take the Silver Totem of Aquementas to Linken in Marshal's Refuge.",
  [3962] = "Travel to Fire Plume Ridge, south of Marshal's Refuge.  Find Blazerunner and use the totem to remove his protective aura. Once he has been defeated, acquire the Golden Flame from the cave.",
  [3981] = "Find Commander Gor'shak in Blackrock Depths.  You recall that the crudely drawn picture of the orc included bars drawn over the portrait. Perhaps you should search for a prison of some sort.",
  [3982] = "Defend Gor'shak.",
  [4001] = "Speak with Kharan Mighthammer and gather information about Princess Moira Bronzebeard's kidnapping. Take that information to Thrall in Orgrimmar.  You recall Gor'shak mentioning that Kharan is being held in a cell nearby.",
  [4002] = "Speak with Thrall if you are prepared to take on the mission he has planned.",
  [4003] = "Slay Emperor Dagran Thaurissan and free Princess Moira Bronzebeard from his evil spell. ",
  [4004] = "Return to Thrall!",
  [4005] = "Take the Book of Aquor, the Silvery Claws, and the Irontree Heart to Tanaris.  Use the Book of Aquor to summon Aquementas.  After you have the completed totem, take it to J.D. Collie in Marshal's Refuge.",
  [4021] = "Bring a Piece of Krom'zar's Banner to Regthar Deathgate, west of the Crossroads.",
  [4022] = "Show Cyrus Therepentous the Black Dragonflight Molt you received from Kalaran Windblade.",
  [4023] = "Show Cyrus Therepentous proof of your worth.  You have a feeling that Cyrus already knows that you are unworthy.",
  [4024] = "Travel to Blackrock Depths and slay Bael'Gar.  You only know that the giant resides inside Blackrock Depths. Remember to use the Altered Black Dragonflight Molt on Bael'Gar's remains to capture the Fiery Essence.  Return the Encased Fiery Essence to Cyrus Therepentous.",
  [4061] = "Venture to the Burning Steppes and recover 10 Fractured Elemental Shards for Hierophant Theodora Mulvadania.  You recall Theodora mentioning the golems and elementals of that region as being a source for these shards.",
  [4062] = "Take the Elemental Shard Sample to Lotwil Veriatus.  You recall Theodora saying that Lotwil was stationed in a camp to the east.",
  [4063] = "Find and slay Golem Lord Argelmach. Return his head to Lotwil. You will also need to collect 10 Intact Elemental Cores from the Ragereaver Golems and Warbringer Constructs protecting Argelmach. You know this because you are psychic. ",
  [4081] = "Venture to Blackrock Depths and destroy the vile aggressors!  Warlord Goretooth wants you to kill 15 Anvilrage Guardsmen, 10 Anvilrage Wardens and 5 Anvilrage Footmen. Return to him once your task is complete.",
  [4082] = "Venture to Blackrock Depths and destroy the vile aggressors!  Warlord Goretooth wants you to kill 10 Anvilrage Medics, 10 Anvilrage Soldiers and 10 Anvilrage Officers. Return to him once your task is complete.",
  [4084] = "Collect 11 Silvery Claws and 1 Irontree Heart for Eridan Bluewind in Felwood.",
  [4101] = "Bring 15 Blood Amber to Arathandris Silversky in Felwood.",
  [4102] = "Bring 15 Blood Amber to Maybess Riverbreeze in Felwood.",
  [4120] = "Talo Thornhoof at Camp Mojache in Feralas wants you to kill 12 Angerclaw Grizzlies and 12 Felpaw Ravagers in Felwood.",
  [4121] = "Escort your prisoner, Grark Lorkrub, through Burning Steppes and through Blackrock Mountain to the Searing Gorge.  You recall Lexlort mentioning that he would have his men waiting on the other side to take Grark into custody.  You will also be required to hand over your Thorium Shackles to Lexlort.",
  [4122] = "Travel to the Burning Steppes and find Grark Lorkrub. You recall Lexlort mentioning that he was last seen in a massive Blackrock fortress.  When you find Grark Lorkrub, use the Thorium Shackles to bind him and then lead him back through Blackrock Mountain to the Searing Gorge. Lexlort will have his men waiting on the other side to take Grark into custody.",
  [4123] = "Bring the Heart of the Mountain to Maxwort Uberglint in the Burning Steppes.",
  [4124] = "Speak with Ginro Hearthkindle in Feathermoon Stronghold.",
  [4125] = "Locate the courier's boat somewhere along the coast of Feralas.",
  [4126] = "Bring the Lost Thunderbrew Recipe to Ragnar Thunderbrew in Kharanos.",
  [4127] = "Return to Feathermoon Stronghold and show Ginro Hearthkindle the Discarded Knife you have found.",
  [4128] = "Speak with Ragnar Thunderbrew.",
  [4129] = "Take the Discarded Knife to Quintis Jonespyre in Feathermoon Stronghold.",
  [4130] = "Speak with Ginro Hearthkindle in Feathermoon Stronghold.",
  [4131] = "Search the Woodpaw Gnoll camps of southern Feralas for evidence of the courier's belongings or the courier himself.",
  [4132] = "Travel to Blackrock Depths and slay General Angerforge! Return to Warlord Goretooth when the task is complete.",
  [4133] = "Speak with Shadowmaster Vivian Lagrave in Kargath.",
  [4134] = "Bring the Lost Thunderbrew Recipe to Vivian Lagrave in Kargath.",
  [4135] = "Now that Raschal's last known whereabouts have been discovered, continue your search for him or his remains in the Writhing Deep.  According to the note, it is located to the south of the Woodpaw gnoll camps.",
  [4136] = "Bring Ribbly's Head to Yuka Screwspigot in the Burning Steppes.",
  [4141] = "Collect 15 Bloodpetals and return to Muigin.",
  [4142] = "Take a Bloodpetal to Gregan Brewspewer in Feralas.",
  [4143] = "Collect 5 samples of Atal'ai Haze, then return to Muigin in Un'Goro Crater.",
  [4145] = "Hunt 5 Bloodpetal Lashers, 5 Bloodpetal Threshers, 5 Bloodpetal Flayers and 5 Bloodpetal Trappers for Larion at Marshal's Refuge.",
  [4146] = "Deliver the Unloaded Zapper and 5 samples of Atal'ai Haze to Larion in Marshal's Refuge.",
  [4147] = "Travel to Marvon Rivetseeker's workshop in Ratchet.",
  [4161] = "Collect 7 Small Spider Legs for Zarrin in Dolanaar.",
  [4181] = "If you wish to learn more about Goblin Engineering, take the Manual of Engineering Disciplines to Nixx Sprocketspring in Gadgetzan.",
  [4182] = "Slay 15 Black Broodlings, 10 Black Dragonspawn, 4 Black Wyrmkin and 1 Black Drake. Return to Helendis Riverhorn when the task is complete.",
  [4183] = "Travel to Lakeshire and deliver Helendis Riverhorn's Letter to Magistrate Solomon. ",
  [4184] = "Travel to Stormwind and deliver Solomon's Plea to Highlord Bolvar Fordragon.  Bolvar resides in Stormwind Keep. ",
  [4185] = "Speak with Highlord Bolvar Fordragon after speaking with Lady Katrana Prestor.",
  [4186] = "Take Bolvar's Decree to Magistrate Solomon in Lakeshire.",
  [4201] = "Bring 4 Gromsblood, 10 Giant Silver Veins and Nagmara's Filled Vial to Mistress Nagmara in Blackrock Depths.",
  [4223] = "Speak with Marshal Maxwell in the Burning Steppes.",
  [4224] = "Speak with Ragged John to learn of Marshal Windsor's fate and return to Marshal Maxwell when you have completed this task.  You recall Marshal Maxwell telling you to search for him in a cave to the north.",
  [4241] = "Travel to Blackrock Mountain in the northwest and enter Blackrock Depths. Find out what became of Marshal Windsor.  You recall Ragged John talking about Windsor being dragged off to a prison.",
  [4242] = "Give Marshal Maxwell the bad news.",
  [4243] = "Find A-Me 01 in Un'Goro Crater.",
  [4244] = "Find a Mithril Casing and return to A-Me 01 in Un'Goro Crater.",
  [4245] = "Escort A-Me 01 back to Karna Remtravel in Un'Goro Crater.",
  [4261] = "Escort Arei to safety, then speak with Kayneth Stillwind in Forest Song, in eastern Ashenvale.",
  [4262] = "Slay Overmaster Pyron and return to Jalinda Sprig.  You recall Jalinda talking about Pyron guarding the quarry. Perhaps you should search there?",
  [4263] = "Find Lord Incendius in Blackrock Depths and destroy him!",
  [4264] = "You may have just stumbled on to something that Marshal Windsor would be interested in seeing. There may be hope, after all.",
  [4265] = "Free Raschal from the Zukk'ash hive.  Return to Ginro Hearthkindle in Feathermoon Stronghold and let him know that Raschal is alive and well.",
  [4266] = "Speak with Shandris Feathermoon in Feathermoon Stronghold.",
  [4267] = "Bring Raschal's Report to Gracina Spiritmight in Darnassus.",
  [4281] = "Bring the Undelivered Parcel to Falfindel Waywarder in Thalanaar.",
  [4282] = "Return Marshal Windsor's Lost Information.  Marshal Windsor believes that the information is being held by Golem Lord Argelmach and General Angerforge.",
  [4283] = "Oralius wants 50 Blackrock Medallions. Chances are high that these medallions can be found on the orcs in the Burning Steppes.",
  [4284] = "Collect 7 Power Crystals of each color: red, blue, yellow, and green. Bring them to J.D. Collie at Marshal's Refuge.",
  [4285] = "Discover the location of the Northern Crystal Pylon in Un'Goro Crater.",
  [4286] = "Travel to Blackrock Depths and recover 20 Dark Iron Fanny Packs. Return to Oralius when you have completed this task. You assume that the Dark Iron dwarves inside Blackrock Depths carry these 'fanny pack' contraptions.",
  [4287] = "Discover the location of the Eastern Crystal Pylon in Un'Goro Crater.",
  [4288] = "Discover the location of the Western Crystal Pylon.",
  [4289] = "Bring 2 Un'Goro Gorilla Pelts, 2 Un'Goro Stomper Pelts, and 2 Un'Goro Thunderer Pelts to Torwa Pathfinder at the entrance of Un'Goro Crater.",
  [4290] = "Find the carcass of Lar'korwi's freshest kill and steal a Piece of Threshadon Carcass before returning to Torwa Pathfinder in Un'Goro Crater.",
  [4291] = "Bring 2 Ravasaur Pheromone Glands to Torwa Pathfinder near the entrance to Un'Goro Crater.",
  [4292] = "Using the contents of Torwa's Pouch, summon Lar'korwi and defeat him. Then bring Lar'korwi's Head to Torwa Pathfinder near the entrance to Un'Goro Crater.",
  [4293] = "Gather Felwood Slime Samples from any of the slimes in Felwood. Then, using the Testing Equipment next to Chemist Fuely in Undercity, see which of your samples are the most corrupt. Bring 5 of the Corrupted Felwood Samples you find to Chemist Fuely.",
  [4294] = "Gather Un'Goro Slime Samples from any of the slimes in Un'Goro Crater. Then, using the Testing Equipment next to Chemist Fuely in Undercity, see which of your samples are the most pure. Bring 5 of the Pure Un'Goro Samples you find to Chemist Fuely.",
  [4296] = "Bring the Tablet Transcript to Maxwort Uberglint in the Burning Steppes.",
  [4297] = "Bring 5 Silvermane Stalker Flanks to Agnar Beastamer in Hinterlands.",
  [4298] = "Speak to Agnar Beastamer in the Hinterlands.",
  [4299] = "Place the PX83-Enigmatron in the Tomb of the Seven, then return to Maxwort Uberglint.",
  [4300] = "Bring 8 White Ravasaur Claws to Jes'rimon in Orgrimmar.",
  [4301] = "Bring U'cha's Pelt to Torwa Pathfinder at the entrance of Un'Goro Crater.",
  [4321] = "Speak with J.D. Collie in a moment.",
  [4322] = "Help Marshal Windsor get his gear back and free his friends. Return to Marshal Maxwell if you succeed.",
  [4323] = "Bring 7 Spotted Hyena Pelts to TESTTAUREN at Freewind Post.",
  [4324] = "Speak with Yuka Screwspigot in the Burning Steppes.",
  [4341] = "Travel to Blackrock Depths and find Kharan Mighthammer.  The King mentioned that Kharan was being held prisoner there - perhaps you should try looking for a prison.",
  [4342] = "Listen as Kharan Mighthammer tells his story.",
  [4361] = "Return to Ironforge and deliver the bad news to King Magni Bronzebeard.",
  [4362] = "Return to Blackrock Depths and rescue Princess Moira Bronzebeard from the evil clutches of Emperor Dagran Thaurissan.",
  [4363] = "Return to Ironforge and speak with King Magni Bronzebeard.",
  [4402] = "Bring Galgar 10 Cactus Apples. You remember him saying that they could be found near cactuses.",
  [4421] = "Kill 11 Jadefire Felsworns, 9 Jadefire Shadowstalkers, 9 Jadefire Rogues, and Xavathras. Return to Eridan Bluewind in Felwood when the task has been completed.",
  [4441] = "Travel to Darnassus and use Eridan's Vial to collect a Vial of Blessed Water from the Temple of the Moon. Return to Eridan with the filled vial.",
  [4442] = "Speak to Eridan again in a moment.",
  [4449] = "Kill 8 Dark Iron Geologists and bring 15 pieces of Silk Cloth to the person locked in the outhouse in Searing Gorge.",
  [4450] = "Take the copy of Goodsteel's Ledger and then find the items listed in it before seeking Krinkle Goodsteel in Tanaris.",
  [4451] = "Search Searing Gorge and find a use for the Grimesilt Outhouse Key you have found.",
  [4485] = "Speak to Duthorian Rall in Stormwind.",
  [4486] = "Speak to Duthorian Rall in Stormwind.",
  [4487] = "Speak to Strahad Farsan in Ratchet.",
  [4488] = "Speak to Strahad Farsan in Ratchet.",
  [4489] = "Speak to Strahad Farsan in Ratchet.",
  [4490] = "Speak to Strahad Farsan in Ratchet to learn the ability to summon a Felsteed.",
  [4491] = "Lead Ringo to Spraggle Frock at Marshal's Refuge.  If Ringo faints, use Spraggle's Canteen to revive him.",
  [4492] = "Find Ringo at Fire Plume Ridge.",
  [4493] = "Speak to Alchemist Pestlezugg in Gadgetzan.",
  [4494] = "Speak to Alchemist Pestlezugg in Gadgetzan.",
  [4495] = "Find Iverron by the cave to the north.",
  [4496] = "Bring a Gorishi Scent Gland and 5 Un'Goro Soil samples to Alchemist Pestlezugg in Gadgetzan.",
  [4501] = "Kill 10 Pterrordax and 15 Frenzied Pterrordax, then speak to Spraggle Frock at Marshal's Refuge.",
  [4502] = "Collect 9 samples of Un'Goro Ash from the fire elementals around the volcano in Un'Goro Crater, and return them to Liv Rizzlefix in Ratchet.",
  [4503] = "Collect 8 Webbed Diemetradon Scales and 8 Webbed Pterrordax Scales for Shizzle in Marshal's Refuge.",
  [4504] = "Collect 12 samples of Super Sticky Tar for Tran'rek in Gadgetzan.",
  [4505] = "Collect a sample of corrupted water from the Jadefire Satyrs' moonwell and bring it to Winna Hazzard at Bloodvenom Post.",
  [4506] = "Take Winna's kitten to the corrupted moon well, release it, then bring it back to Winna.  Once you have returned to Winna, click on the cat to release it to Winna.",
  [4507] = "Defeat the Gorishi Hive Queen once she is summoned.  Bring the Gorishi Queen's Brain to Alchemist Pestlezugg in Gadgetzan.",
  [4508] = "Bring Pestlezugg's Un'Goro Report to Gracina Spiritmight in Darnassus.",
  [4509] = "Bring Pestlezugg's Un'Goro Report to Zilzibin Drumlore in Orgrimmar.",
  [4510] = "Bring the Bank Voucher to Idriana in the bank of Darnassus.",
  [4511] = "Bring the Bank Voucher to Karus in the bank of Orgrimmar.",
  [4512] = "Bring 6 Filled Cursed Ooze Jars and 6 Filled Tainted Ooze Jars to Laris Geardawdle in Ironforge.",
  [4513] = "Bring 10 Filled Pure Sample Jars to Laris Geardawdle in Ironforge.  If you have trouble finding them, perhaps try to get more clues from Laris.",
  [4521] = "Trull Failbane in Felwood wants you to kill 15 Raging Owlbeasts and 15 Ragged Owlbeasts.",
  [4542] = "Bring the Urgent Message to Cliffwatcher Longhorn at Freewind Post.",
  [4581] = "Take Shindrell's Note to Kayneth Stillwind in Forest Song.",
  [4601] = "Insert a Grime-Encrusted Item into the Sparklematic 5200, and be sure to have three silver coins to start the machine.",
  [4602] = "Insert a Grime-Encrusted Item into the Sparklematic 5200, and be sure to have three silver coins to start the machine.",
  [4621] = "Slay Fleet Master Seahorn and Baron Revilgaz of Booty Bay, and then return to Fleet Master Firallon aboard the Crimson Veil off the coast of Stranglethorn Vale.",
  [4641] = "Speak with Gornek. You recall Kaltunk marking your map with his location and mentioning that Gornek resided in the Den, a building to the west. ",
  [4642] = "Bring a Merged Ooze Sample to Chemist Fuely in Undercity.",
  [4681] = "Recover the Sea Turtle Remains from the Skeletal Sea Turtle in the waters west of Auberdine, and then speak with Gwennyth Bly'Leggonde back in Auberdine.",
  [4701] = "Travel to Blackrock Spire and destroy the source of the worg menace. As you left Helendis, he shouted a name: Halycon. It is what the orcs refer to in regards to the worg.",
  [4721] = "Trull Failbane in Felwood wants you to hunt 10 Berserk Owlbeasts in Winterspring.",
  [4722] = "Take the Sea Turtle Remains to Gwennyth Bly'Leggonde in Auberdine.",
  [4723] = "Take the Sea Creature Bones to Gwennyth Bly'Leggonde in Auberdine.",
  [4724] = "Slay Halycon, pack mistress of the Bloodaxe worg.",
  [4725] = "Take the Strangely Marked Box to Gwennyth Bly'Leggonde in Auberdine.",
  [4726] = "Bring 8 Broodling Essence and the Draco-Incarcinatrix 900 to Tinkee Steamboil at the Flame Crest in the Burning Steppes.",
  [4727] = "Take the Sea Turtle Remains to Gwennyth Bly'Leggonde in Auberdine.",
  [4728] = "Take the Sea Creature Bones to Gwennyth Bly'Leggonde in Auberdine.",
  [4729] = "Travel to Blackrock Spire and find Bloodaxe Worg Pups. Use the cage to carry the ferocious little beasts. Bring back a Caged Worg Pup to Kibler.",
  [4730] = "Take the Sea Creature Bones to Gwennyth Bly'Leggonde in Auberdine.",
  [4731] = "Take the Strangely Marked Box to Gwennyth Bly'Leggonde in Auberdine.",
  [4732] = "Take the Sea Turtle Remains to Gwennyth Bly'Leggonde in Auberdine.",
  [4733] = "Take the Sea Creature Bones to Gwennyth Bly'Leggonde in Auberdine.",
  [4734] = "Use the Eggscilloscope Prototype on an egg in the Rookery.",
  [4735] = "Bring 8 Collected Dragon Eggs and the Collectronic Module to Tinkee Steamboil at Flame Crest in the Burning Steppes.",
  [4736] = "Speak to Menara Voidrender in the Barrens.",
  [4737] = "Speak to Menara Voidrender in the Barrens.",
  [4738] = "Speak with Menara Voidrender in the Barrens.",
  [4739] = "Speak to Menara Voidrender in the Barrens.",
  [4740] = "Find and slay the murloc known as Murkdeep.  The creature is thought to be defending the murloc huts south of Auberdine along the water.  Report the death of Murkdeep to Sentinel Glynda Nal'Shea in Auberdine.",
  [4741] = "Trull Failbane in Felwood wants you to hunt 13 Moontouched Owlbeasts.",
  [4742] = "Find the three gemstones of command: The Gemstone of Smolderthorn, Gemstone of Spirestone, and Gemstone of Bloodaxe. Return them, along with the Unadorned Seal of Ascension, to Vaelan.  The Generals, as told to you by Vaelan, are: War Master Voone of the Smolderthorn; Highlord Omokk of the Spirestone; and Overlord Wyrmthalak  of the Bloodaxe.",
  [4743] = "Travel to the Wyrmbog in Dustwallow Marsh. Find the ancient drake, Emberstrife and beat him without mercy until his will is broken.  It is at that moment which you must place the Unforged Seal of Ascension before the great beast. You must then be quick to use the Orb of Draconic Energy on his weakened form and claim dominion over his mental faculties. Control the beast and force the Flames of the Black Dragonflight upon the Unforged Seal of Ascension!",
  [4761] = "Speak with Thundris Windweaver in Auberdine.",
  [4762] = "Travel north of Auberdine to the first waterfall along the Cliffspring River and draw a sample from the pool there.  Return to Thundris Windweaver in Auberdine with the Cliffspring River Sample.",
  [4763] = "Fill the Empty Cleansing Bowl at the Auberdine Moonwell.  Gather a sample of fruit, nut, and grain from the northern Blackwood furbolg camps.  Mix the bowl and place it near the bonfire closest to the Cliffspring River at the northern camp, thus summoning the satyr corruptor.  Take the Talisman of Corruption and bring it to Thundris Windweaver in Auberdine.",
  [4764] = "Bring Doomrigger's Clasp to Mayara Brightwing in the Burning Steppes.",
  [4765] = "Bring Ridgewell's Crate to Remington Ridgewell in Stormwind.",
  [4766] = "Speak with Mayara Brightwing in the Burning Steppes.",
  [4767] = "Bring 10 Highperch Wyvern Eggs to Elu in Freewind Post.",
  [4768] = "Bring the Darkstone Tablet to Shadow Mage Vivian Lagrave in Kargath.",
  [4769] = "Speak with Shadowmage Vivian Lagrave.",
  [4770] = "Escort Pao'ka Swiftmountain from Highperch, and then talk to Motega Firemane in Whitereach Post.",
  [4771] = "Place Dawn's Gambit in the Viewing Room of the Scholomance.  Defeat Vectus, then return to Betina Bigglezink.",
  [4781] = "Bring a Gold Bar to Xizk Goodstitch in Stranglethorn Vale.",
  [4782] = "Return to Menara Voidrender in the Barrens.",
  [4783] = "Bring 10 Vials of Hatefury Blood and 1 Lesser Infernal Stone to Menara Voidrender in the Barrens.",
  [4784] = "Bring some Fine Gold Thread, 2 Smoldering Coals, and a Soul Shard to Menara Voidrender in the Barrens.",
  [4786] = "Wait for Menara Voidrender to complete your robe and then speak to her again.",
  [4787] = "Bring the Ancient Egg to Yeh'kinya in Tanaris.",
  [4788] = "Bring the Fifth and Sixth Mosh'aru Tablets to Prospector Ironboot in Tanaris.",
  [4808] = "Give Tinkee's Letter to Felnok Steelspring.",
  [4809] = "Bring 8 Uncracked Chillwind Horns to Felnok Steelspring.",
  [4810] = "Bring Felnok's Package to Tinkee Steamboil in the Burning Steppes.",
  [4811] = "Travel east of Auberdine and look for a large, red crystal along Darkshore's eastern mountain range.  Report back what you find to Sentinel Glynda Nal'Shea in Auberdine.",
  [4812] = "Fill the Empty Water Tube at the Auberdine moonwell, and then investigate the red crystal along Darkshore's eastern mountain wall.",
  [4813] = "Report back what you have found to Sentinel Glynda Nal'Shea in Auberdine.",
  [4821] = "Return the Alien Egg to Hagar Lightninghoof in Freewind Post.",
  [4822] = "Get some Strawberry Ice Cream for your ward.  The lad seems to prefer Tigule and Foror's brand ice cream.",
  [4841] = "Kill 12 Galak Scouts, 10 Galak Wranglers, and 6 Galak Windchasers, and then return to Cliffwatcher Longhorn in Freewind Post.",
  [4842] = "Follow Donova Snowden's instructions, then report back.",
  [4861] = "Locate Jaron Stoneshaper's wrecked camp and supplies in southern Winterspring.",
  [4862] = "Travel to Blackrock Spire and collect 15 Spire Spider Eggs for Kibler.  By the sound of it, these eggs could be found near spiders.",
  [4863] = "Find Jaron Stoneshaper's wrecked wagon.",
  [4864] = "Pick up Jaron's Supplies from the snow, then find the wildkin that stole the amulet Jaron spoke of.  Bring Jaron's Supplies and the Blue-feathered Amulet to Jaron Stoneshaper at the lodge in Winterspring.",
  [4865] = "Report your findings to Motega Firemane.",
  [4866] = "In the heart of Blackrock Spire you will find Mother Smolderweb. Engage her and get her to poison you. Chances are good that you will have to kill her as well. Return to Ragged John when you are poisoned so that he can 'milk' you.",
  [4867] = "Read Warosh's Scroll.  Bring Warosh's Mojo to Warosh.",
  [4881] = "Warn Kanati Greycloud at Whitereach Post of the plot to kill him.",
  [4882] = "Take the Blue-feathered Necklace to Trull Failbane at Bloodvenom Post.",
  [4883] = "Take the Blue-feathered Necklace to Nara Wildmane.",
  [4901] = "Protect Ranshalla while she attempts to reactivate the Altar of Elune. Report your findings to Erelas Ambersky in Rut'theran Village.",
  [4902] = "Speak with Arch Druid Fandral Staghelm in Darnassus.",
  [4903] = "Slay Highlord Omokk, War Master Voone, and Overlord Wyrmthalak. Recover Important Blackrock Documents. Return to Warlord Goretooth in Kargath when the mission has been accomplished.",
  [4904] = "Escort Lakota Windsong from the Darkcloud Pinnacle, and then talk to Thalia Amberhide at Freewind Post.",
  [4905] = "Defend Kanati Greycloud",
  [4906] = "Eridan Bluewind in Felwood wants you to kill 8 Jadefire Hellcallers, 8 Jadefire Betrayers, 8 Jadefire Tricksters, and Xavaric. Return to Eridan when the task is completed.",
  [4907] = "Speak with Tinkee Steamboil.",
  [4921] = "Find Mankrik's wife and then return to him in the Crossroads.",
  [4941] = "Speak with Eitrigg in Orgrimmar. When you have discussed matters with Eitrigg, seek council from Thrall.  You recall having seen Eitrigg in Thrall's chamber.",
  [4961] = "Kill the Demon of the Orb, then speak with Tabetha.",
  [4962] = "Take the Felhas Ruby and use it on one of the Felhounds found in Desolace. After successful, bring the Felhas Ruby and the Imprisoned Felhound Spirit back to Menara Voidrender in the Barrens.",
  [4963] = "Take the Infus Emerald and use it on one of the Infernals found in Desolace. After successful, bring the Infus Emerald and the Imprisoned Infernal Spirit back to Menara Voidrender in the Barrens.",
  [4964] = "Wait for Menara Voidrender to complete the Orb of Dar'Orahil and then speak to her again.",
  [4965] = "Speak to Menara Voidrender in the Barrens.",
  [4966] = "Protect Kanati Greycloud from the centaur attack.",
  [4967] = "Speak to Menara Voidrender in the Barrens.",
  [4968] = "Speak to Menara Voidrender in the Barrens.",
  [4969] = "Speak to Menara Voidrender in the Barrens.",
  [4970] = "Collect 5 Shardtooth Meats and 5 Chillwind Meats for Rivern Frostwind in Winterspring.",
  [4971] = "Use the Temporal Displacer near one of Andorhal's silos and uncover Temporal Parasites.  Slay 15 Temporal Parasites, and then return the Temporal Displacer to Chromie in the Andorhal Inn, Western Plaguelands.",
  [4972] = "Locate 5 Andorhal Watches, found in lockboxes amongst the rubble of the city.  Return with them to Chromie in the Andorhal Inn, Western Plaguelands.",
  [4973] = "Locate 5 Andorhal Watches amongst the rubble of the city, and return with them to Chromie in the Andorhal Inn, Western Plaguelands.",
  [4974] = "Travel to Blackrock Spire and slay Warchief Rend Blackhand. Take his head and return to Orgrimmar.",
  [4975] = "Wait for Menara Voidrender to complete the Orb of Noh'Orahil and then speak to her again.",
  [4976] = "Return the Cleansed Infernal Orb to Menara Voidrender in the Barrens.",
  [4981] = "Travel to Blackrock Spire and find out what happened to Bijou.",
  [4982] = "Find Bijou's Belongings and return them to her. You recall her mentioning that she stashed them on the bottom floor of the city.",
  [4983] = "Take Bijou's Reconnaissance Report back to Grandmaster Lexlort in Kargath.",
  [4984] = "Destroy 8 Diseased Wolves, and then return to Mulgris Deepriver at the Writhing Haunt, Western Plaguelands.",
  [4985] = "Destroy 8 Diseased Grizzlies, and then return to Mulgris Deepriver at the Writhing Haunt, Western Plaguelands.",
  [4986] = "Based on the magic enchanted within the Glyphed Oaken Branch, its delivery to the Cenarion Circle in Darnassus is the next step the tauren druid sought.  Seek one of the druids there for assistance.",
  [4987] = "Based on the magic enchanted within the Glyphed Oaken Branch, its delivery to the Cenarion Circle in Thunder Bluff is the next step the tauren druid sought.  Seek one of the druids there for assistance.",
  [5001] = "Find Bijou's Belongings and return them to her. Good luck!",
  [5002] = "Travel to the Burning Steppes and give Bijou's Information to Marshal Maxwell.",
  [5021] = "The ramblings of the ghostly woman indicated that she needed a package delivered.  She claimed that it was where her horse was.  As to where the horse is or where the package was to be delivered - the ghost remains incomprehensible.",
  [5022] = "Check with the Royal Factors of Stormwind to learn the whereabouts of an Emma Felstone.  There is usually a census officer located in City Hall.",
  [5023] = "Check with the Royal Overseers of the Undercity to learn the whereabouts of a Jeremiah Felstone.  There is usually a census officer located near guild and tabard registration.",
  [5041] = "Find and return Crossroads' Supply Crates to Thork in the Barrens.",
  [5047] = "Talk to Malyfous Darkhammer in Everlook.",
  [5048] = "Find Ol' Emma in Stormwind and see if she is in fact Emma Felstone.  If she is, then perhaps she'd like the package Janice Felstone made for her.",
  [5049] = "Find Jeremiah Payson in the Undercity and see if he is in fact Jeremiah Felstone.  If he is, then perhaps he'd like the package Janice Felstone made for him.",
  [5050] = "Return to Janice Felstone in Western Plaguelands her Good Luck Half-Charm.",
  [5051] = "Locate the other half of the Good Luck Charm somewhere on the Felstone Farm in Western Plaguelands and reassemble it.  Give the Good Luck Charm to Janice Felstone on the Felstone Farm, Western Plaguelands.",
  [5052] = "Bring a Blood Shard to Mangletooth in Camp Taurajo in the Barrens.  Collect more Blood Shards if you want him to bless you with Agamaggan's power.",
  [5053] = "Test quest to see if mail is sent to your mailbox. Just hit complete, then go check your mail.  Have a nice day.",
  [5054] = "Storm Shadowhoof at Everlook in Winterspring wants you to kill Ursius.",
  [5055] = "Storm Shadowhoof at Everlook in Winterspring wants you to kill Brumeran.",
  [5056] = "Storm Shadowhoof at Everlook in Winterspring wants you to defeat Shy-Rotam.",
  [5057] = "Bring Storm Shadowhoof's Marker to Melor Stonehoof in Thunder Bluff.",
  [5061] = "Return to Darnassus and show Mathrengyl Bearwalker the Pendant of the Sea Lion.",
  [5062] = "Gather 10 bushels of Incendia Agave, and then consult Magatha Grimtotem on Elder Rise in Thunderbluff.",
  [5063] = "In order to create the Cap of the Scarlet Savant, you will be required to bring the following items back to Malyfous Darkhammer: 1 Pristine Hide of the Beast; 5 Frayed Abomination Stitchings; 8 Arcane Crystals; 5 Enchanted Scarlet Thread.   You will also be required to pay 50 gold pieces for the crafting of the item.",
  [5064] = "Locate and retrieve the three Secret Notes in Darkcloud Pinnacle",
  [5065] = "Bring the Third and Fourth Mosh'aru Tablets to Prospector Ironboot in Tanaris.",
  [5066] = "Seek out Commander Ashlam Valorfist.  His base camp is located at Chillwind Camp, north of the Alterac Mountains.",
  [5067] = "In order to create the Leggings of Arcana, you will be required to bring the following items back to Malyfous Darkhammer: 1 Pristine Hide of the Beast; 5 Frayed Abomination Stitchings; 5 Arcanite Bars; 5 Frostwhisper's Embalming Fluid.  You will also be required to pay 50 gold pieces for the crafting of the item.",
  [5068] = "In order to create the Breastplate of Bloodthirst, you will be required to bring the following items back to Malyfous Darkhammer: 1 Pristine Hide of the Beast; 10 Frayed Abomination Stitchings; 5 Arcanite Bars; 5 Skin of Shadow.  You will also be required to pay 50 gold pieces for the crafting of the item.",
  [5081] = "Travel to Blackrock Spire and destroy War Master Voone, Highlord Omokk, and Overlord Wyrmthalak. Return to Marshal Maxwell when the job is done.",
  [5082] = "Donova Snowden in Winterspring wants you to kill 8 Winterfall Pathfinders, 8 Winterfall Den Watchers, and 8 Winterfall Totemics.",
  [5083] = "Bring the Empty Firewater Flask to Donova Snowden in Winterspring.",
  [5084] = "Search the Deadwood furbolg camp in northern Felwood for a clue.",
  [5085] = "Report back to Donova Snowden with your findings.",
  [5086] = "Collect 3 Toxic Horror Droplets for Donova Snowden in Winterspring.",
  [5087] = "Find the Winterfall Runners and stop them from delivering their shipment to Winterfall Village.",
  [5088] = "Slay Arikara. Bring her remains and the Incendia powder to Motega Firemane in Whitereach Post as proof of your deed.",
  [5089] = "Take General Drakkisath's Command to Marshal Maxwell in Burning Steppes.",
  [5090] = "Seek out Commander Ashlam Valorfist.  His base camp is located at Chillwind Camp, north of the Alterac Mountains.",
  [5091] = "Seek out Commander Ashlam Valorfist.  His base camp is located at Chillwind Camp, north of the Alterac Mountains.",
  [5092] = "Kill 10 Skeletal Flayers and 10 Slavering Ghouls in Sorrow Hill.  Return to Commander Ashlam Valorfist at Chillwind Camp, Western Plaguelands.",
  [5093] = "Seek out High Executor Derrington.  His base camp is located at the Bulwark, east of Tirisfal Glade and the Undercity.",
  [5094] = "Seek out High Executor Derrington.  His base camp is located at the Bulwark, east of Tirisfal Glade and the Undercity.",
  [5095] = "Seek out High Executor Derrington.  His base camp is located at the Bulwark, east of Tirisfal Glades and the Undercity.",
  [5096] = "Proceed to the Scarlet Crusade's base camp between Felstone Field and Dalson's Tears and destroy their command tent.  Place the Scourge banner at the camp, and then return to High Executor Derrington at the Bulwark, Western Plaguelands.",
  [5097] = "Using the Beacon Torch, mark each tower in Andorhal; you will need to stand in the doorway of the tower to successfully mark it.  Once all four towers are marked, return the Beacon Torch to Commander Ashlam Valorfist in Chillwind Camp, Western Plaguelands.",
  [5098] = "Using the Beacon Torch, mark each tower in Andorhal; you will need to stand in the doorway of the tower to successfully mark it.  Once all four towers are marked, return the Beacon Torch to High Executor Derrington at the Bulwark, Western Plaguelands.",
  [5101] = "Kill 6 sheep for Benny and then run like hell!     Just kidding... about the running part.",
  [5102] = "Travel to Blackrock Spire and destroy General Drakkisath. Return to Marshal Maxwell when the job is done.",
  [5103] = "Someone in this world must know what to do with these gauntlets. Good luck!",
  [5121] = "Donova Snowden in Winterspring wants you to defeat High Chief Winterfall.",
  [5123] = "Bring the Crudely-written Log to Donova Snowden in Winterspring.",
  [5124] = "Bring Malyfous Darkhammer 6 Enchanted Thorium Bars, 2 Essence of Fire, and 4 Star Rubies. You will also need to turn in your Unfired Plate Gauntlets.",
  [5126] = "Speak with Lorax. Listen to what he has to say.",
  [5127] = "Travel to Blackrock Spire and find Goraluk Anvilcrack. Slay him and then use the Blood Stained Pike upon his corpse. After his soul has been siphoned, the pike will be Soul Stained.  You must also find the Unforged Rune Covered Breastplate.  Return both the Soul Stained Pike and the Unforged Rune Covered Breastplate to Lorax in Winterspring.",
  [5128] = "Take the Crudely-written Log to Kelek Skykeeper in southern Felwood.",
  [5141] = "Bring 2 Tough Scorpid Breastplates, 2 Tough Scorpid Gloves, and 10 Worn Dragonscales to Peter Galen in Azshara.  Completing this quest will give you access to the Dragonscale Leatherworking arts.  The completion of this quest will prevent you from learning Elemental Leatherworking and Tribal Leatherworking; be sure this is the path you wish to follow before doing so.",
  [5142] = "Find Pamela Redpath.",
  [5143] = "Bring a Wild Leather Vest and a Wild Leather Helmet to Caryssia Moonhunter in Feralas.  Completing this quest will give you access to the Tribal Leatherworking arts.  The completion of this quest will prevent you from learning Dragonscale Leatherworking and Elemental Leatherworking; be sure this is the path you wish to follow before doing so.",
  [5144] = "Bring 2 Heart of Fire, 2 Globe of Water, 2 Core of Earth, and 2 Breath of Wind to Sarah Tanner in Searing Gorge.  Completing this quest will give you access to the Elemental Leatherworking arts.  The completion of this quest will prevent you from learning Dragonscale Leatherworking and Tribal Leatherworking; be sure this is the path you wish to follow before doing so.",
  [5145] = "Bring 2 Tough Scorpid Breastplates, 2 Tough Scorpid Gloves, and 10 Worn Dragonscales to Thorkaf Dragoneye in the Badlands.  Completing this quest will give you access to the Dragonscale Leatherworking arts.  The completion of this quest will prevent you from learning Elemental Leatherworking and Tribal Leatherworking; be sure this is the path you wish to follow before doing so.",
  [5146] = "Bring 2 Heart of Fire, 2 Globe of Water, 2 Core of Earth, and 2 Breath of Wind to Brumn Winterhoof in the Arathi Mountains.  Completing this quest will give you access to the Elemental Leatherworking arts.  The completion of this quest will prevent you from learning Dragonscale Leatherworking and Tribal Leatherworking; be sure this is the path you wish to follow before doing so.",
  [5147] = "Slay Arnak Grimtotem and bring proof of your deed to Cliffwatcher Longhorn in Freewind Post.",
  [5148] = "Bring a Wild Leather Vest and a Wild Leather Helmet to Se'Jib in Stranglethorn Vale.  Completing this quest will give you access to the Tribal Leatherworking arts.  The completion of this quest will prevent you from learning Dragonscale Leatherworking and Elemental Leatherworking; be sure this is the path you wish to follow before doing so.",
  [5149] = "Find Pamela's doll.",
  [5151] = "Slay the beast and bring back the Hypercapacitor Gizmo and Panther Cage Key to Wizlo Bearingshiner.",
  [5152] = "Speak with Marlene, south of the Ruins of Andorhal.",
  [5153] = "Bring Joseph's Wedding Ring to Chromie.",
  [5154] = "Bring the Annals of Darrowshire to Chromie in Andorhal.",
  [5155] = "Enter Jaedenar and slay 4 Jaedenar Hounds, 4 Jaedenar Guardsmen, 6 Jaedenar Adepts, and 6 Jaedenar Cultists before returning to Greta Mosshoof in Felwood.",
  [5156] = "Seek out and destroy 2 Entropic Beasts and 2 Entropic Horrors while exploring Shatter Scar Vale. After checking to see if the craters there are still filled with corrupt fel water, return to Taronn Redfeather in Felwood.",
  [5157] = "Take the Empty Canteen to the Moon Well in the center of Jaedenar and fill it before returning to Greta Mosshoof in Felwood.",
  [5158] = "Take the Corrupt Moon Well Water to Islen Waterseer in the Barrens.",
  [5159] = "Take the Purified Moon Well Water to Greta Mosshoof in Felwood.",
  [5160] = "Travel to Winterspring and find Haleh. Give her Awbee's scale.",
  [5161] = "Speak with Haleh if you wish to continue.",
  [5162] = "Speak with Jeziba in the Plaguelands. He resides in Andorhal.",
  [5163] = "Take Umi's Mechanical Yeti and scare her friends with it:  Legacki in Everlook (Winterspring) Sprinkle in Gadgetzan (Tanaris) Quixxil in Marshal's Refuge (Un'Goro Crater)  When you are done, bring the Mechanical Yeti back to Umi.",
  [5164] = "Read from the Catalogue of the Wayward.",
  [5165] = "Using the Purified Moon Well Water, douse the flames of the four braziers of protection within Shadow Hold in Felwood, then return to Greta Mosshoof in the Emerald Sanctuary.",
  [5166] = "To forge the Breastplate of the Chromatic Flight, you will be required to bring the following items to Jeziba the 'Sculptor':  1 Chromatic Carapace.  10 Brilliant Chromatic Scales.  10 Blood of Heroes.  10 Frayed Abomination Stitchings.",
  [5167] = "To forge the Legplates of the Chromatic Defier, you will be required to bring the following items to Jeziba the 'Sculptor':  1 Chromatic Carapace.  10 Brilliant Chromatic Scales.  10 Blood of Heroes.  5 Skin of Shadow.",
  [5168] = "Bring Davil's Libram and Redpath's Shield to Carlin Redpath.",
  [5181] = "Bring the Skull of Horgus and the Shattered Sword of Marduk to Carlin Redpath at Light's Hope Chapel.",
  [5201] = "Rivern Frostwind wants you to slay 5 Winterfall Shaman and 5 Winterfall Ursa.",
  [5202] = "Search through Jaedenar to discover what the Blood Red Key is used for.",
  [5203] = "Escort Arko'narin to where Lightforge and her equipment are being held, and then protect her as you escape Shadow Hold. Afterwards, seek out Jessir Moonbow in Felwood to let her know what's happened to her friends.",
  [5204] = "Return to Jaedenar and kill the succubus Rakaiah before finding the Remains of Trey Lightforge.",
  [5206] = "Bring 5 Resonating Skulls and the Mystic Crystal to Carlin Redpath in Eastern Plaguelands.",
  [5210] = "Bring the Extended Annals of Darrowshire to Carlin Redpath in Eastern Plaguelands.",
  [5211] = "Free 15 Darrowshire Spirits and return to Carlin Redpath.",
  [5212] = "Recover 20 Plagued Flesh Samples from Stratholme and return them to Betina Bigglezink. You suspect that any creature in Stratholme would have said flesh sample.",
  [5213] = "Travel to Stratholme and search the ziggurats. Find and return new Scourge Data to Betina Bigglezink.",
  [5214] = "Find Halric Emberlain's smoke shop in Stratholme and recover a box of Emberlain's Premium Tobacco. Return to Smokey LaRue when the job is done.",
  [5215] = "Speak with High Priestess MacDonnell at Chillwind Point, Western Plaguelands.",
  [5216] = "Go to Felstone Field in Western Plaguelands to locate and defeat the Cauldron Lord present there.  It may have a key that will allow access to the cauldron.  You must have the Empty Felstone Field Bottle with you to secure a sample of the poisons used inside the cauldron.",
  [5217] = "Bring the Filled Felstone Field Bottle to High Priestess MacDonnell at Chillwind Camp, Western Plaguelands.",
  [5219] = "Go to Dalson's Tears in Western Plaguelands to locate and defeat the Cauldron Lord present there, and use its key to gain access to the cauldron.  You must have the Empty Dalson's Tears Bottle with you to secure a sample of the poisons used inside the cauldron.",
  [5220] = "Bring the Filled Dalson's Tears Bottle to High Priestess MacDonnell at Chillwind Camp, Western Plaguelands.",
  [5222] = "Go to the Writhing Haunt in Western Plaguelands to locate and defeat the Cauldron Lord present there, and use its key to gain access to the cauldron.  You must have the Empty Writhing Haunt Bottle with you to secure a sample of the poisons used inside the cauldron.",
  [5223] = "Bring the Filled Writhing Haunt Bottle to High Priestess MacDonnell at Chillwind Camp, Western Plaguelands.",
  [5225] = "Go to Gahrron's Withering in Western Plaguelands to locate and defeat the Cauldron Lord present there, and use its key to gain access to the cauldron.  You must have the Empty Gahrron's Withering Bottle with you to secure a sample of the poisons used inside the cauldron.",
  [5226] = "Bring the Filled Gahrron's Withering Bottle to High Priestess MacDonnell at Chillwind Camp, Western Plaguelands.",
  [5228] = "Speak with Shadow Priestess Vandis at the Bulwark, Western Plaguelands.",
  [5229] = "Go to Felstone Field in Western Plaguelands to locate and defeat the Cauldron Lord present there.  It may have a key that will allow access to the cauldron.  You must have the Empty Felstone Field Bottle with you to secure a sample of the poisons used inside the cauldron.",
  [5230] = "Bring the Filled Felstone Field Bottle to Shadow Priestess Vandis at the Bulwark, Western Plaguelands.",
  [5231] = "Go to Dalson's Tears in Western Plaguelands to locate and defeat the Cauldron Lord present there, and use its key to gain access to the cauldron.  You must have the Empty Dalson's Tears Bottle with you to secure a sample of the poisons used inside the cauldron.",
  [5232] = "Bring the Filled Dalson's Tears Bottle to Shadow Priestess Vandis at the Bulwark, Western Plaguelands.",
  [5233] = "Go to the Writhing Haunt in Western Plaguelands to locate and defeat the Cauldron Lord present there, and use its key to gain access to the cauldron.  You must have the Empty Writhing Haunt Bottle with you to secure a sample of the poisons used inside the cauldron.",
  [5234] = "Bring the Filled Writhing Haunt Bottle to Shadow Priestess Vandis at The Bulwark, Western Plaguelands.",
  [5235] = "Go to Gahrron's Withering in Western Plaguelands to locate and defeat the Cauldron Lord present there, and use its key to gain access to the cauldron.  You must have the Empty Gahrron's Withering Bottle with you to secure a sample of the poisons used inside the cauldron.",
  [5236] = "Bring the Filled Gahrron's Withering Bottle to Shadow Priestess Vandis at the Bulwark, Western Plaguelands.",
  [5241] = "Find Carlin Redpath.",
  [5242] = "Kill Moora and Salia, and bring Shadow Lord Fel'dan's Head to Greta Mosshoof in Felwood.",
  [5243] = "Travel to Stratholme, in the north. Search the supply crates that litter the city and recover 5 Stratholme Holy Water. Return to Leonid Barthalomew the Revered when you have collected enough of the blessed fluid.",
  [5244] = "Speak with Jaron Stoneshaper in Starfall Village.",
  [5245] = "Use Jaron's Pick to find the four Highborne Relic Fragments. Bring them to Aurora Skycaller in Eastern Plaguelands.",
  [5246] = "Find the Sacred Highborne Writings in the Temple of Zin-Malor in Azshara, and bring them to Aurora Skycaller near the Northpass Tower in Eastern Plaguelands.",
  [5247] = "Bring an Enchanted Thorium Bar, 5 Crystal Restore, and a Vial of Dire Water to Aurora Skycaller near the Northpass Tower in Eastern Plaguelands.",
  [5248] = "Take the Crystal of Zin-Malor to Lake Kel'Theril in Winterspring and find a highborne spirit that will speak to you.",
  [5249] = "Find Starfall Village in Winterspring and speak with Wynd Nightchaser.",
  [5250] = "Find Starfall in Winterspring and speak with Wynd Nightchaser.",
  [5251] = "Travel to Stratholme and find Archivist Galford of the Scarlet Crusade. Destroy him and burn down the Scarlet Archive.",
  [5252] = "Speak with Wynd Nightchaser in Starfall Village, and ask about the proper place for the Crystal of Zin-Malor.",
  [5253] = "Deliver the Crystal of Zin-Malor to Arch Druid Fandral Staghelm in Darnassus.",
  [5261] = "Speak with Eagan Peltskinner.",
  [5262] = "Take the Head of Balnazzar to Duke Nicholas Zverenhoff in the Eastern Plaguelands.",
  [5263] = "Venture to Stratholme and destroy Baron Rivendare. Take his head and return to Duke Nicholas Zverenhoff.",
  [5264] = "Speak with Lord Maxwell Tyrosus. He is inside the church.",
  [5265] = "Open the Argent Hold and claim your reward.",
  [5281] = "Find Egan. You only know that he was last seen around Stratholme.",
  [5282] = "Use Egan's Blaster on the ghostly and spectral citizens of Stratholme. When the restless souls break free from their ghostly shells, use the blaster again - freedom will be theirs!  Free 15 Restless Souls and return to Egan.",
  [5283] = "To become an Armorsmith, you must make the following items and return them to Grumnus: 4 Ornate Mithril Helms, 2 Ornate Mithril Boots, 1 Ornate Mithril Breastplate.",
  [5284] = "To become a Weaponsmith, you must make the following items and return them to Ironus: 4 Moonsteel Broadswords, 4 Massive Iron Axes, 2 Heavy Mithril Axes, and 2 Big Black Maces.",
  [5301] = "To become an armorsmith, you must make the following items and return them to Okothos: 4 Ornate Mithril Helms, 2 Ornate Mithril Boots, 1 Ornate Mithril Breastplate.",
  [5302] = "To become a Weaponsmith, you must make the following items and return them to Borgosh: 4 Moonsteel Broadswords, 4 Massive Iron Axes, 2 Heavy Mithril Axes, and 2 Big Black Maces.",
  [5305] = "Travel to Stratholme and kill the Crimson Hammersmith. Recover the Crimson Hammersmith's Apron and return to Lilith.",
  [5306] = "Travel to Blackrock Spire and slay Shadow Hunter Vosh'gajin. Recover Vosh'gajin's Snakestone and return to Kilram.",
  [5307] = "Find the Black Guard Swordsmith in Stratholme and destroy him. Recover the Insignia of the Black Guard and return to Seril Scourgebane.",
  [5321] = "Escort Kerlonian Evershade to Liladris Moonriver at Maestra's Post in Ashenvale.",
  [5341] = "Venture to the Scholomance and recover the Barov family fortune. Four deeds make up this fortune: The Deed to Caer Darrow; The Deed to Brill; The Deed to Tarren Mill; and The Deed to Southshore. Return to Alexi Barov when you have completed this task.",
  [5342] = "Travel to Chillwind Camp - Alliance territory - and assassinate Weldon Barov. Take his head and return to Alexi Barov.  Be warned, Weldon will probably be well protected by Alliance scum.",
  [5343] = "Venture to the Scholomance and recover the Barov family fortune. Four deeds make up this fortune: The Deed to Caer Darrow; The Deed to Brill; The Deed to Tarren Mill; and The Deed to Southshore. Return to Weldon Barov when you have completed this task.",
  [5344] = "Travel to the Bulwark - Horde territory - and assassinate Alexi Barov. Take his head and return to Weldon Barov.  Be warned, Alexi will probably be well protected by Horde filth.",
  [5361] = "Deliver Cliffwatcher Longhorn Report to Nataka Longhorn at Ghost Walker Post in Desolace.",
  [5381] = "Retrieve the Demon Box from Thunder Axe Fortress, and return it, along with the Demon Pick to Taiga Wisemane in Shadowprey Village.",
  [5382] = "Find Doctor Theolen Krastinov inside the Scholomance. Destroy him, then burn the Remains of Eva Sarkhoff and the Remains of Lucien Sarkhoff. Return to Eva Sarkhoff when the task is complete.",
  [5383] = "Take the Bag of Horrors to Eva Sarkhoff on Caer Darrow.",
  [5384] = "Return to the Scholomance with the Blood of Innocents. Find the porch and place the Blood of Innocents in the brazier. Kirtonos will come to feast upon your soul.  Fight valiantly, do not give an inch! Destroy Kirtonos and return to Eva Sarkhoff.",
  [5385] = "Return the Remains of Trey Lightforge to Jessir Moonbow in Felwood.",
  [5386] = "Talk to Jinar'Zillen at Shadowprey Village, and then bring Nataka Longhorn 2 Bloodbelly fish.",
  [5441] = "Use the Foreman's Blackjack on Lazy Peons when they're sleeping.  Wake up 5 peons, then return the Foreman's Blackjack to Foreman Thazz'ril in the Valley of Trials.",
  [5461] = "Travel to the Arathi Highlands, to the ruins of Stromgarde. Search Stromgarde for a Keepsake of Remembrance. If you find such an item, return with it to Magistrate Marduke.",
  [5462] = "Travel to Light's Hope in Eastern Plaguelands and seek out Leonid Barthalomew the Revered. Show him the Keepsake of Remembrance and tell him all that you have discovered.",
  [5463] = "Travel to Stratholme and find Menethil's Gift. Place the Keepsake of Remembrance upon the unholy ground. ",
  [5464] = "Take the Soulbound Keepsake to Leonid Barthalomew in Eastern Plaguelands.",
  [5465] = "Return to Magistrate Marduke in Caer Darrow. Show him the Soulbound Keepsake.",
  [5466] = "Find Ras Frostwhisper in the Scholomance. When you have found him, use the Soulbound Keepsake on his undead visage. Should you succeed in reverting him to a mortal, strike him down and recover the Human Head of Ras Frostwhisper. Take the head back to Magistrate Marduke.",
  [5481] = "Collect 3 Gloom Weed and deliver them to Junior Apothecary Holland in the Brill graveyard.",
  [5482] = "Collect 10 Doom Weed and deliver them back to Junior Apothecary Holland.",
  [5501] = "Bring 10 Kodo Bones from the Kodo Graveyard to Bibbly F'utzbuckle at Kormek's Hut.",
  [5502] = "Return your ward to the Orgrimmar orphanage by handing in the Orcish Orphan Whistle to Orphan Matron Battlewail in the Valley of Honor.",
  [5504] = "Bring 10 Argent Dawn Valor Tokens to Quartermaster Hasana at the Bulwark, Western Plaguelands.",
  [5507] = "Bring 10 Argent Dawn Valor Tokens to Quartermaster Lightspark at Chillwind Camp, Western Plaguelands.",
  [5513] = "Bring 10 Argent Dawn Valor Tokens to Quartermaster Breechlock at Light's Hope Chapel, Eastern Plaguelands.",
  [5514] = "Bring the Imbued Skeletal Fragments and 15 gold coins to Krinkle Goodsteel in Gadgetzan.",
  [5515] = "Locate Jandice Barov in the Scholomance and destroy her. From her corpse recover Krastinov's Bag of Horrors. Return the bag to Eva Sarkhoff.",
  [5517] = "Bring 25 Argent Dawn Valor Tokens to Quartermaster Breechlock at Light's Hope Chapel, Eastern Plaguelands.",
  [5518] = "Bring 4 Bolts of Runecloth, 8 Rugged Leather, 2 Rune Threads, and Ogre Tannin to Knot Thimblejack.  He is currently chained inside the Gordok wing of Dire Maul.",
  [5521] = "Bring 25 Argent Dawn Valor Tokens to Quartermaster Lightspark at Chillwind Camp, Western Plaguelands.",
  [5522] = "Bring the Frozen Eggs to Leonid Barthalomew in the Eastern Plaguelands.",
  [5524] = "Bring 25 Argent Dawn Valor Tokens to Quartermaster Hasana at the Bulwark or Quartermaster Lightspark at Chillwind Camp, Western Plaguelands or Quartermaster Breechlock at Light's Hope Chapel, Eastern Plaguelands.",
  [5526] = "Find the Felvine in Dire Maul and acquire a shard from it.  Chances are you'll only be able to procure one with the demise of Alzzin the Wildshaper.  Use the Reliquary of Purity to securely seal the shard inside, and return it to Rabine Saturna in Nighthaven, Moonglade.",
  [5527] = "Travel to Silithus and search for a Reliquary of Purity within the ruins of Southwind Village.  If you are able to find it, return with it to Rabine Saturna in Nighthaven, Moonglade.",
  [5529] = "Kill 20 Plagued Hatchlings, then return to Betina Bigglezink at the Light's Hope Chapel.",
  [5531] = "Bring the Frozen Eggs to Betina Bigglezink.",
  [5533] = "Speak with Alchemist Arbington at Chillwind Point, Western Plaguelands.",
  [5534] = "Find Some Rune that the naga have in their possession in the Ruins of Eldarath and return it to Kim'jael in Azshara.",
  [5535] = "Destroy 6 Highborne Apparitions and 6 Highborne Lichlings before returning to Loh'atu in Azshara.",
  [5536] = "Kill 6 Haldarr Satyr, 2 Haldarr Tricksters, 2 Haldarr Felsworn and then return to Loh'atu on the border of Ashenvale.",
  [5537] = "Bring 15 Skeletal Fragments to Alchemist Arbington at Chillwind Point, Western Plaguelands.",
  [5538] = "Bring the Imbued Skeletal Fragments and 15 gold coins to Krinkle Goodsteel in Gadgetzan.",
  [5541] = "Bring Rumbleshot's Ammo to Hegnar Rumbleshot in Dun Morogh.",
  [5542] = "Slay 20 Plaguehound Runts, 5 Plaguehounds and 5 Frenzied Plaguehounds. Return to Tirion Fordring when the task is complete.",
  [5543] = "Slay 30 Plaguebats and return to Tirion Fordring.",
  [5544] = "Seek out the Carrion Grubs and Devourers of the region. Slay them and harvest their meat. Return to Tirion Fordring when you have gathered 15 Slabs of Carrion Worm Meat.",
  [5545] = "Bring 8 Bundles of Wood to Raelen at the Eastvale Logging Camp.",
  [5561] = "Bring five Tamed Kodos and the Kodo Kombobulator back to Smeed Scrabblescrew at Scrabblescrew's Camp.",
  [5581] = "Banish 6 Portals at Mannoroc Coven and return to Taiga Wisemane at Shadowprey Village.",
  [5582] = "Bring the Healthy Dragon Scale to Betina Bigglezink at the Light's Hope Chapel in Eastern Plaguelands.",
  [5601] = "Find Pamela Redpath in Darrowshire.",
  [5621] = "Find Sentinel Shaya and heal her wounds using Lesser Heal (Rank 2). Afterwards, grant her Power Word: Fortitude and then return to Laurna Morninglight in Dolanaar.",
  [5622] = "Speak to Laurna Morninglight in Teldrassil.",
  [5623] = "Speak to Priestess Josetta in Elwynn Forest.",
  [5624] = "Find Guard Roberts and heal his wounds using Lesser Heal (Rank 2). Afterwards, grant him Power Word: Fortitude and then return to Priestess Josetta in Goldshire.",
  [5625] = "Find Mountaineer Dolf and heal his wounds using Lesser Heal (Rank 2). Afterwards, grant him Power Word: Fortitude and then return to Maxan Anvol in Kharanos.",
  [5626] = "Speak to Maxan Anvol in Dun Morogh.",
  [5628] = "Speak to Priestess Alathea in Darnassus.",
  [5629] = "Speak to Priestess Alathea in Darnassus.",
  [5630] = "Speak to Priestess Alathea in Darnassus.",
  [5631] = "Speak to Priestess Alathea in Darnassus.",
  [5632] = "Speak to Priestess Alathea in Darnassus.",
  [5633] = "Speak to Priestess Alathea in Darnassus.",
  [5635] = "Speak to High Priestess Laurena in Stormwind.",
  [5636] = "Speak to High Priestess Laurena in Stormwind.",
  [5637] = "Speak to High Priestess Laurena in Stormwind.",
  [5638] = "Speak to High Priestess Laurena in Stormwind.",
  [5639] = "Speak to High Priestess Laurena in Stormwind.",
  [5640] = "Speak to High Priestess Laurena in Stormwind.",
  [5642] = "Speak to Ur'kyo in Orgrimmar.",
  [5643] = "Speak to Ur'kyo in Orgrimmar.",
  [5644] = "Speak to Aelthalyste in the Undercity.",
  [5645] = "Speak to High Priest Rohan in Ironforge.",
  [5646] = "Speak to Aelthalyste in the Undercity.",
  [5647] = "Speak to High Priest Rohan in Ironforge.",
  [5648] = "Find Grunt Kor'ja and heal her wounds using Lesser Heal (Rank 2). Afterwards, grant her Power Word: Fortitude and then return to Tai'jin at Razor Hill.",
  [5649] = "Speak to Tai'jin in Durotar.",
  [5650] = "Find Deathguard Kel and heal his wounds using Lesser Heal (Rank 2). Afterwards, grant him Power Word: Fortitude and then return to Dark Cleric Beryl in Brill.",
  [5651] = "Speak to Dark Cleric Beryl in Tirisfal Glades.",
  [5654] = "Speak to Ur'kyo in Orgrimmar.",
  [5655] = "Speak to Ur'kyo in Orgrimmar.",
  [5656] = "Speak to Ur'kyo in Orgrimmar.",
  [5657] = "Speak to Ur'kyo in Orgrimmar.",
  [5659] = "Speak to Aelthalyste in the Undercity.",
  [5660] = "Speak to Aelthalyste in the Undercity.",
  [5661] = "Speak to Aelthalyste in the Undercity.",
  [5662] = "Speak to Aelthalyste in the Undercity.",
  [5663] = "Speak to Aelthalyste in the Undercity.",
  [5673] = "Speak to Priestess Alathea in Darnassus.",
  [5674] = "Speak to Priestess Alathea in Darnassus.",
  [5675] = "Speak to Priestess Alathea in Darnassus.",
  [5677] = "Speak to High Priestess Laurena in Stormwind.",
  [5678] = "Speak to High Priestess Laurena in Stormwind.",
  [5713] = "Protect Sentinel Aynasha, then speak with Onaeya at Maestra's Post in Ashenvale.",
  [5721] = "Place the Relic Bundle at the Darrowshire town square.  Prevent Davil Lightfire's death until the death of Horgus.  Prevent Captain Redpath's death until Redpath the Corrupted appears.  Defeat Redpath the Corrupted.  Speak with the spirit of Joseph Redpath when he appears at the town square, then speak with Pamela at her home.",
  [5722] = "Search Ragefire Chasm for Maur Grimtotem's corpse and search it for any items of interest.",
  [5723] = "Search Orgrimmar for Ragefire Chasm, then kill 8 Ragefire Troggs and 8 Ragefire Shaman before returning to Rahauro in Thunder Bluff.",
  [5724] = "Take the Grimtotem Satchel to Rahauro in Thunder Bluff.",
  [5725] = "Bring the books Spells of Shadow and Incantations from the Nether to Varimathras in Undercity.",
  [5726] = "Bring a Lieutenant's Insignia to Thrall in Orgrimmar.",
  [5727] = "Take the Lieutenant's Insignia to Neeru Fireblade and speak to him. Gauge if he believes you are a member of the Burning Blade and then return to Thrall in Orgrimmar.",
  [5728] = "Kill Bazzalan and Jergosh the Invoker before returning to Thrall in Orgrimmar.",
  [5729] = "Speak to Neeru Fireblade in Orgrimmar.",
  [5730] = "Speak to Thrall in Orgrimmar and tell him what you've learned.",
  [5741] = "Get the Sceptre of Light and then return it to Azore Aldamort at the tower in Ethel Rethor.",
  [5742] = "Listen to what Tirion Fordring has to say.",
  [5761] = "Enter Ragefire Chasm and slay Taragaman the Hungerer, then bring his heart back to Neeru Fireblade in Orgrimmar.",
  [5762] = "Take Kravel's Crate to Hemet Nesingwary in Stranglethorn.",
  [5763] = "Bring Roon's Kodo Horn to Hemet Nesingwary in Stranglethorn.",
  [5781] = "Travel to the Undercroft - at the southernmost section of the Eastern Plaguelands - and recover Taelan's Hammer. Return to Tirion Fordring upon completion of your objective.",
  [5801] = "Take the Skeleton Key Mold and 2 Thorium Bars to the top of Fire Plume Ridge in Un'Goro Crater.  Use the Skeleton Key Mold by the lava lake to forge the Unfinished Skeleton Key.  Bring the Unfinished Skeleton Key to Alchemist Arbington at Chillwind Point, Western Plaguelands.",
  [5802] = "Take the Skeleton Key Mold and 2 Thorium Bars to the top of Fire Plume Ridge in Un'Goro Crater.  Use the Skeleton Key Mold by the lava lake to forge the Unfinished Skeleton Key.  Bring the Unfinished Skeleton Key to Apothecary Dithers at the Bulwark, Western Plaguelands.",
  [5803] = "Destroy Araj the Summoner and bring Araj's Scarab to Alchemist Arbington at Chillwind Point, Western Plaguelands.",
  [5804] = "Destroy Araj the Summoner and bring Araj's Scarab to Apothecary Dithers at the Bulwark, Western Plaguelands.",
  [5805] = "Bring the Northshire Gift Voucher to Merissa Stilwell.",
  [5821] = "Escort the Gizelton Caravan past the Kolkar Centaur village. Talk with Smeed at Scrabblescrew's Camp for your reward.",
  [5841] = "Bring the Coldridge Valley Gift Voucher to Yori Crackhelm.",
  [5842] = "Bring the Shadowglen Gift Voucher to Orenthil Whisperwind.",
  [5843] = "Bring the Valley of Trials Gift Voucher to Magga.",
  [5844] = "Bring the Camp Narache Gift Voucher to Vorn Skyseer.",
  [5845] = "Travel to Northdale, in the northeastern region of the Eastern Plaguelands, and recover the Symbol of Lost Honor. Return to Tirion Fordring upon completion of your objective.",
  [5846] = "Travel to island of Caer Darrow, in the south-central region of the Plaguelands, and look for any clues as to the whereabouts of the painting.",
  [5847] = "Bring the Deathknell Gift Voucher to Claire Willower in Deathknell.",
  [5848] = "Travel to Stratholme, in the northern part of the Plaguelands. It is in the Scarlet Bastion that you will find the painting 'Of Love and Family,' hidden behind another painting depicting the twin moons of our world.  Return the painting to Tirion Fordring.",
  [5861] = "Travel to Uther's Tomb, located in the southern Plaguelands. Show Myranda the Hag Tirion's Gift.",
  [5862] = "Speak to Myranda to gain the Scarlet Illusion. Travel to Hearthglen while under the Scarlet Illusion and deliver Tirion's Gift to Highlord Taelan Fordring.  Hearthglen is to the north, Taelan should be inside of Mardenholde Keep.",
  [5863] = "Andi Lynn in Gadgetzan wants you to destroy the Dunemaul Compound by killing 10 Dunemaul Brutes, 10 Dunemaul Enforcers, and Gor'marok the Ravager.",
  [5881] = "Maggran wishes you to deliver a letter to Grish Longrunner at the Great Lift in the Barrens.",
  [5892] = "Bring 10 Irondeep Supplies to the Alliance Quartermaster in Dun Baldar.",
  [5893] = "Bring 10 Coldtooth Supplies to the Horde Quatermaster in Frostwolf Keep.",
  [5901] = "Use the Empty Termite Jar on the Termite Mounds in Eastern Plaguelands. After you've gathered 100 Plagueland Termites, return to Mickey Levine at the Bulwark in Tirisfal Glades.",
  [5902] = "Find someplace suitable in the center of the Northridge Lumber Mill in Western Plaguelands to place the Barrel of Plagueland Termites.",
  [5903] = "Use the Empty Termite Jar on the Termite Mounds in Eastern Plaguelands. After you've gathered 100 Plagueland Termites, return to Nathaniel Dumah at Chillwind Camp in Western Plaguelands.",
  [5904] = "Find someplace suitable in the center of the Northridge Lumber Mill in Western Plaguelands to place the Barrel of Plagueland Termites.",
  [5921] = "Use the spell \"Teleport: Moonglade\" to travel to Moonglade.  When you arrive, speak with Dendrite Starblaze in the village of Nighthaven.",
  [5922] = "Use the spell \"Teleport: Moonglade\" to travel to Moonglade.  When you arrive, speak with Dendrite Starblaze in the village of Nighthaven.",
  [5923] = "Speak with Mathrengyl Bearwalker in the Cenarion Enclave, Darnassus.",
  [5924] = "Speak with Mathrengyl Bearwalker in the Cenarion Enclave, Darnassus.",
  [5925] = "Speak with Mathrengyl Bearwalker in the Cenarion Enclave, Darnassus.",
  [5926] = "Speak with Turak Runetotem on the Elder Rise of Thunder Bluff.",
  [5927] = "Speak with Turak Runetotem on the Elder Rise of Thunder Bluff.",
  [5928] = "Speak with Turak Runetotem on the Elder Rise of Thunder Bluff.",
  [5929] = "Seek out the Great Bear Spirit in northwestern Moonglade and learn what it has to share with you about the nature of the bear.  When finished, return to Dendrite Starblaze in Nighthaven, Moonglade.",
  [5930] = "Seek out the Great Bear Spirit in northwestern Moonglade and learn what it has to share with you about the nature of the bear.  When finished, return to Dendrite Starblaze in Nighthaven, Moonglade.",
  [5931] = "Return to Darnassus and speak with Mathrengyl Bearwalker in the Cenarion Enclave.",
  [5932] = "Return to Thunder Bluff and speak with Turak Runetotem on the Elder Rise.",
  [5941] = "Take the Bundle of Relics to Chromie in Andorhal.",
  [5942] = "Bring Joseph's Key to Joseph's Chest.",
  [5943] = "Escort the Gizelton Caravan through Mannoroc Coven. Talk with Smeed at Scrabblescrew's Camp for your reward.",
  [5944] = "Escort Taelan Fordring out of Hearthglen.",
  [5961] = "Speak with Nathanos Blightcaller in the Eastern Plaguelands. He is said to have taken up residence at the Marris Stead.",
  [5981] = "Rivern Frostwind wants you to kill 4 Frostmaul Giants and 4 Frostmaul Preservers.",
  [6000] = "Announces you to Gakin the Darkbinder in the Magic quarter of Stormwind.",
  [6001] = "Use the Cenarion Moondust on the Moonkin Stone of Auberdine to bring forth Lunaclaw.  From there, you must face Lunaclaw and earn the strength of body and heart it possesses.  Speak with Mathrengyl Bearwalker in Darnassus when you are done.",
  [6002] = "Use the Cenarion Lunardust on the Moonkin Stone between Mulgore and the Barrens to bring forth Lunaclaw.  From there, you must face Lunaclaw and earn the strength of body and heart it possesses.  Speak with Turak Runetotem in Thunder Bluff when you are done.",
  [6004] = "Kill 2 Scarlet Medics, 2 Scarlet Hunters, 2 Scarlet Magi and 2 Scarlet Knights before returning to Kirsta Deepshadow in Western Plaguelands.",
  [6021] = "Bring Zaeldarr's Head to Caretaker Alen at Light's Hope Chapel.",
  [6022] = "Travel to Corin's Crossing to the east and slaughter the Scourge that inhabit the town. Collect 7 pieces of Living Rot in under 10 minutes. Use the Mortar and Pestle to grind the Living Rot into Coagulated Rot.",
  [6023] = "Kill Huntsman Radley and Cavalier Durgen before returning to Kirsta Deepshadow in Western Plaguelands.",
  [6024] = "Kill Infiltrator Hameya.  Use his key on the Mound of Dirt behind the Undercroft.",
  [6025] = "Enter Hearthglen and find a high vantage point from which you can see the town and gauge the Scarlet Crusade's forces, then return to Kirsta Deepshadow in Western Plaguelands.",
  [6026] = "Smokey LaRue wants you to get 2 Thorium Bars, 1 Golden Rod, 8 Hi-Explosive Bombs, and 8 Unstable Triggers.  You will have to find a blacksmith and an engineer for these items.",
  [6027] = "Get the Book of the Ancients and return it to Azore Aldamort at the tower in Ethel Rethor.",
  [6028] = "Deliver the Everlook Report to Argent Officer Pureheart at Chillwind Camp, Western Plaguelands.",
  [6029] = "Deliver the Everlook Report to Argent Officer Garush at the Bulwark, Western Plaguelands.",
  [6030] = "Deliver the book, \"Studies in Spirit Speaking\", to Duke Nicholas Zverenhoff at Light's Hope Chapel, Eastern Plaguelands.",
  [6031] = "Bring 30 Runecloth to Meilosh in Timbermaw Hold.",
  [6032] = "Bring 2 Mooncloth to Meilosh in Timbermaw Hold.",
  [6041] = "Travel to Plaguewood, northwest of Light's Hope. Destroy 8 Scourge Structures by using Smokey's Special Compound at the Mark of Detonation planted inside each building. Smokey has had the Ziggurats and Slaughterhouses marked.  Once you plant the bomb, leave the building and marvel at your handiwork.  By the way, Smokey's Special Compound is rather... unstable.",
  [6042] = "Slay 20 Noxious Plaguebats and 10 Monstrous Plaguebats. Return to Nathanos Blightcaller when you are finished.",
  [6061] = "Use the Taming Rod to tame an Adult Plainstrider. Practice your skills, then return the Taming Rod to Yaw Sharpmane in Bloodhoof Village.",
  [6062] = "Use the Taming Rod to tame a Dire Mottled Boar. Practice your skills, then return the Taming Rod to Thotar in Razor Hill.",
  [6063] = "Use the Taming Rod to tame a Webwood Lurker. Practice your skills, then return the Taming Rod to Dazalar in Dolanaar.",
  [6064] = "Use the Taming Rod to tame a Large Crag Boar. Practice your skills, then return the Taming Rod to Grif Wildheart in Kharanos.",
  [6065] = "Speak with Yaw Sharpmane in Bloodhoof Village.",
  [6066] = "Speak with Yaw Sharpmane in Bloodhoof Village.",
  [6067] = "Speak with Yaw Sharpmane in Bloodhoof Village.",
  [6068] = "Speak with Thotar at Razor Hill.",
  [6069] = "Speak with Thotar at Razor Hill.",
  [6070] = "Speak with Thotar at Razor Hill.",
  [6071] = "Speak with Dazalar in Dolanaar.",
  [6072] = "Speak with Dazalar in Dolanaar.",
  [6073] = "Speak with Dazalar in Dolanaar.",
  [6074] = "Speak with Grif Wildheart in Kharanos.",
  [6075] = "Speak with Grif Wildheart in Kharanos.",
  [6076] = "Speak with Grif Wildheart in Kharanos.",
  [6081] = "Speak with Ormak Grimshot in Orgrimmar.",
  [6082] = "Use the Taming Rod to tame an Armored Scorpid. Practice your skills, then return to Thotar at Razor Hill.",
  [6083] = "Use the Taming Rod to tame a Surf Crawler. Practice your skills, then return the Taming Rod to Thotar at Razor Hill.",
  [6084] = "Use the Taming Rod to tame a Snow Leopard. Practice your skills, then return to Grif Wildheart in Kharanos.",
  [6085] = "Use the Taming Rod to tame an Ice Claw Bear. Practice your skills, then return the Taming Rod to Grif Wildheart in Kharanos.",
  [6086] = "Speak with Belia Thundergranite in Ironforge.",
  [6087] = "Use the Taming Rod to tame a Prairie Stalker. Practice your skills, then return the Taming Rod to Yaw Sharpmane in Bloodhoof Village.",
  [6088] = "Use the Taming Rod to tame a Swoop. Practice your skills, then return the Taming Rod to Yaw Sharpmane in Bloodhoof Village.",
  [6089] = "Speak with Holt Thunderhorn on Hunter Rise in Thunder Bluff.",
  [6101] = "Use the Taming Rod to tame a Nightsaber Stalker. Practice your skills, then return the Taming Rod to Dazalar in Dolanaar.",
  [6102] = "Use the Taming Rod to tame a Strigid Screecher. Practice your skills, then return the Taming Rod to Dazalar in Dolanaar.",
  [6103] = "Speak to Jocaste in the Cenarion Enclave, in Darnassus.",
  [6121] = "Travel to Moonglade and speak with Dendrite Starblaze in the village of Nighthaven.",
  [6122] = "Use the Empty Cliffspring Falls Sampler to draw a sample of water from the mouth of the cave by the falls.  Deliver the Filled Cliffspring Falls Sampler to Alanndarian Nightsong in Auberdine, Darkshore.",
  [6123] = "Bring 5 Earthroot and 12 Lunar Funguses to Alanndarian Nightsong in Auberdine so she may make a curative salve.",
  [6124] = "Use the Curative Animal Salve on 10 Sickly Deer that are located throughout Darkshore; doing so should cure them.  Sickly Deer have been reported starting south of the Cliffspring River to the north of Auberdine and extending all the way into southern Darkshore where the edge of Ashenvale begins.",
  [6125] = "Return to Mathrengyl Bearwalker in the Cenarion Enclave, Darnassus.",
  [6126] = "Travel to Moonglade and speak with Dendrite Starblaze in the village of Nighthaven.",
  [6127] = "Use the Empty Dreadmist Peak Sampler to draw a sample of water from a pool at the top of the peak.  Deliver the Filled Dreadmist Peak Sampler to Tonga Runetotem at the Crossroads, Barrens.",
  [6128] = "Bring 5 Earthroot and 5 Kodo Horns to Tonga Runetotem at the Crossroads so he may make a curative salve.",
  [6129] = "Use the Curative Animal Salve on 10 Sickly Gazelles that are located throughout the northern part of the Barrens; doing so should cure them.  Sickly Gazelles have been reported north of the east-west road that runs through the Crossroads.",
  [6130] = "Return to Turak Runetotem on the Elder Rise, Thunder Bluff.",
  [6131] = "Grazle wants you to prove yourself by killing 5 Deadwood Warriors, 5 Deadwood Pathfinders, and 5 Deadwood Gardeners.",
  [6132] = "Escort Melizza Brimbuzzle, then speak with Hornizz Brimbuzzle at the Kodo Graveyard in Desolace.",
  [6133] = "Travel to the northern borders of the Eastern Plaguelands and recover the Quel'Thalas Registry. The item is somewhere in the Quel'Lithien lodge.  You must also slay 8 Rangers, 8 Pathstriders, and 8 Woodsmen.",
  [6134] = "Bring 8 Ghost-o-plasms and the Crate of Ghost Magnets to Hornizz Brimbuzzle in Desolace.",
  [6135] = "Find Duskwing and slay him. From the corpse, recover a Patch of Duskwing's Fur and return it to Nathanos Blightcaller.  It is said that Duskwing roams the countryside to the north of Marris Stead.",
  [6136] = "Find Borelgore in the northern wastes of Eastern Plaguelands and destroy him. Return to Nathanos Blightcaller when the mission is complete.",
  [6141] = "Speak with Brother Anton in Desolace.",
  [6142] = "Find 10 pieces of Soft-shelled Clam Meat and bring it back to Mai'Lahii at Shadowprey Village.",
  [6143] = "Slay 7 Slitherblade Myrmidon, 7 Slitherblade Naga, and 5 Slitherblade Sorceresses, and then talk to Drulzegar at Shadowprey in Desolace.",
  [6144] = "Travel to the Undercity and speak with Varimathras.",
  [6145] = "Return to Eastern Plaguelands and track down the Crimson Courier. Kill the Courier and recover the Grand Crusader's Command.  Take the command to Nathanos Blightcaller for further instruction.",
  [6146] = "Travel to Tyr's Hand, southeast of the Marris Stead. Once there, take a bite of the Rotten Apple. While under the guise of the Scarlet Crusade, deliver the Grand Crusader's Command to Crusader Lord Valdelmar.",
  [6147] = "Return to Nathanos Blightcaller with the new information.",
  [6148] = "The Scarlet Crusade is on the move. Somewhere along the road from Tyr's Hand to Stratholme you will find the Oracle, Demetria, and her entourage. Hunt her down and slay her. Return to Nathanos Blightcaller should you succeed.",
  [6161] = "Find Rackmore's Silver Key.  Find Rackmore's Golden Key.  Find and open Rackmore's Chest.",
  [6162] = "Kill Overlord Ror and return his claw to Dreka'Sur at Bloodvenom Post in Felwood.",
  [6163] = "Travel to Stratholme and slay Ramstein the Gorger. Take his head as a souvenir for Nathanos.",
  [6164] = "Bring Augustus' Receipt Book to Augustus the Touched in Terrordale.",
  [6165] = "The description of this quest is missing",
  [6181] = "Bring Lewis' Note to Thor the gryphon master.",
  [6182] = "Speak with Mathias Shaw in Old Town Stormwind. He resides in the Barracks.",
  [6183] = "Speak with Mathias Shaw again if you wish to accept his task.",
  [6184] = "Travel to Chillwind Camp in the Western Plaguelands and meet up with your contact, Flint Shadowmore.",
  [6185] = "Scour the Eastern Plaguelands for clues as to the \"Blightcaller\" and the missing SI:7 agents. If you find any SI:7 Insignias, return them to Flint Shadowmore at Chillwind Camp.",
  [6186] = "Return to Stormwind and inform Highlord Bolvar Fordragon of the fate of Nathanos Marris.",
  [6187] = "Assemble an army and travel to the Eastern Plaguelands. Launch a full assault on Nathanos Blightcaller and any Horde filth that may attempt to protect him.  Keep your wits about you, $N. The Horde will defend the ranger lord with their very lives.",
  [6221] = "Nafien would like you to kill 5 Deadwood Den Watchers, 5 Deadwood Avengers, and 5 Deadwood Shamans.",
  [6241] = "Salfa wants you to kill 6 Winterfall Totemics, 6 Winterfall Den Watchers, and 6 Winterfall Pathfinders.",
  [6261] = "Bring Osric's Crate to Dungar Longdrink the gryphon master.",
  [6281] = "Buy a gryphon ride from the gryphon master Thor, then bring Lewis' Note to Osric Strang, in the shop Limited Immunity, in the Old Town of Stormwind.",
  [6282] = "Maggran Earthbinder in Sun Rock Retreat wants you to slay 7 Bloodfury Harpies, 7 Bloodfury Ambushers, 7 Bloodfury Slayers and 7 Bloodfury Roguefeathers.",
  [6283] = "Maggran at Sun Rock Retreat wishes you to slay Bloodfury Ripper and bring her remains as proof of your deed.",
  [6284] = "Kill Besseleth and bring Besseleth's Fang to Maggran at Sun Rock Retreat.",
  [6285] = "Buy a gryphon ride to Sentinel Hill from the gryphon master Dungar Longdrink, then take Osric's Crate to Lewis at Sentinel Hill.",
  [6301] = "Tammra Windfield at Sun Rock Retreat wants you to gather 10 Gaea Seeds.",
  [6321] = "Bring Podrig's Order to Karos Razok.",
  [6322] = "Bring Gordon's Crate to Michael Garrett.",
  [6323] = "Buy a bat ride to the Undercity from the bat master Karos Razok, then take Podrig's Order to Gordon Wendham in the Undercity.",
  [6324] = "Buy a bat ride to the Sepulcher from the bat master Michael Garrett, then bring Gordon's Crate to Deathguard Podrig in the Sepulcher.",
  [6341] = "Bring Nessa's Collection to Vesprystus.",
  [6342] = "Ride a hippogryph to Auberdine from the hippogryph master Vesprystus, then bring Nessa's Collection to Laird.",
  [6343] = "Bring Laird's Response to Nessa Shadowsong.",
  [6344] = "Speak with Nessa Shadowsong.",
  [6361] = "Bring the Bundle of Hides to the wind rider master Devrak in the Crossroads.",
  [6362] = "Buy a wind rider to Thunder Bluff from the wind rider master Devrak, then bring the Bundle of Hides to Ahanu in Thunder Bluff.",
  [6363] = "Bring Ahanu's Leather Goods to Tal in Thunder Bluff.",
  [6364] = "Buy a wind rider to the Crossroads from the wind rider master Tal, then bring Ahanu's Leather Goods to Jahan Hawkwing.",
  [6365] = "Bring Zargh's Meats to Devrak in the Crossroads.",
  [6381] = "Plant 10 Gaea Seeds in Gaea Dirt Mounds, and then return the remaining Enchanted Gaea Seeds to Tammra at Sun Rock Retreat.",
  [6382] = "Speak with Senani Thunderheart at Splintertree Post, Ashenvale.",
  [6384] = "Buy a wind rider to Orgrimmar from the wind rider master Devrak, then bring Zargh's Meats to Gryshka in Orgrimmar.",
  [6385] = "Bring Gryshka's Letter to Doras in Orgrimmar.",
  [6386] = "Buy a wind rider to the Crossroads from the wind rider master Doras, then bring Gryshka's Letter to Zargh at the Crossroads.",
  [6387] = "Bring Brock's List to Thorgrum Borrelson in Thelsamar.",
  [6388] = "Bring the Honorary Picks to Gryth Thurden in Ironforge.",
  [6389] = "Release the Plagueland Termites in the Northridge Lumber Mill, then return with the Barrel of Plagueland Termites to Nathaniel Dumah at Chillwind Camp in Western Plaguelands.",
  [6390] = "Release the Plagueland Termites in the Northridge Lumber Mill, then return with the Barrel of Plagueland Termites to Mickey Levine at the Bulwark in Tirisfal Glades.",
  [6391] = "Buy a gryphon to Ironforge from the gryphon master Thorgrum Borrelson, then bring Brock's List to Golnir Bouldertoe in Ironforge.",
  [6392] = "Buy a gryphon to Thelsamar from the gryphon master Gryth Thurden, then bring the Honorary Picks to Brock Stoneseeker in Thelsamar.",
  [6393] = "Bring 10 Incendrites to Tsunaman at Sun Rock Retreat.",
  [6394] = "Bring Thazz'ril's Pick to Foreman Thazz'ril.",
  [6395] = "Bring Samuel Fipps' Remains to Marla's Grave, then return to Novice Elreth.",
  [6401] = "Tell Tammra Windfield in Sun Rock Retreat the good news.",
  [6402] = "Travel to Stormwind City and venture to the city gates. Speak with Squire Rowe so that he may let Marshal Windsor know that you have arrived.",
  [6403] = "Follow Reginald Windsor through Stormwind. Protect him from harm!",
  [6421] = "Explore deep into the cave at Boulderslide Ravine and bring back 10 Resonite Crystals for Mor'rogal at Sun Rock Retreat to investigate.",
  [6441] = "Collect 16 Satyr Horns for Pixel in Splintertree Post.",
  [6442] = "Bring 20 Wrathtail Heads to Marukai along the Zoram Strand.",
  [6461] = "Xen'zilla at Malaka'Jin needs you to kill 10 Deepmoss Creepers and 7 Deepmoss Venomspitters.",
  [6462] = "Bring 8 Troll Charms to Mitsuwa at the Zoram'gar Outpost.",
  [6481] = "Open the Resonite cask with the Enchanted Resonite Crystal, and then slay Goggeroc. Return to Mor'rogal with the news and Enchanted Resonite Crystal.",
  [6482] = "Escort Ruul, then speak with Yama Snowhoof in Spintertree Post.",
  [6501] = "You must search the world for a being capable of restoring the power to the Fragment of the Dragon's Eye. The only information you possess about such a being is that they exist.",
  [6502] = "You must retrieve the Blood of the Black Dragon Champion from General Drakkisath. Drakkisath can be found in his throne room behind the Halls of Ascension in Blackrock Spire.",
  [6503] = "Kill 9 Ashenvale Outrunners, then return to Kuray'bin at Splintertree Outpost.",
  [6504] = "Find the 12 missing pages of the Shredder Operating Manual, and put them together to form Chapters 1, 2, and 3. Return the pages to Gurda Ragescar near Splintertree Post.",
  [6521] = "Bring Ambassador Malcin's Head to Varimathras in the Undercity.",
  [6522] = "Take the Small Scroll to Varimathras in the Undercity.",
  [6523] = "Escort Kaya Flathoof to Camp Aparaje, and then return to Makaba Flathoof near the southeastern edge of Stonetalon.",
  [6541] = "Report to Kadrak at the watch tower in northern Barrens.",
  [6542] = "Report to Kadrak at the watch tower in northern Barrens.",
  [6543] = "Open the Bundle of Reports.  Take the Warsong Reports to the Warsong Scout, Warsong Runner, and Warsong Outrider. Bring back the updates they give you to Kadrak at the northern watch tower in the barrens.",
  [6544] = "Escort Torek on his attack against Silverwing Outpost and Duriel Moonfire, then report to Ertog Ragetusk at Splintertree Post.",
  [6548] = "Kill 8 Grimtotem Ruffians and 6 Grimtotem Mercenaries, and then return to Makaba Flathoof near the southeastern edge of Stonetalon.",
  [6561] = "Bring the head of Twilight Lord Kelris to Bashana Runetotem in Thunder Bluff.",
  [6562] = "Speak to Je'neu Sancrea in Ashenvale.",
  [6563] = "Bring 20 Sapphires of Aku'Mai to Je'neu Sancrea in Ashenvale.",
  [6564] = "Bring the Damp Note to Je'neu Sancrea in Ashenvale.",
  [6565] = "Kill Lorgus Jett in Blackfathom Deeps and then return to Je'neu Sancrea in Ashenvale.",
  [6566] = "Listen to Thrall.",
  [6567] = "Seek out Rexxar. The Warchief has instructed you as to his whereabouts. Search the paths of Desolace, between the Stonetalon Mountains and Feralas.",
  [6568] = "Deliver Rexxar's Testament to Myranda the Hag in the Western Plaguelands.",
  [6569] = "Travel to Blackrock Spire and collect 20 Black Dragonspawn Eyes. Return to Myranda the Hag when the task is complete.",
  [6570] = "Travel to the Wyrmbog in Dustwallow Marsh and seek out Emberstrife's Den. Once inside, wear the Amulet of Draconic Subversion and speak with Emberstrife.",
  [6571] = "Collect the Warsong Supplies: Warsong Saw Blades, Logging Rope, Warsong Oil, and the Warsong Axe Shipment for Locke Okarr in Splintertree Post.",
  [6582] = "You must find the blue dragonflight drake champion, Scryer, and slay him. Pry his skull from his corpse and return it to Emberstrife.  You know that Scryer can be found in Winterspring.",
  [6583] = "Destroy the drake champion of the Green Flight, Somnus. Take his skull and return it to Emberstrife.",
  [6584] = "Guarding the Caverns of Time in the Tanaris Desert is Chronalis, child of Nozdormu. Destroy him and return his skull to Emberstrife.",
  [6585] = "Travel to Grim Batol and track down Axtroz, drake champion of the Red Flight. Destroy him and take his skull. Return the skull to Emberstrife.",
  [6601] = "It would appear as if the charade is over. You know that the Amulet of Draconic Subversion that Myranda the Hag created for you will not function inside Blackrock Spire. Perhaps you should find Rexxar and explain your predicament. Show him the Dull Drakefire Amulet. Hopefully he will know what to do next.",
  [6602] = "Travel to Blackrock Spire and slay General Drakkisath. Gather his blood and return it to Rexxar.",
  [6603] = "Find Donova Snowden near the hot springs in Winterspring.",
  [6604] = "Speak with Jaron Stoneshaper at Starfall Village.",
  [6605] = "Speak with Winna Hazzard in Felwood.",
  [6606] = "Speak with Witch Doctor Mau'ari in Everlook.",
  [6607] = "Nat Pagle wants you to catch the following fish:  Misty Reed Mahi Mahi from the Misty Reed Strand in the Swamp of Sorrows.  A Sar'theris Striker from the Sar'theris Strand in Desolace.  Feralas Ahi from the Verdantis River of Feralas.  Savage Coast Blue Sailfin from the Savage Coast of Stranglethorn Vale.  Return to Nat Pagle when you have reeled them all in!",
  [6608] = "You think Lumak is trying to tell you that he can no longer help you improve your fishing skill. You may want to try to find his friend, Nat Pagle, a human fishing off one of the islands south of Theramore (at least that's what you think Lumak said).",
  [6609] = "Travel to Kalimdor, to the coastal city of Theramore. From there you must search for an island, south of the main town. Nat Pagle awaits your arrival!",
  [6610] = "Dirge Quikcleave wants you to get the following items:  12 Giant Eggs. You will find those on the Rocs wandering Tanaris or any other species of large bird.  10 pieces of Zesty Clam Meat. You can find those in clams, naturally!  20 pieces of Alterac Swiss. Get thee to a cheesery!  Gather all of the items and return to Dirge.",
  [6611] = "Travel to Gadgetzan in the Tanaris desert and speak with Dirge Quikcleave about advancing your cooking career.",
  [6612] = "Travel to Gadgetzan in the Tanaris desert and speak with Dirge Quikcleave about advancing your cooking career.",
  [6621] = "Place Karang's Banner on the Foulweald Totem Mound.  Do not let the furbolgs destroy the banner.  Defeat Chief Murgut and bring Murgut's Totem to Karang Amakkar at Zoram'gar.",
  [6622] = "Save patients by using Triage Bandages to tend to their wounds. You must save 15 patients before 6 of them die from their injuries.  Remember the order of triage! Critically Injured Soldiers die the fastest followed by Badly Injured Soldiers. Injured Soldiers take the longest to die and should be saved AFTER your Critically Injured and Badly Injured Soldiers have been triaged.",
  [6623] = "Travel to Hammerfall in the Arathi Highlands and speak with Doctor Gregory Victor about joining the ranks of Horde Trauma.",
  [6624] = "Save patients by using Triage Bandages to tend to their wounds. You must save 15 patients before 6 of them die from their injuries.  Remember the order of triage! Critically Injured Soldiers die the fastest followed by Badly Injured Soldiers. Injured Soldiers take the longest to die and should be saved AFTER your Critically Injured and Badly Injured Soldiers have been triaged.",
  [6625] = "Travel to Theramore in the Dustwallow Marsh and speak with Doctor Gustaf VanHowzen about joining the ranks of Alliance Trauma.",
  [6626] = "Kill 8 Razorfen Battleguard, 8 Razorfen Thornweavers, and 8 Death's Head Cultists and return to Myriam Moonsinger near the entrance to Razorfen Downs.",
  [6627] = "Answer Braug Dimspirit's question successfully and then speak to him again. He will remain in Stonetalon Mountains when you are ready.",
  [6628] = "Answer Parqual Fintallas' question successfully and then speak to him again. He will remain in the Undercity until you are ready.",
  [6629] = "Kill Grundig Darkcloud and 6 Grimtotem Brutes, and return to Makaba Flathoof near the southeastern edge of Stonetalon.",
  [6641] = "Keep Muglash safe as he travels to the brazier. Help him by putting the brazier out, then protect him as you fight against the Naga.  If you are successful, return to the Zoram'gar Outpost and inform the Warsong Runner of the death of Vorsha the Lasher.",
  [6661] = "Capture 5 Deeprun Rats by using the Rat Catcher's Flute. Lead the rats back to Monty. Don't forget to turn in the flute when you're finished.",
  [6662] = "Take the Carton of Mystery Meat to Nipsy at the Stormwind Deeprun Tram Depot.",
  [6681] = "Take the Seal of Ravenholdt to Fahrad at Ravenholdt Manor, hidden away in the hills of Hillsbrad.  Your cunning will be tested along the way. Be prepared.",
  [6721] = "Speak with Dazalar in Dolanaar.",
  [6722] = "Speak with Dazalar in Dolanaar.",
  [6761] = "Speak with Mathrengyl Bearwalker at the Cenarion Enclave of Darnassus.",
  [6762] = "Speak with Rabine Saturna in the village of Nighthaven, Moonglade.  Moonglade lies between Felwood and Winterspring, accessible through a path out of Timbermaw Hold.",
  [6804] = "Use the Aspect of Neptulon on poisoned elementals of Eastern Plaguelands.  Bring 12 Discordant Bracers and the Aspect of Neptulon to Duke Hydraxis in Azshara.",
  [6805] = "Kill 15 Dust Stormers and 15 Desert Rumbers and then return to Duke Hydraxis in Azshara.",
  [6821] = "Bring the Eye of the Emberseer to Duke Hydraxis in Azshara.",
  [6822] = "Kill 1 Fire Lord, 1 Molten Giant, 1 Ancient Core Hound and 1 Lava Surger, then return to Duke Hydraxis in Azshara.",
  [6823] = "Earn an Honored faction with the Hydraxian Waterlords, then talk to Duke Hydraxis in Azshara.",
  [6824] = "Bring the Hands of Lucifron, Sulfuron, and Shazzrah to Duke Hydraxis.",
  [6841] = "x",
  [6842] = "x",
  [6844] = "Take the Encrusted Silithid Object to Umber - the Cenarion Circle's archivist - in the village of Nighthaven, Moonglade.",
  [6845] = "Speak with Rabine Saturna in the village of Nighthaven, Moonglade.",
  [6847] = "Recover Master Ryson's All Seeing Eye from the Winterax caves and return it to Master Ryson.  Be warned, it is said that Master Ryson's All Seeing Eye carries with it a terrible curse!",
  [6848] = "Recover Master Ryson's All Seeing Eye from the Winterax caves and return it to Master Ryson.  Be warned, it is said that Master Ryson's All Seeing Eye carries with it a terrible curse!",
  [6921] = "Bring the Fathom Core to Je'neu Sancrea at Zoram'gar Outpost, Ashenvale.",
  [6922] = "Bring the Strange Water Globe to Je'neu Sancrea at Zoram'gar Outpost, Ashenvale.",
  [6961] = "Speak with Greatfather Winter; he is located near the Smokywood Pastures vendor area in Orgrimmar.",
  [6962] = "Bring 5 Gingerbread Cookies and an Ice Cold Milk to Greatfather Winter in Orgrimmar.",
  [6963] = "Locate the Smokywood Pastures investigator that has gone missing in the snowy regions of the Alterac Mountains.",
  [6964] = "Speak with Sagorne Creststrider in the Valley of Wisdom of Orgrimmar about the Feast of Winter Veil.",
  [6981] = "Travel to Ratchet to find someone that can tell you more about the glowing shard.  Then, deliver the shard as you are directed.",
  [6982] = "Bring 10 Coldtooth Supplies to the Alliance Quartermaster in Dun Baldar.",
  [6983] = "Locate and return the Stolen Treats to Kaymard Copperpinch in Orgrimmar.  It was last thought to be in the possession of the Abominable Greench, found somewhere in the snowy regions of the Alterac Mountains.",
  [6984] = "Speak with Great-father Winter in Orgrimmar.",
  [6985] = "Bring 10 Irondeep Supplies to the Horde Quartermaster in Frostwolf Keep.",
  [7001] = "Locate a Frostwolf in Alterac Valley. Use the Frostwolf Muzzle when you are near the Frostwolf to 'tame' the beast. Once tamed, the Frostwolf will follow you back to the Frostwolf Stable Master. Speak with the Frostwolf Stable Master to earn credit for the capture.",
  [7002] = "null",
  [7003] = "Use Zorbin's Ultra-Shrinker to zap any kind of giant found in Feralas into a more manageable form.  Bring 15 Miniaturization Residues found on the zapped versions of these giants to Zorbin Fandazzle at the docks of the Forgotten Coast, Feralas.",
  [7021] = "Speak with Greatfather Winter; he is located near the Smokywood Pastures vendor area in Orgrimmar.",
  [7022] = "Speak with Greatfather Winter; he is located near the Smokywood Pastures vendor area in Ironforge.",
  [7023] = "Speak with Greatfather Winter; he is located near the Smokywood Pastures vendor area in Ironforge.",
  [7024] = "Speak with Greatfather Winter; he is located near the Smokywood Pastures vendor area in Orgrimmar.",
  [7025] = "Bring 5 Gingerbread Cookies and an Ice Cold Milk to Greatfather Winter in Ironforge.",
  [7026] = "null",
  [7027] = "Locate an Alterac Ram in Alterac Valley. Use the Stormpike Training Collar when you are near the Alterac Ram to 'tame' the beast. Once tamed, the Alterac Ram will follow you back to the Stable Master. Speak with the Stable Master to earn credit for the capture.",
  [7028] = "Collect 25 Theradric Crystal Carvings for Willow in Desolace.",
  [7029] = "Fill the Coated Cerulean Vial at the orange crystal pool in Maraudon.  Use the Filled Cerulean Vial on the Vylestem Vines to force the corrupted Noxxious Scion to emerge.  Heal 8 plants by killing these Noxxious Scion, then return to Vark Battlescar in Shadowprey Village.",
  [7041] = "Fill the Coated Cerulean Vial at the orange crystal pool in Maraudon.  Use the Filled Cerulean Vial on the Vylestem Vines to force the corrupted Noxxious Scion to emerge.  Heal 8 plants by killing these Noxxious Scion, then return to Talendria in Nijel's Point.",
  [7042] = "Locate the Smokywood Pastures investigator that has gone missing in the snowy regions of the Alterac Mountains.",
  [7043] = "Locate and return the Stolen Treats to Wulmort Jinglepocket in Ironforge.  It was last thought to be in the possession of the Abominable Greench, found somewhere in the snowy regions of the Alterac Mountains.",
  [7044] = "Recover the two parts of the Scepter of Celebras: the Celebrian Rod and the Celebrian Diamond.  Find a way to speak with Celebras.",
  [7045] = "Speak with Greatfather Winter in Ironforge.",
  [7046] = "Assist Celebras the Redeemed while he creates the Scepter of Celebras.  Speak with him when the ritual is complete.",
  [7061] = "Feel free to read the book, \"The Feast of Winter Veil\", to learn more about the holiday.  When you are finished with the book, deliver it to Cairne Bloodhoof in Thunder Bluff.",
  [7062] = "Speak with Historian Karnik at the Explorer's League in Ironforge about the Feast of Winter Veil.",
  [7063] = "Feel free to read the book, \"The Feast of Winter Veil\", to learn more about the holiday.  When you are finished with the book, deliver it to King Magni Bronzebeard in Ironforge.",
  [7064] = "Slay Princess Theradras and return to Selendra near Shadowprey Village in Desolace.",
  [7065] = "Slay Princess Theradras and return to Keeper Marandis at Nijel's Point in Desolace.",
  [7066] = "Seek out Remulos in Moonglade and give him the Seed of Life.",
  [7067] = "Read the Pariah's Instructions. Afterwards, obtain the Amulet of Union from Maraudon and return it to the Centaur Pariah in southern Desolace.",
  [7068] = "Collect 10 Shadowshard Fragments from Maraudon and return them to Uthel'nay in Orgrimmar.",
  [7070] = "Collect 10 Shadowshard Fragments from Maraudon and return them to Archmage Tervosh in Theramore on the coast of Dustwallow Marsh.",
  [7081] = "Assault a graveyard, then return to Sergeant Durgen Stormpike in the Alterac Mountains.",
  [7082] = "Assault a graveyard, then return to Corporal Teeka Bloodsnarl in the Alterac Mountains.",
  [7101] = "Capture an enemy tower, then return to Corporal Teeka Bloodsnarl in the Alterac Mountains.",
  [7102] = "Destroy the banner at an enemy tower or bunker, then return to Sergeant Durgen Stormpike in the Alterac Mountains.",
  [7121] = "Speak with the Stormpike Quartermaster.",
  [7122] = "Capture a mine that the Stormpike does not control, then return to Sergeant Durgen Stormpike in the Alterac Mountains.",
  [7123] = "Speak with the Frostwolf Quartermaster.",
  [7124] = "Capture a mine, then return to Corporal Teeka Bloodsnarl in the Alterac Mountains.",
  [7141] = "Enter Alterac Valley, defeat the Horde general Drek'thar, and then return to Prospector Stonehewer in the Alterac Mountains.",
  [7142] = "Enter Alterac Valley and defeat the dwarven general, Vanndar Stormpike.  Then, return to Voggah Deathgrip in the Alterac Mountains.",
  [7161] = "Travel to the Wildpaw cavern located southeast of the main base in Alterac Valley and find the Frostwolf Banner. Return the Frostwolf Banner to Warmaster Laggrond. ",
  [7162] = "Travel to the Icewing Caverns located southwest of Dun Baldar in Alterac Valley and recover the Stormpike Banner. Return the Stormpike Banner to Lieutenant Haggerdin in the Alterac Mountains.",
  [7181] = "According to legend, the leader of the mighty Winterax trolls appears at will to wreak havoc on the denizens of Alterac Valley.  Should Korrak make himself known, destroy him and return to Warmaster Laggrond.",
  [7201] = "Travel to Blackrock Depths and recover 10 Essence of the Elements. Your first inclination is to search the golems and golem makers. You remember Vivian Lagrave also muttering something about elementals.",
  [7202] = "According to legend, the leader of the mighty Winterax trolls appears at will to wreak havoc on the denizens of Alterac Valley.  Should Korrak make himself known, destroy him and return to Lieutenant Haggerdin in the Alterac Mountains.",
  [7221] = "Speak with Prospector Stonehewer in the Dun Baldar garrison.",
  [7222] = "Speak with Voggah in Frostwolf Keep.",
  [7223] = "Bring 20 Armor Scraps to Murgot Deepforge in Dun Baldar.",
  [7224] = "Bring 20 Armor Scraps to Smith Regzar in Frostwolf Village.",
  [7241] = "Venture to Alterac Valley, located in the Alterac Mountains. Find and speak with Warmaster Laggrond - who stands outside the tunnel entrance - to begin your career as a soldier of Frostwolf. You will find Alterac Valley north of Tarren Mill at the base of the Alterac Mountains.",
  [7261] = "Travel to Alterac Valley in the Hillsbrad Foothills. Outside of the entrance tunnel, find and speak with Lieutenant Haggerdin.  For the glory of Bronzebeard!",
  [7281] = "Travel into Stormpike territory and slay Commander Karl Philips. Return to Commander Louis Philips when the task is complete.",
  [7282] = "Travel into Frostwolf territory and slay Commander Louis Philips. Return to Commander Karl Philips when the task is complete.",
  [7301] = "Travel to Frostwolf territory and search for Wing Commander Slidore, Wing Commander Vipore, and Wing Commander Ichman. Return to Commander Duffy should you complete your mission.",
  [7302] = "Find out what became of Wing Commander Guse, Wing Commander Jeztor, and Wing Commander Mulverick. Return to Commander Mulfort should you complete your mission.",
  [7321] = "Bring 10 pieces of Turtle Meat and some Soothing Spices to Christoph Jeffcoat in Tarren Mill.",
  [7361] = "You have been tasked with slaying opposing night elf players in Alterac Valley.  Kill a night elf and return to Najak Hexxen at Frostwolf Keep with a Severed Night Elf Head.",
  [7362] = "You have been tasked with slaying opposing gnome players in Alterac Valley.  Kill a gnome and return to Ravak Grimtotem at Frostwolf Keep with a Tuft of Gnome Hair.",
  [7363] = "You have been tasked with slaying opposing human players in Alterac Valley.  Kill a human and return to Commander Louis Philips (who wanders between the front lines and Frostwolf keep) with a  Human Bone Chip.  A cure for the human condition is close at hand!",
  [7364] = "You have been tasked with slaying opposing tauren players in Alterac Valley.  Kill a tauren and return to Dirk Swindle at Dun'Baldar with a  Tauren Hoof.",
  [7365] = "You have been tasked with slaying opposing troll players in Alterac Valley.  Kill a troll and return to Athramanis at Dun'Baldar with Darkspear Troll Mojo.",
  [7366] = "You have been tasked with slaying opposing Forsaken players in Alterac Valley.  Kill a Forsaken and return to Commander Karl Philips (who wanders between the lumber mill and the mine) with a Forsaken Heart.",
  [7367] = "Find the Frostwolf Explosives Expert and kill him. Return to the Stormpike Explosives Expert when the task is complete.",
  [7368] = "Find the Stormpike Explosives Expert and kill him. Return to the Frostwolf Explosives Expert when the task is complete.",
  [7381] = "Should Korrak the Bloodrager make a return to the Snowfall Graveyard, seek him out and destroy him.  Return the Skull of Korrak to Warmaster Laggrond in the Hillsbrad Foothills.",
  [7382] = "Should Korrak the Bloodrager make a return to the Snowfall Graveyard, seek him out and destroy him.  Return the Skull of Korrak to Lieutenant Haggerdin in the Hillsbrad Foothills.",
  [7383] = "Fill the Amethyst Phial and bring it back to Corithras Moonrage in Dolanaar.",
  [7385] = "null",
  [7386] = "null",
  [7401] = "You have been tasked with slaying opposing Dwarf players in Alterac Valley.  Kill a Dwarf and rip out their spine. Take the Dwarf Spine to Sergeant Yazra Bloodsnarl at Frostwolf Keep.",
  [7402] = "You have been tasked with slaying opposing Orc players in Alterac Valley.  Kill an Orc and take their Orc Tooth back to Corporal Noreg Stormpike at Dun Baldar.",
  [7441] = "Travel to Dire Maul and locate the Imp, Pusillin. Convince Pusillin to give you Azj'Tordin's Book of Incantations through any means necessary.  Return to Azj'Tordin at the Lariss Pavilion in Feralas should you recover the Book of Incantations.",
  [7461] = "You must destroy the guardians surrounding the 5 Pylons that power the Prison of Immol'thar. Once the Pylons have powered down, the force field surrounding Immol'thar will have dissipated.  Enter the Prison of Immol'thar and eradicate the foul demon that stands at its heart. Finally, confront Prince Tortheldrin in Athenaeum.  Return to the Shen'dralar Ancient in the courtyard should you complete this quest.",
  [7462] = "Return to the Athenaeum and find the Treasure of the Shen'dralar. Claim your reward!",
  [7463] = "Travel to the Warpwood Quarter of Dire Maul and slay the water elemental, Hydrospawn. Return to Lorekeeper Lydros in the Athenaeum with the Hydrospawn Essence.",
  [7478] = "Bring a Libram of Rapidity, 1 Pristine Black Diamond, 2 Large Brilliant Shards, and 2 Blood of Heroes to Lorekeeper Lydros in Dire Maul to receive an Arcanum of Rapidity.",
  [7479] = "Bring a Libram of Focus, 1 Pristine Black Diamond, 4 Large Brilliant Shards, and 2 Skin of Shadow to Lorekeeper Lydros in Dire Maul to receive an Arcanum of Focus.",
  [7480] = "Bring a Libram of Protection, 1 Pristine Black Diamond, 2 Large Brilliant Shards, and 1 Frayed Abomination Stitching to Lorekeeper Lydros in Dire Maul to receive an Arcanum of Protection.",
  [7481] = "Search Dire Maul for Kariel Winthalus. Report back to Sage Korolusk at Camp Mojache with whatever information that you may find.",
  [7482] = "Search Dire Maul for Kariel Winthalus. Report back to Scholar Runethorn at Feathermoon with whatever information that you may find.",
  [7483] = "Bring a Libram of Rapidity, 1 Pristine Black Diamond, 2 Large Brilliant Shards, and 2 Blood of Heroes to Lorekeeper Lydros in Dire Maul to receive an Arcanum of Rapidity.",
  [7484] = "Bring a Libram of Focus, 1 Pristine Black Diamond, 4 Large Brilliant Shards, and 2 Skin of Shadow to Lorekeeper Lydros in Dire Maul to receive an Arcanum of Focus.",
  [7485] = "Bring a Libram of Protection, 1 Pristine Black Diamond, 2 Large Brilliant Shards, and 1 Frayed Abomination Stitching to Lorekeeper Lydros in Dire Maul to receive an Arcanum of Protection.",
  [7486] = "Claim your reward from Hydraxis' Coffer.",
  [7487] = "Venture to the Molten Core entry portal in Blackrock Depths and recover a Core Fragment. Return to Lothos Riftwaker in Blackrock Mountain when you have recovered the Core Fragment.",
  [7488] = "Bring Lethtendris' Web to Latronicus Moonspear at the Feathermoon Stronghold in Feralas.",
  [7489] = "Bring Lethtendris's Web to Talo Thornhoof at Camp Mojache in Feralas.",
  [7490] = "Take the Head of Onyxia to Thrall in Orgrimmar.",
  [7491] = "Seek out Overlord Runthak in the Valley of Strength.",
  [7492] = "Speak with Talo Thornhoof at Camp Mojache in Feralas.",
  [7494] = "Speak with Latronicus Moonspear at the Feathermoon Stronghold in Feralas.",
  [7495] = "Take the Head of Onyxia to Highlord Bolvar Fordragon in Stormwind.",
  [7496] = "Seek out Major Mattingly in the Valley of Heroes.",
  [7498] = "Return the book to its rightful owners.",
  [7499] = "Return the book to its rightful owners.",
  [7500] = "Return the book to its rightful owners.",
  [7501] = "Return the book to its rightful owners.",
  [7502] = "Return the book to its rightful owners.",
  [7503] = "Return the book to its rightful owners.",
  [7504] = "Return the book to its rightful owners.",
  [7505] = "Return the book to its rightful owners.",
  [7506] = "Return the book to its rightful owners.",
  [7507] = "Return Foror's Compendium of Dragon Slaying to the Athenaeum.",
  [7508] = "Give the Dull and Flat Elven Blade to Lorekeeper Lydros.",
  [7509] = "You must get Onyxia to breathe fire on the Unfired Ancient Blade. Once this is done, pick up the now Heated Ancient Blade. Be warned, a Heated Ancient Blade will not remain heated forever - time is of the essence.  The last step before returning to me is to slay the beast and drive the Heated Ancient Blade into her corpse.  Do this and Quel'Serrar will be yours.",
  [7521] = "To free Thunderaan the Windseeker from his prison, you must present the right and left halves of the Bindings of the Wind Seeker, 10 bars of Elementium, and the Essence of the Firelord to Highlord Demitrian. ",
  [7562] = "Speak with Mor'zul Bloodbringer in the Burning Steppes.",
  [7563] = "Bring 30 bottles of Raging Beast's Blood to Mor'zul Bloodbringer in the Burning Steppes.",
  [7564] = "Bring the Case of Blood to Gorzeeki Wildeyes in the Burning Steppes.",
  [7581] = "Travel to Dire Maul in Feralas and recover 15 Satyr Blood from the Wildspawn Satyr that inhabit the Warpwood Quarter. Return to Daio in the Tainted Scar when this is done.",
  [7582] = "Travel to Darkwhisper Gorge in Winterspring and recover 5 Tears of the Hederine from the Hederine demons that occupy the gorge. Return to Daio in the Tainted Scar when you have completed this task.",
  [7583] = "Venture forth into the Tainted Scar and locate a Doomguard Commander.  Use the Glowing Crystal Prison on the Doomguard Commander. Be prepared for a ferocious onslaught of attacks, as the demon attempts to escape capture.  Should you succeed, return the Imprisoned Doomguard to Daio in the Tainted Scar.",
  [7601] = "Speak with Impsy in Felwood.",
  [7602] = "Impsy in Felwood has asked that you bring him three Flawless Fel Essences originating from three distinct locations.  The Legashi Satyrs of Azshara hold the Flawless Fel Essence of their region. The Jaedenar Legionnaires of Jaedenar hold the Flawless Fel Essence of their region. The Felguard Sentries of the Blasted Lands hold the Flawless Fel Essence of their region.  Recover the Flawless Fel Essences and return  to Impsy in Felwood.",
  [7603] = "Search Shatter Scar Vale in Felwood for the remains of Kroshius. When you locate the remains, use the Fel Fire near them and await Kroshius' return. When the infernal has awoken, slay him and take from his corpse Kroshius' Infernal Core.  Return Kroshius' Infernal Core to Niby the Almighty in Felwood.",
  [7604] = "Turn the Thorium Brotherhood Contract in to Lokhtos Darkbargainer if you would like to receive the plans for Sulfuron.",
  [7622] = "Save 50 Peasants before 15 are slain. Speak with Eris Havenfire should you accomplish this task.  You may view the Death Post to view how many Peasants have been slain.",
  [7623] = "Purchase Shadowy Potions from Gorzeeki in the Burning Steppes.  Use the potions to travel through Jaedenar, and speak with Lord Banehollow.",
  [7624] = "Confront Ulathek, then bring The Traitor's Heart to Lord Banehollow in Jaedenar.",
  [7625] = "Purchase Xorothian Stardust from Ur'dan.  Bring it to Gorzeeki Wildeyes in the Burning Steppes.",
  [7626] = "Bring 10 Elixirs of Shadow Power to Gorzeeki Wildeyes in the Burning Steppes.",
  [7627] = "Bring 6 Large Brilliant Shards and 25 Dark Iron Ore to Gorzeeki in the Burning Steppes.",
  [7628] = "Bring 35 Black Dragonscales to Gorzeeki Wildeyes in the Burning Steppes.",
  [7629] = "Bring the Imp in a Jar to the alchemy lab in the Scholomance.  After the parchment is created, return the jar to Gorzeeki Wildeyes.",
  [7630] = "Bring 3 Arcanite Bars to Gorzeeki in the Burning Steppes.",
  [7631] = "Read Mor'zul's Instructions.  Summon a Xorothian Dreadsteed, defeat it, then bind its spirit to you.",
  [7632] = "Find the owner of the Ancient Petrified Leaf. Good luck, $N; It's a big world.",
  [7634] = "Hastat the Ancient has asked that you bring him a Mature Blue Dragon Sinew. Should you find this sinew, return it to Hastat in Felwood.",
  [7635] = "Stoma the Ancient has asked that you bring him a Mature Black Dragon Sinew. Should you find this sinew, return it to Stoma in Felwood.",
  [7636] = "You must find and destroy these four demonic corrupters:  Simone the Seductress.  Klinfran the Crazed.  Solenor the Slayer.  Artorius the Doombringer.  Destroy these creatures and return to Vartrus the Ancient in Felwood with their heads.  Refer to the Petrified Bark in your inventory for clues as to their whereabouts.  You MUST complete this task by yourself.",
  [7637] = "Travel to Ironforge and get High Priest Rohan's Exorcism Censer.  You will need to make a donation of 150 gold in order to secure it.",
  [7638] = "Speak with Lord Grayson Shadowbreaker in Stormwind's Cathedral District.",
  [7639] = "Return the Exorcism Censer to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind.",
  [7640] = "Use the Exorcism Censer to drive out the spirits that torment Terrordale.  When you have slain 25 Terrordale Spirits, return to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind.",
  [7641] = "Speak with Grimand Elmore in Stormwind's Dwarven District.",
  [7642] = "Bring 40 Runecloth, 6 Arcanite Bars, 10 Arthas' Tears, 5 Stratholme Holy Water vials, and 150 gold to Grimand Elmore in the Dwarven District of Stormwind.",
  [7643] = "Acquire special horse feed used for feeding a spirit horse.  Merideth Carlson in Southshore apparently is the source for such food.  Travel to the Dire Maul dungeon in Feralas and slay Tendris Warpwood.  Doing so will free the Ancient Equine Spirit.  Feed it the special horse feed, thereby soothing the spirit.  Finally, give it the Arcanite Barding so it may bless it.",
  [7644] = "Return with the Blessed Arcanite Barding to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind.",
  [7645] = "Retrieve 20 Enriched Manna Biscuits - the key ingredient in making Manna-Enriched Horse Feed - for Merideth Carlson at Southshore in the Hillsbrad Foothills.  The Argent Dawn is known as the sole purveyor of the biscuits.  You also need to give her 50 gold to soothe her ruffled sensibilities.",
  [7646] = "Bring an Azerothian Diamond and a Pristine Black Diamond to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind.",
  [7647] = "Use the Divination Scryer in the heart of the Great Ossuary's basement in the Scholomance.  Doing so will bring forth the spirits you must judge.  Defeating these spirits will summon forth Death Knight Darkreaver.  Defeat him and reclaim the lost soul of the fallen charger.  Give the Charger's Redeemed Soul and the Blessed Enchanted Barding to Darkreaver's Fallen Charger.",
  [7648] = "Take the Arcanite Barding to Lord Grayson Shadowbreaker in Stormwind's Cathedral District for his inspection.",
  [7649] = "Return the book to its rightful owners.",
  [7650] = "Return the book to its rightful owners.",
  [7651] = "Return the book to its rightful owners.",
  [7653] = "For the belt plans, I'll be needin' 20 thorium bars.",
  [7654] = "For the boot plans, I'll be needin' 40 thorium bars. Yep, 40. Are you gonna cry? Would you like a hanky?",
  [7655] = "For the bracer plans, I'll be needin' 20 thorium bars.",
  [7656] = "For the chest piece plans, I'll be needin' 60 thorium bars.Oh boy, there you go again. Are you gonna be runnin' to yer blue Gods, askin' why they have forsaken you?!?Toughen up, Nancy! Nobody ever said life's fair.",
  [7657] = "Just hand over 50 thorium bars and the helm plans are yers.",
  [7658] = "Just hand over 60 thorium bars and the leg plans are yers.I know, I'm driving you into bankruptcy! I've heard it all before so you can save your sob story, weakling.",
  [7659] = "For the shoulder plans, I'll be needin' 20 thorium bars.",
  [7667] = "If you are interested in helping Sagorne Crestrider in Orgrimmar's Valley of Wisdom, bring him an Azerothian Diamond and a Pristine Black Diamond.",
  [7668] = "Use the Divination Scryer in the heart of the Great Ossuary's basement in the Scholomance.  Doing so will bring forth spirits you must fight.  Defeating these spirits will summon forth Death Knight Darkreaver; defeat him.  Bring Darkreaver's Head to Sagorne Creststrider in the Valley of Wisdom, Orgrimmar.",
  [7670] = "Speak with Lord Grayson Shadowbreaker in Stormwind's Cathedral District.",
  [7681] = "Feed your pet, then talk to your questgiver.",
  [7682] = "Feed your pet, then talk to your questgiver.",
  [7701] = "Deep within the Slag Pit of the Cauldron, in the Searing Gorge, you will find the traitorous Dark Iron dwarf named Overseer Maltorius.  Slay Overseer Maltorius and take his head. Return the head to Lookout Captain Lolo Longstriker in the Searing Gorge for your reward.",
  [7703] = "Find the Gauntlet of Gordok Might and return it to Captain Kromcrush in Dire Maul.  According to Kromcrush, the \"old timey story\" says that Tortheldrin - a \"creepy\" elf who called himself a prince - stole it from one of the Gordok kings.",
  [7704] = "Take Chambermaid Pillaclencher's Pillow to Evonice Sootsmoker in the Searing Gorge.",
  [7721] = "Collect 10 Water Elemental Cores from the Sea Elementals and Sea Sprays along the Forgotten Coast of Feralas, and bring them back to Zorbin Fandazzle who is near the dock there.",
  [7722] = "Somewhere in the Slag Pit of the Cauldron you will find the Secret Plans: Fiery Flux that Overseer Maltorius stole. Find those plans and return them to Master Smith Burninate in the Searing Gorge.",
  [7723] = "Hansel Heavyhands wants you to kill 20 Heavy War Golems.  The Heavy War Golems wander the areas surrounding the Cauldron in the Searing Gorge. When you've killed enough, return to Hansel in Searing Gorge.",
  [7724] = "Hansel Heavyhands wants you to kill 20 Greater Lava Spiders in the Searing Gorge. You can find Greater Lava Spiders in the plateaus and lava pools of the Searing Gorge.  Return to Hansel Heavyhands in the Searing Gorge when you have killed enough Greater Lava Spiders.",
  [7725] = "Use Zorbin's Ultra-Shrinker to zap any kind of giant found in Feralas into a more manageable form.  Bring 10 Miniaturization Residues found on the zapped versions of these giants to Zorbin Fandazzle at the docks of the Forgotten Coast, Feralas.",
  [7726] = "Collect 6 Water Elemental Cores from the Sea Elementals and Sea Sprays along the Forgotten Coast of Feralas, and bring them back to Zorbin Fandazzle who is near the dock there.",
  [7727] = "Hansel Heavyhands wants you to kill 20 Incendosaurs.  You will find Incendosaurs occupying the lava pools inside the Slag Pit. The Slag Pit can be found in the Cauldron of the Searing Gorge.  Return to Hansel Heavyhands in the Searing Gorge when you have killed enough Incendosaurs.",
  [7728] = "Find and return the Smithing Tuyere and Lookout's Spyglass to Taskmaster Scrange in the Searing Gorge.  The only information you have about these items is the following: They were definitely stolen by Dark Iron dwarves. The Smithing Tuyere is a blacksmithing tool used by blacksmiths and the Lookout's Spyglass is an invaluable monitoring tool to lookouts. ",
  [7729] = "Slay 15 Dark Iron Taskmasters and 15 Dark Iron Slavers. Return to Taskmaster Scrange in the Searing Gorge once you have accomplished this task.",
  [7730] = "Bring 20 Zukk'ash Carapaces to Hadoken Swiftstrider at Camp Mojache, Feralas.",
  [7731] = "Defeat Stinglasher in the Writhing Deep, bringing its glands back to Hadoken Swiftstrider at Camp Mojache, Feralas.",
  [7732] = "Deliver the Camp Mojache Zukk'ash Report to Zilzibin Drumlore.  He resides in the Drag of Orgrimmar.",
  [7733] = "Bring 10 Rage Scar Yeti Hides to Pratt McGrubben at Feathermoon Stronghold, Feralas.",
  [7734] = "Bring 10 Rage Scar Yeti Hides to Jangdor Swiftstrider at Camp Mojache, Feralas.",
  [7735] = "Bring the Pristine Yeti Hide to Pratt McGrubben at the Feathermoon Stronghold, Feralas.",
  [7738] = "Bring the Perfect Yeti Hide to Jangdor Swiftstrider at Camp Mojache, Feralas.",
  [7761] = "That is one stupid orc. It would appear as if you need to find this brand and gain the Mark of Drakkisath in order to access the Orb of Command.  The letter indicates that General Drakkisath guards the brand. Perhaps you should investigate.",
  [7781] = "Return the Head of Nefarian to Highlord Bolvar Fordragon in Stormwind.",
  [7782] = "Venture to the Valley of Heroes in Stormwind City and speak with Field Marshal Afrasiabi.",
  [7783] = "Return the Head of Nefarian to Thrall in Orgrimmar.",
  [7784] = "Speak with High Overlord Saurfang in Orgrimmar. He stands waiting for you in the Valley of Strength.",
  [7785] = "Examine the Vessel of Rebirth and return it to Highlord Demitrian.",
  [7786] = "To free Thunderaan the Windseeker from his prison, you must present the right and left halves of the Bindings of the Windseeker, 10 bars of Elementium, and the Essence of the Firelord to Highlord Demitrian in Silithus.",
  [7787] = "Present the Dormant Wind Kissed Blade to Highlord Demitrian.",
  [7788] = "Enter Warsong Gulch and defeat the Horde, obtain a Warsong Gulch Mark of Honor, and return to Sentinel Farsong at the Silverwing Grove.",
  [7789] = "Enter Warsong Gulch and defeat the Alliance, gain a Warsong Gulch Mark of Honor, and bring it to Captain Shatterskull at the Mor'shan Base Camp.",
  [7810] = "Speak with Short John Mithril in the Stranglethorn Arena.",
  [7815] = "Katoom the Angler at Revantusk Village in the Hinterlands wants you to kill 15 Saltwater Snapjaw turtles. Return to him when you have completed this task.",
  [7816] = "Katoom the Angler at Revantusk Village in the Hinterlands wants you to kill Gammerita and retrieve Katoom's Best Lure from her corpse.  Katoom mentioned that Gammerita hangs out on the coast with the other turtles.",
  [7828] = "Huntsman Markhor at Revantusk Village in the Hinterlands wants you to kill 15 Silvermane Stalkers and 15 Silvermane Howlers. Return to him once the task is complete.  Markhor mentioned that the wolves hide in the wilds of the Hinterlands.",
  [7829] = "Huntsman Markhor at Revantusk Village in the Hinterlands wants you to kill 20 Savage Owlbeasts. Return to him once the task is complete.  Markhor mentioned that the Savage Owlbeasts occupy the wilds of the Hinterlands.",
  [7830] = "Huntsman Markhor at Revantusk Village in the Hinterlands wants you to kill a Razorbeak Skylord and retrieve its Skylord Plume. Return to him once the task is complete.  Markhor mentioned that the Razorbeak Skylord are a rare breed that tend to occupy the wilds of the Hinterlands.",
  [7839] = "Smith Slagtree at Revantusk Village in the Hinterlands wants you to find Slagtree's Lost Tools. Return to him once this task is complete.  You recall Smith Slagtree mentioning that the tools might be at one of the Vilebranch temples in the northeastern region of the Hinterlands. You should also check Skulk Rock.",
  [7840] = "Lard at Revantusk Village in the Hinterlands wants you to find Lard's Lunch. Return to him when this task is complete.  Lard mentioned that he left it on the island to the north. Watch out for Vilebranch trolls.",
  [7841] = "Otho Moji'ko at Revantusk Village in the Hinterlands wants you to slaughter 15 Highvale Outrunners, 15 Highvale Scouts, 15 Highvale Marksman and 15 Highvale Rangers. Return to him when this task is complete.  You can find the Highvale high elves at the Quel'Danil Lodge in the northwestern region of the Hinterlands.",
  [7842] = "Otho Moji'ko at Revantusk Village in the Hinterlands wants you to bring him 10 Long Elegant Feathers from the gryphons that inhabit the Hinterlands. Return to him once this task is complete.  Gryphons are known to inhabit every region of the Hinterlands.",
  [7843] = "Otho Moji'ko at Revantusk Village in the Hinterlands wants you to travel to Aerie Peak in the western region of the Hinterlands and place the Final Message to the Wildhammer by the well in the center of town. Return to him once this task is complete.  Beware of angry Wildhammer dwarves and unruly members of the Alliance.",
  [7844] = "Mystic Yayo'jin at Revantusk Village in the Hinterlands wants you to kill 30 Vilebranch Scalpers and 15 Vilebranch Soothsayers. Return to her when this task is complete.  Yayo'jin indicated that these trolls could be found near the Shaol'watha and Agol'watha temples in the north by northeastern region of the Hinterlands.",
  [7845] = "Primal Torntusk at Raventusk Village in the Hinterlands wants you to rescue her mate, Elder Torntusk, from Jintha'alor.  You have been told that he is being held prisoner atop Jintha'alor, the Vilebranch capital city located in the southern region of the Hinterlands.",
  [7846] = "Elder Torntusk at Jintha'alor wants you to kill Hitah'ya the Keeper to get the Shackle Key to his bindings. Return to Elder Torn'tusk when you have recovered the key.",
  [7847] = "Elder Torntusk at Jintha'alor wants you to return to Primal Torntusk at Revantusk Village with news of his rescue.",
  [7848] = "Venture to the Molten Core entry portal in Blackrock Depths and recover a Core Fragment. Return to Lothos Riftwaker in Blackrock Mountain when you have recovered the Core Fragment.",
  [7849] = "Huntsman Markhor at Revantusk Village in the Hinterlands wants you to recover his twin brother's remains. Find and return Huntsman Malkhor's Skull and Huntsman Malkhor's Bones to Huntsman Markhor.  Markhor mentioned that his brother's remains were fed to the oozes and wolves of the Vilebranch. He also mentioned that there is a refuse pit filled with oozes in Jintha'alor as well as a wolf den. Both of these places are near the top of the temple.",
  [7850] = "Primal Torntusk at Revantusk Village in the Hinterlands wants you to recover 10 Vessels of Tainted Blood from Jintha'alor. Return to Primal Torntusk when this task is complete.",
  [7861] = "You have been ordered to slay Vile Priestess Hexx and 20 Vilebranch Aman'zasi Guards. See Primal Torntusk at Revantusk Village in the Hinterlands once this task is complete.  Vile Priestess Hexx and the Aman'zasi Guards can be found atop Jintha'alor in the Hinterlands.",
  [7862] = "You have been tasked with the decimation of 20 Vilebranch Berserkers, 20 Vilebranch Shadow Hunters, 20 Vilebranch Blood Drinkers, and 20 Vilebranch Soul Eaters.  Should you complete this task, return to Primal Torntusk at Revantusk Village in the Hinterlands.",
  [7871] = "Enter Warsong Gulch and defeat the Horde, obtain a Warsong Gulch Mark of Honor, and return to Sentinel Farsong at the Silverwing Grove.",
  [7872] = "Enter Warsong Gulch and defeat the Horde, obtain a Warsong Gulch Mark of Honor, and return to Sentinel Farsong at the Silverwing Grove.",
