  [7876] = "Enter Warsong Gulch and defeat the Alliance, gain a Warsong Gulch Mark of Honor, and bring it to Captain Shatterskull at the Mor'shan Base Camp.",
  [7877] = "Return to the Athenaeum and find the Treasure of the Shen'dralar. Claim your reward!",
