  [8053] = "Bring Jin'rokh the Breaker Primal Hakkari Bindings.  You must also have a reputation equal to or greater than Friendly with the Zandalar Tribe.  Jin'rokh the Breaker is located on Yojamba Isle, Stranglethorn Vale.",
