  [8231] = "Bring 6 Wavethrasher Scales to Ogtinc in Azshara.  Ogtinc resides atop the cliffs northeast the Ruins of Eldarath.",
  [8232] = "Bring the Tooth of Morphaz to Ogtinc in Azshara.  Ogtinc resides atop the cliffs northeast the Ruins of Eldarath.",
  [8233] = "Speak with Lord Jorach Ravenholdt in Ravenholdt Manor.",
  [8234] = "Retrieve the Sealed Azure Bag from the Timbermaw Shaman in Azshara.  Then take the bag to Archmage Xylem, also found in Azshara.",
  [8235] = "Bring 10 Encoded Fragments to Archmage Xylem in Azshara.",
  [8236] = "Return the Azure Key to Lord Jorach Ravenholdt.",
  [8240] = "Destroy any one of the Hakkari Bijous found in Zul'Gurub at the Altar of Zanza on Yojamba Isle.  When done, speak with Vinchaxa nearby.",
  [8250] = "Seek out Sanath Lim-yo and gain passage to see Archmage Xylem.",
  [8251] = "Bring 10 Glittering Dust to Archmage Xylem.",
  [8252] = "Collect 6 Enchanted Coral and return them to Archmage Xylem.",
  [8253] = "Retrieve the Arcane Shard from Morphaz and return to Archmage Xylem.",
  [8254] = "Seek out Ogtinc in Azshara.",
  [8255] = "Acquire 4 Healthy Courser Glands and bring them to Ogtinc in Azshara.  Ogtinc resides atop the cliffs northeast the Ruins of Eldarath.",
  [8256] = "Acquire an Ichor of Undeath for Ogtinc in Azshara.  Ogtinc resides atop the cliffs northeast the Ruins of Eldarath.",
  [8257] = "Kill Morphaz in the sunken temple of Atal'Hakkar, and return his blood to Greta Mosshoof in Felwood.  The entrance to the sunken temple can be found in the Swamp of Sorrows.",
  [8258] = "Use the Divination Scryer in the heart of the Great Ossuary's basement in the Scholomance.  Doing so will bring forth spirits you must fight.  Defeating these spirits will summon forth Death Knight Darkreaver; defeat him.  Bring Darkreaver's Head to Sagorne Creststrider in the Valley of Wisdom, Orgrimmar.",
  [8266] = "Bring the Ribbons of Sacrifice to Sentinel Farsong so that the Sentinels may reward you for acting on our behalf.",
  [8267] = "Bring the Ribbons of Sacrifice to Captain Shatterskull so that the Outriders may reward you for acting on our behalf.",
  [8268] = "Bring the Ribbons of Sacrifice to Captain Shatterskull so that the Outriders may reward you for acting on our behalf.",
  [8269] = "Bring the Ribbons of Sacrifice to Sentinel Farsong so that the Sentinels may reward you for acting on our behalf.",
  [8271] = "According to legend, the leader of the mighty Winterax trolls appears at will to wreak havoc on the denizens of Alterac Valley.  Should Korrak make himself known, destroy him and return to Lieutenant Haggerdin in the Alterac Mountains.",
  [8272] = "According to legend, the leader of the mighty Winterax trolls appears at will to wreak havoc on the denizens of Alterac Valley.  Should Korrak make himself known, destroy him and return to Warmaster Laggrond.",
  [8274] = "Kill 5 Murlocs and come back to the test character.",
  [8275] = "Talk to Windcaller Proudhorn at Cenarion Hold in Silithus.",
  [8276] = "Talk to Windcaller Proudhorn at Cenarion Hold in Silithus.",
  [8277] = "Beetix Ficklespragg at Cenarion Hold in Silithus wants you to gather 8 Stonelash Scorpid Stingers and 8 Sand Skitterer Fangs. Return to her when you have completed the task.",
  [8278] = "Beetix Ficklespragg at Cenarion Hold in Silithus wants you to gather 3 Stonelash Pincer Stingers, 3 Stonelash Flayer Stingers and 3 Rock Stalker Fangs.",
  [8279] = "Bring the three chapters of the Twilight Lexicon to Hermit Ortell in Silithus.  ",
  [8280] = "Windcaller Proudhorn at Cenarion Hold in Silithus wants you to kill 15 Dredge Strikers.",
  [8281] = "Windcaller Proudhorn at Cenarion Hold in Silithus wants you to slay 20 Dredge Crushers.",
  [8282] = "Retrieve Noggle's Satchel from the mountains in the south of Silithus and return it to him at Cenarion Hold.",
  [8283] = "Bring Deathclasp's Pincer to Vish Kozus, Captain of the Guard.",
  [8284] = "Geologist Larksbane at Cenarion Hold in Silithus wants you to collect 8 Twilight Tablet Fragments.",
  [8285] = "Take the restored tablet to Hermit Ortell in Silithus.",
  [8286] = "Venture to the Caverns of Time in Tanaris and find Anachronos, Brood of Nozdormu.",
  [8287] = "Take the Decoded Tablet Parchment to Commander Mar'alith.",
  [8288] = "Return the Head of the Broodlord Lashlayer to Baristolth of the Shifting Sands at Cenarion Hold in Silithus.",
  [8290] = "Enter Warsong Gulch and defeat the Horde, obtain a Warsong Gulch Mark of Honor, and return to Sentinel Farsong at the Silverwing Grove.",
  [8291] = "Enter Warsong Gulch and defeat the Horde, obtain a Warsong Gulch Mark of Honor, and return to Sentinel Farsong at the Silverwing Grove.",
  [8294] = "Enter Warsong Gulch and defeat the Alliance, gain a Warsong Gulch Mark of Honor, and bring it to Captain Shatterskull at the Mor'shan Base Camp.",
  [8295] = "Enter Warsong Gulch and defeat the Alliance, gain a Warsong Gulch Mark of Honor, and bring it to Captain Shatterskull at the Mor'shan Base Camp.",
  [8297] = "Win the battle for Arathi Basin, get an Arathi Basin Mark of Honor, and return it to Sergeant Maclear at Refuge Pointe.",
  [8299] = "Win the battle for Arathi Basin, get an Arathi Basin Mark of Honor, and return it to Deathstalker Mortis at Hammerfall.",
  [8301] = "Collect 200 Silithid Carapace Fragments and return to Baristolth.",
  [8302] = "Collect 200 Silithid Carapace Fragments and return to Baristolth.",
  [8303] = "Seek out Anachronos at the Caverns of Time in Tanaris.",
  [8304] = "Commander Mar'alith at Cenarion Hold in Silithus wants you to question the inhabitants of Bronzebeard's Encampment. You will find Bronzebeard's Encampment south of Cenarion Hold.  Once you have gathered the requested information, return to Commander Mar'alith.",
  [8305] = "Locate the Crystalline Tear in Silithus and gaze into its depths.",
  [8306] = "Commander Mar'alith at Cenarion Hold in Silithus wants you to find his beloved Natalia. The information that you gathered points to Hive'Regal in the south as being the area in which you may find Mistress Natalia Mar'alith.  Do not forget to visit the dwarves at Bronzebeard's camp before venturing into the hive. They might have some additional work and advice for you.  And $N, remember the Commander's words: \"Do what you must...\"",
  [8307] = "Look for information about cooking Sandworm Meat at the Twilight's Hammer camp west of Cenarion Hold.",
  [8308] = "Take Brann Bronzebeard's Letter to Bronzebeard's Encampment in southern Silithus.",
  [8309] = "Rutgar Glyphshaper at Bronzebeard's Encampment in Silithus wants you to venture to Hive'Ashi, Hive'Zora, and Hive'Regal and recover Glyphed Rubbings from the Glyphed Crystals of each hive.  Use the Geologist's Transcription Kit to make a reasonable facsimile of the ancient glyphs. Return to Rutgar Glyphshaper when you complete this task.",
  [8310] = "Frankal Stonebridge at Bronzebeard's Encampment in Silithus wants you to recover a Hive'Zora Silithid Brain, Hive'Ashi Silithid Brain, and a Hive'Regal Silithid Brain. Return to Frankal when you have completed this task.",
  [8311] = "Speak with the innkeepers of Stormwind, Ironforge, and Darnassus, as well as Talvash del Kissel in Ironforge.  Perform the tricks they ask of you in exchange for the treats they offer.  Return to Jesper at the Stormwind Orphanage with a Darnassus Marzipan, Gnomeregan Gumdrop, Stormwind Nougat, and Ironforge Mint.",
  [8312] = "Speak with the innkeepers of Orgrimmar, Undercity, and Thunder Bluff, as well as Kali Remik in Sen'jin Village.  Perform the tricks they ask of you in exchange for the treats they offer.  Return to Spoops at the Orgrimmar Orphanage with a Thunder Bluff Marzipan, Darkspear Gumdrop, Orgrimmar Nougat, and Undercity Mint.",
  [8313] = "Bring the Torn Recipe Page to Calandrath at the inn in Cenarion Hold.",
  [8314] = "Rutgar Glyphshaper at Bronzebeard's Encampment wants you to deliver the Glyphed Crystal Prism to Geologist Larksbane at the Cenarion Hold in Silithus.",
  [8315] = "Geologist Larksbane at Cenarion Hold in Silithus wants you to recover the Crystal Unlocking Mechanism from the Qiraji Emissary.  You have been instructed to take the Glyphs of Calling to the Bones of Grakkarond, south of Cenarion Hold, and draw them in the sand. Should the Qiraji Emissary appear, slay it and recover the Crystal Unlocking Mechanism. Return to Geologist Larksbane if you succeed.  Assemble an army for this task, $N!",
  [8317] = "Calandrath at Cenarion Hold needs a batch of 10 Smoked Desert Dumplings.",
  [8318] = "Bring 10 Encrypted Twilight Texts to Bor Wildmane in Cenarion Hold.",
  [8320] = "Kill 10 Twilight Geolords, then return to Huum Wildmane in Cenarion Hold.",
  [8321] = "Bring Vyral's Signet Ring to Huum Wildmane in Cenarion Hold.",
  [8322] = "Place the Rotten Eggs in the main brew keg located inside the Southshore Inn.",
  [8323] = "Hermit Ortell wants you to bring him 10 Encrypted Twilight Texts",
  [8331] = "Speak with Aurel Goldleaf in Cenarion Hold.",
  [8332] = "Bring 1 Large Brilliant Shard and 3 Abyssal Crests to Aurel Goldleaf in Cenarion Hold.",
  [8341] = "Bring 5 Large Brilliant Shards and 3 Abyssal Signets to Aurel Goldleaf in Cenarion Hold.",
  [8343] = "Speak with Aurel Goldleaf in Cenarion Hold.",
  [8348] = "Bring the Abyssal Signet to Bor Wildmane in Cenarion Hold.",
  [8349] = "Speak with Bor Wildmane in Cenarion Hold.",
  [8351] = "Speak with Bor Wildmane in Cenarion Hold.",
  [8352] = "Bring an Abyssal Scepter to Bor Wildmane in Cenarion Hold.",
  [8353] = "Do a chicken emote at Innkeeper Firebrew, and in exchange you'll receive an Ironforge Mint!",
  [8354] = "Do a chicken emote at Innkeeper Norman, and in exchange you'll receive an Undercity Mint!",
  [8355] = "Do a train emote at Talvash del Kissel, and in exchange you'll receive a Gnomeregan Gumdrop!",
  [8356] = "Do a flex emote at Innkeeper Allison, and in exchange you'll receive Stormwind Nougat!",
  [8357] = "Do a dance emote at Innkeeper Saelienne, and in exchange you'll receive Darnassus Marzipan!",
