  [8846] = "Well then, it's settled; here are your supplies, $c. If you wish to do an additional exchange, then I am prepared to authorize it. Just give me the word and I'll make it happen.  Keep up the good work, $N. We need all the materiel we can muster if we're going to win this thing. If we all do our part, then victory shall be ours for the taking!",
