  [41315] = "Conduct the final test and return to Archmage Xylem in Azshara.",
  [41316] = "Bring the book to someone proficient in jewelcrafting.",
  [41317] = "Obtain a fragment on an elemental attuned to the Rune of Blaz from the Molten Core for Fanzy Sparkspring in Steamwheedle Port.",
  [41318] = "Deliver the materials to Fanzy Sparkspring in Steamwheedle Port.",
  [41319] = "Fanzy Sparkspring at Steamwheedle Port requires Blood of the Mountain and the Dark Iron Prospecting Lens from Fineous Darkvire for creation.",
  [41320] = "Listen to Akh Z'ador's story.",
  [41321] = "Bring Akh Z'ador in Azshara three Siren Brains for his ‘mental recovery'.",
  [41322] = "Akh Z'ador in Azshara requires herbs from the furbolgs to the west and flesh of the makrura to the east.",
  [41323] = "Return with Akh Z'ador's Riftwalker Cane and the Mojo of Jammal'an to Akh Z'ador in Azshara.",
  [41324] = "Search for Akh Z'ador's apprentice in the Blasted Lands.",
  [41325] = "Face whatever is meddling at the Dark Portal and return to Kas'tal overlooking the Blasted Lands.",
  [41326] = "Alert Sanv K'la of the imminent danger.",
  [41327] = "Speak with Akh Z'ador in the Harborage.",
  [41328] = "For Akh Z'ador to create a Pure Draenethyst Gemstone, bring him the following. He awaits in the Harborage in the Swamp of Sorrows.",
  [41329] = "Bring 10 Rumsey Rum Light to 'Ale Saint' Grida",
  [41333] = "Bring the book about gemology to an ancient master of that specialization.",
  [41334] = "Bring the book about gemology to an ancient master of that specialization.",
  [41335] = "Bring the book about gemology to an ancient master of that specialization.",
  [41336] = "Collect a substitute rune from the Scholomance for The Artificer in Desolace.",
  [41337] = "Bring the book about gemology to an ancient master of that specialization.",
  [41338] = "Seek the druids at the foot of the World Tree Nordrassil in Hyjal.",
  [41339] = "Investigate the disturbances near Darkhollow Pass and report to Arch Druid Dreamwind at Nordanaar.",
  [41340] = "Bring twenty Bright Dream Shards to Keeper Remulos in Moonglade.",
  [41341] = "Gather the needed relics for Keeper Remulos in Moonglade.",
  [41342] = "Cleanse the Dissipating Spectre at the Prophet's Hill in Hyjal and return to Keeper Remulos.",
  [41343] = "Speak to Doorman Montigue in Lower Karazhan Halls.",
  [41344] = "Recover the Comically Large Candle from Grizikil and return to Big Whiskers in Upper Karazhan.",
  [41347] = "Countess Tillia Earlwake seeks her stolen necklace. The last time she saw it was in her estate in Stormwind City.",
  [41348] = "The lead runs dry, Archibald is of no help. But perhaps the description of the orc he provided can aid in the search for Tillia's necklace. ",
  [41349] = "Analyze the journal and continue your search.",
  [41350] = "Seek H.C. somewhere in Lordaeron.",
  [41351] = "Find Razuv Ivaldi and take Tillia's necklace from him. Return it to her in the opera of the Lower Karazhan Halls.",
  [41352] = "Bring the golden ring to Archibald Earlwake in Stormwind Harbor.",
  [41353] = "Investigate the mysteries of the Enchanted Amethyst.",
  [41354] = "Free the spirits of Suffering and Anguished Highborne within Kel'Theril for Al'Dorel.",
  [41355] = "Bring the Magical Telescope back to Al'Dorel.",
  [41356] = "Brings 6 Pristine Azure Scales to Al'Dorel.",
  [41357] = "Bring the Core of Arc'Tiras back to Al'Dorel",
  [41358] = "Speak to Haleh at the top of Mazthoril about the truth revealed by Al'Dorel in Winterspring.",
  [41359] = "Return to Al'Dorel",
  [41360] = "Accept your gift.",
  [41361] = "Find someone to teach you about the scalding gemstone.",
  [41362] = "Bring Lokthos Darkbargainer the needed materials. He waits in the Grim Guzzler in the Blackrock Depths.",
  [41363] = "Thundris Windweaver in Auberdine needs samples of the Unnatural Overgrowths in the Wailing Caverns.",
  [41364] = "Bring your report to Deathguard Markus in Glenshire.",
  [41365] = "Slay Private William and report to Father Brightcopf in Glenshire.",
  [41366] = "Slay Prelate Ironmane and return to Father Brightcopf in Glenshire.",
  [41367] = "Slay Zandara Windhoof within Wailing Caverns, and bring her head back to Nalpak in the Barrens.",
  [41368] = "Slay Armory Quartermaster Daghelm and return Basil's journal to him in Undercity.",
  [41369] = "To restore the Scepter Rod of Medivh, Anelace the Clairvoyant at Morgan's Plot in Deadwind Pass needs a high amount of arcane energy.",
  [41370] = "A figment of Medivh is necessary to imbue the Scepter of Medivh with. Bring it to Anelace the Clairvoyant at Morgan's Plot outside Karazhan.",
  [41371] = "Attune the raging, alien magics within the Scepter of Medivh by bringing a source of similar magic to Anelace the Clairvoyant at Morgan's Plot outside Karazhan.",
  [41372] = "Bear witness to the creation of the Scepter of Medivh.",
  [41373] = "Find The Cook in Lower Karazhan Halls.",
  [41374] = "Slay the Ravenous Strigoi in Karazhan Crypts and return to The Cook in Lower Karazhan Halls.",
  [41375] = "Travel to Dire Maul and seek Lorekeeper Lydros.",
  [41376] = "Bring 5 Blue Leaves to Lorekeeper Lydros",
  [41377] = "Find Arch Druid Staghelm in Darnassus and seek his counsel.",
  [41378] = "Gather worgen blood for Fandral Staghelm. He requires blood samples from Karazhan, Gilneas City and Shadowfang Keep.",
  [41379] = "Bring Pure Worgen Blood to Arch Druid Dreamwind at Nordanaar in Hyjal.",
  [41380] = "Find Magatha Grimtotem and seek her counsel.",
  [41381] = "Gather worgen blood for Magatha Grimtotem. She requires blood samples from Karazhan, Gilneas City and Shadowfang Keep.",
  [41382] = "Bring Pure Worgen Blood to Arch Druid Dreamwind in Nordanaar.",
  [41383] = "Listen to what Arch Druid Dreamwind learned during your absence.",
  [41384] = "Slay Keeper Gnarlmoon. He can be found in the Upper Chambers of Karazhan.",
  [41385] = "Venture to Gilneas City and search for the whereabouts of the second Pricolich.",
  [41386] = "Slay Father Lycan in the Circle of Power.",
  [41387] = "Return with an Ironvine Root to Mathias Brightheart on Fray Island.",
  [41388] = "Pass Mathias Brightheart's test.",
  [41389] = "Hand the Glass Marble to Sakgoth in the next room.",
  [41390] = "Meet with Agent Kearnen in southern Westfall.",
  [41391] = "Recover valuable documents from the goblin and bring them to Renzik the 'Shiv' in Stormwind.",
  [41392] = "Infiltrate the Deadmines in Westfall and acquire Voss' Sizzling Brew.",
  [41393] = "Bring the Searing Eye of Rholgast to Mathias Brightheart on Fray Island.",
  [41394] = "Bring 6 Eternal Dreamstone Shards, 20 Mooncloth and Soul of a Dreadlord to Arch Druid Dreamwind.",
  [41396] = "Assist Keeper Remulos in Moonglade by bringing him the needed materials to craft a slumbering dreamveil.",
  [41397] = "Locate the remains of the green dragon Vithekus, commune with him and return to Keeper Remulos in Moonglade.",
  [41398] = "Meet Malorne in the Twilight Grove and receive his blessing.",
