  [41636] = "Retrieve the crate from the thieves in the northern mountains and bring it to Sister Argent at the Ambershire Church.",
  [41637] = "Talk with the children at Ambershire Church and revise their knowledge about Balor.",
  [41638] = "Find the urn of Brother Graham's mother and return it to him at the Ambershire Church in Northwind.",
