  [41643] = "Interrogate the townsfolk of Ambershire.",
  [41644] = "Locate the Defias headquarters in Northwind and search for clues about the abductions.",
  [41645] = "Search Sherwood Quarry. Return to Operative Hawthorne in Ambershire with anything useful you find.",
  [41646] = "Uncover the intent of the Blackrock Orc expansion to the northern watchtower. Report back to Operative Hawthorne in Ambershire.",
  [41647] = "Meet with the enigmatic woman of the woods.",
  [41648] = "Acquire the needed material for the Witch of Northwind in her coven in northwestern Northwind.",
  [41649] = "Listen to Zappo Zapblast's recording. The recording box stands next to him in Everlook.",
  [41650] = "Find the Everlook Broadcast hijacker. Zappo suggests searching northeastern Azshara.",
  [41651] = "Bring Zappo Zapblast the journal and device you found. He waits for you in Everlook in Winterspring.",
  [41652] = "Travel to the Everlook Broadcasting in Everlook in Winterspring.",
  [41653] = "Seek the Spirit of Wisdom in Dustwallow Marsh.",
  [41654] = "Deliver ten Boar Carcasses to Hufan Earthbow in Moonglade. Any boar of Azeroth is suitable for this task.",
  [41655] = "Recover a Lunar Token from the most powerful foes of Azeroth's dungeon to Lissandra Skysoar.",
  [41656] = "Gather 30 Dragonmaw Medallions from Dragonmaw Orcs within the Grim Reaches for Commander Aggnash at Shatterblade Point in Grim Reaches.",
  [41657] = "Bring the letter to someone of high authority in Grim Reaches.",
  [41658] = "Slay Korlag Doomsong within Zarm'geth Stronghold and bring his head to Commander Aggnash at Shatterblade Point within Grim Reaches.",
  [41659] = "Slay 6 Bonesplitter Troggs, 6 Bonesplitter Seers, 6 Bonesplitter Bonesnappers, and 6 Bonesplitter Skullthumpers for Grunt Morkan at Shatterblade Point in Grim Reaches.",
  [41660] = "Slay Dark Iron Dwarves around Groldan's Excavation, and gather 15 Shadowforge Signets for Grunt Morkan at Shatterblade Point in Grim Reaches.",
  [41661] = "Slay 9 Amberpaw Gnolls and return the Stormwind Supplies to Lion's Watch.",
  [41662] = "Find Leon's lost ring among the leaf piles.",
  [41663] = "Report to Duke Sherwood at the Jousting Grounds.",
  [41664] = "Search the Dark Knight's tent and return to Duke Sherwood with your findings.",
  [41665] = "Deliver Duke Sherwood's invitation to Lord Amberwood.",
  [41666] = "Gather the required ingredients for Amberglaze Donuts and return to Mitchell.",
  [41667] = "Seek Chaddus Suncarrier in Alah'Thalas about a pair of enchanted horse shoes and return to Commander Leder.",
  [41668] = "Gather a pack of Amberglaze Donuts, Bundle of Apples and Ingvild's Pie and return to her by the statue.",
  [41669] = "Deliver the packed good to Anduin Wrynn, in Stormwind Keep.",
  [41670] = "Retrieve 20 candles from the Bristlewhisker Cavern and return them to Groundskeeper Clive.",
  [41671] = "Kill The Wailing Nun in the old Abbey and retrieve the Northwind Necrology, return it to Groundskeeper Clive.",
  [41672] = "Slay 10 Amberfin Murlocs, 8 Amberfin Lakestalker and 4 Amberfin Tidecaller. Return to Jarold Thorpe at the Plump Pumpkin in Northwind afterwards.",
  [41673] = "Enter the cave by the shore and slay Grrblga, return her pearl to Henry by the dock.",
  [41674] = "Slay 20 Blackrock Invaders in the outer fields of Northwind Winery. Return to Old Man Crawford when done.",
  [41675] = "Retrieve the recipe for Northwind Amber from the upper floor of the Crawford Winery. Return it to Old Man Crawford in the Plump Pumpkin Inn.",
  [41676] = "Kill Overlord Throkk, Ozuk Doomspike and Shuni Steeltooth for Colonel Driscol and return to him.",
  [41677] = "Sabotage fifteen Dark Iron Gunpowder Kegs and return to Colonel Driscol at the Plump Pumpkin in Northwind.",
  [41678] = "Retrieve the Chalice of Light from the old Abbey for Inquisitor Abbadon.",
  [41679] = "Collect Charred Bones for Triston Lancaster at the abbey crypt in Northwind.",
  [41680] = "Find Wiggles!",
  [41681] = "Kill the Blackrock Pyremaster and return to Wiggles.",
  [41682] = "Sabotage fifteen Dark Iron Gunpowder Kegs and return to Dul Wolfsnarl in northern Northwind.",
  [41683] = "Kill Overlord Throkk, Ozuk Doomspike and Shuni Steeltooth for Dul Wolfsnarl and return to him.",
