  [41687] = "Repel the Dark Iron siege on Sherwood Quarry and return to Duke Sherwood at the Jousting Ground in Northwind.",
  [41688] = "Return the stolen horse feed to Horsekeeper Geringt at Mildenhall Horse Farm in Northwind.",
  [41689] = "Collect ten Grimmen Greens for the injured duck at Grimmen Lake in Northwind. Don't forget to bring a bandage for its wound!",
