  [41691] = "Gather the needed ingredients for the Witch of Northwind at her house in the Witch Coven.",
  [41692] = "Convene with the SI:7 corps on the plateau near the Ruins of Breezehaven on Balor.",
  [41693] = "Search for more clues at Sorrowmore Lake on Balor.",
  [41694] = "Find Agent Deryl's comrades and potential information about your enemies using the clues he gave you. Return to Verona Gillian at the SI:7 Outpost on Balor afterwards.",
  [41695] = "Bring Noppsy Spickerspan on Balor the Stormreaver Scroll.",
  [41696] = "Acquire Stormreaver Writings for Noppsy Spickerspan at the SI:7 Outpost on Balor.",
  [41697] = "Clear out the demons in the cave on the western side of Balor for Nippsy Spickerspan at the SI:7 Outpost.",
  [41698] = "Return to Rufus Hammerstrike at the SI:7 Outpost after placing the explosives on Balor.",
  [41699] = "Give Verona Gillian on Balor the report by Noppsy Spickerspan.",
  [41700] = "Find Helmsman Verix and return Yunie's Compass to her on the island north of Balor.",
  [41701] = "Penny Plainsteel on the northern island of Balor wants you to eradicate the local makrura and murlocs.",
  [41702] = "Dispose of the makrura and murloc leaders to pave the way for the Gullwing's escape. Return to Penny Plainsteel at the Gullwing Wreckage on Balor afterwards.",
  [41703] = "Alleviate the pirates on the northeastern island of Balor of their supplies and bring them to Mechanic Kixqal at the Gullwing Wreckage. Also bring a new Zeppelin Motor from Markel Smythe in Booty Bay.",
  [41704] = "Cleanse Lord Grahan's servants and return to him in his estate on western Balor.",
  [41705] = "Search the cave atop the battlefield on Balor and return with a memento to the woman inside the Balor church.",
  [41706] = "Collect Foul Essences from Balor's wildlife for Methendra Owltalon on the western cliff of the island.",
  [41707] = "Kinrial requires potent spores for her serum. She waits in the SI:7 Outpost on Balor.",
  [41708] = "To bolster their poison supplies, Kinrial in the SI:7 Outpost on Balor needs venom sacs of the Mistbark spiders.",
  [41709] = "Follow the magically inclined murlocs on Balor and search them for anything suspicious. Return to Hydromancer Finnigan on Balor afterwards.",
  [41710] = "Return with the needed reagents to Hydromancer Finnigan in the SI:7 Outpost on Balor.",
  [41711] = "Calm the pearl and return to Hydromancer Finnigan in the SI:7 Outpost on Balor afterwards.",
  [41712] = "Bring the letter to its intended recipient.",
  [41713] = "Bring Ralwen Ivon the book ‘Solutions to Arcane Resonance'. You can find him in the hidden repository within the Tower of Karazhan.",
  [41714] = "Ralwen Ivon needs the following reagents for the spell that will hopefully set him free. You can find him in the hidden repository within the Tower of Karazhan.",
  [41716] = "Speak with Advisor Ranagg at Shatterblade Post in Grim Reaches.",
  [41717] = "Retrieve the Dragonmaw Orders from one of the orcs at Baggoth's Rampart and return to Advisor Ranagg at Shatterblade Post in Grim Reaches.",
  [41718] = "Bring the orders to Commander Aggnash at Shatterblade Post in Grim Reaches.",
  [41719] = "Slay Geshgan Blackhollow, and bring his head to Commander Aggnash at Shatterblade Post in Grim Reaches.",
  [41720] = "Recover the Stolgaz Documents from Stolgaz Keep for Advisor Ranagg at Shatterblade Post in Grim Reaches.",
  [41721] = "Slay 7 Dragonmaw Elites, 7 Dragonmaw Champions, and 7 Dragonmaw Darkweavers for Commander Aggnash at Shatterblade Post in Grim Reaches.",
  [41722] = "Gather 6 Recluse Legs from Brown Recluse spiders for Bargolnak at Shatterblade Post in Grim Reaches.",
  [41723] = "Slay 6 Wild Maw Yeti, and 10 Hulking Wild Maw for Grunt Morkan at Shatterblade Post in Grim Reaches.",
  [41724] = "Slay Rethkag Mirefang at Geth'kar for Gar'gekk at Shatterblade Post in Grim Reaches.",
  [41725] = "Gather 6 Dark Iron Components from Groldan's Excavation to the south for Harlekk at Shatterblade Post in Grim Reaches.",
  [41726] = "Scavenge 6 Intricate Parts from the wrecks of steam tanks across the region for Harlekk at Shatterblade Post in Grim Reaches.",
  [41727] = "Gather 5 Vials of Entranced Blood for Far Seer Mothang at Shatterblade Post in Grim Reaches.",
  [41728] = "Gather Lingering Fel Energy from the demons in Desolace, and a Crystal Spine Scale from the basilisks in Stranglethorn Vale for Far Seer Mothang at Shatterblade Post in Grim Reaches.",
  [41729] = "Recover a Dark Essence from the ghosts of The Grim Hollow for Far Seer Mothang at Shatterblade Post in Grim Reaches.",
