  [41731] = "Wait for Far Seer Mothang to finish his ritual.",
  [41732] = "Find someone who may be familiar with the relic you hold.",
  [41733] = "Gather a Gold Power Core, and an Ancient Power Module for Tarwegg Dustshoulder in Ironforge.",
