  [41738] = "Gather 5 Ornate Feathers, 3 Binding Flame, and a Pristine Stonehide Heart for Yor'thegg the Wise in Grim Reaches.",
  [41739] = "Speak with Dorthas Read near the entrance of Grim Reaches, and inquire about the Flame of Dagnoth.",
