  [41742] = "Destroy the evil energy lingering in the Flame of Dagnoth for Yor'thegg the wise in Grim Reaches.",
  [41745] = "Witness the cleansing of the Scythe of Elune.",
  [41746] = "Gather 8 Lesser Arcane Residue from the nearby arcane elementals for Antonas Riftgaze at the Tower of Azora in Elwynn Forest.",
  [41747] = "Deliver the Shipment of Scrolls to Antonas Riftgaze at the Tower of Azora in Elwynn Forest.",
  [41748] = "Find the rogue mage Ralthas and put an end to his terror. Bring the Necklace of Azora to Theocritus at the Tower of Azora in Elwynn Forest.",
  [41749] = "Acquire the runestone of a Crumbling Stone Golem inside Dragomaw Retreat and bring it to Kixxle on the mainroad in the Wetlands.",
  [41750] = "Avenge the Mosshide gnolls by slaying their former leader Gowlfang in Dragonmaw Retreat. Return to Grimbite at their camp in The Green Belt in the Wetlands afterwards.",
  [41751] = "Nydiszanz at the Dragonmaw Gates in the Wetlands wishes to release his brother Searistrasz from his capture by the Dragonmaw orcs in the Dragonmaw Retreat.",
  [41752] = "Slay the Cavernweb Broodmother in the Dragonmaw Retreat and deliver her venom sac to Okal in Hammerfall.",
  [41753] = "Retrieve the Eternal Flame from within the Dragonmaw Retreat and bring it to Shara Blazen in Tarren Mill.",
  [41754] = "Bring the Redbrand Tablet to one of the historians at The Library in Ironforge.",
  [41755] = "Bring the Redbrand Tablet to Torwyn Redbrand in the Mystic Ward of Ironforge.",
  [41756] = "Slay Dragonmaw Veterans in Dragonmaw Retreat and return to Captain Stoutfist in Menethil Harbor.",
  [41757] = "Bring Captain Stoutfist in Menethil Harbor the head of Overlord Blackheart.",
  [41758] = "Destroy the living embodiment of natural corruption within the depths of Razorfen Kraul, and bring the Tainted Brambleheart to Kym Wildmane in Thunderbluff.",
  [41759] = "Gather 3 Gnarled Brambleroots from the Bramblehide elementals within Razorfen Kraul for Calaran Windseeker at Thalanaar in Feralas.",
