  [41762] = "Sabotage the pump stations of the Slickwick Oil Rig and return to the Shady Individual in Gadgetzan.",
  [41763] = "Recover Kwabit's Salacious Pictorial from the warehouse near the Slickwick Oil Rig in Tanaris.",
