  [41765] = "Clean up the Venture Co. intruders at the Slickwick Oil Rig and return to Boss Slickwick afterwards.",
  [41766] = "Find the leader of the Venture Co. intrusion and dispose of them. Bring Boss Slickwick at the Slickwick Oil Rig anything useful you find on them.",
  [41767] = "Deliver Boss Slickwick's Report to Nert Blastentom in Sparkwater Port in Durotar.",
  [41768] = "Deliver the reports of Northwind to Lady Katrana Prestor in Stormwind Keep.",
  [41769] = "Bring an almost ready to hatch Ravasaur Egg to Jama'nali at the eastern entrance of the Un'goro Crater.",
  [41770] = "Collect enough Ravasaur Teeth for Jama'nali at the southeastern entrance of the Un'goro crater.",
  [41771] = "Collect meat from the lesser beasts of Un'goro and bring it to Jama'nali at the southeastern entrance of the crater.",
  [41772] = "Collect Stegodon Glands and bring them to Jama'nali at the southeastern entrance of the Un'goro crater.",
  [41773] = "Deliver Devilsaur Hearts to Jama'nali at the southeastern entrance of the Un'goro crater.",
