  [41783] = "Acquire the documents for Noppsy Spickerspan in the SI:7 Outpost on Balor.",
  [41784] = "Pay Nizzle 100 Gold for the luxury to buy his fruitcakes.",
  [41785] = "Search the Wetlands for a red dragon willing to hear you out.",
  [41786] = "Look into the suspicious smoke coming from the open sea near Balor.",
