  [41791] = "Belgrom Rockmaul wants you to speak to Commander Aggnash in the Shatterblade Post in the Grim Reaches.",
  [41792] = "Bring the Steamed Hog to Grunt Morkan in Shatterblade Post in the Grim Reaches. You can reach it by heading east from the wetlands, or by passing through a tunnel in the southeast of Loch Modan.",
