  [41799] = "Speak with Hydromancer Finnigan in the SI:7 Outpost on Balor.",
  [41800] = "Lay 10 Wandering Souls, and 10 Displaced Ancestors to rest for Dorthas Read near the northern entrance of Grim Reaches.",
