  [41809] = "Use the Dragonfire Bomb to weaken Skardyn's shield, then defeat the Skardyn sorcerer.",
  [41811] = "Venture in Zul'Farrak, and slay Zel'jeb the Ancient, then return to Zalsu the Wanderer, who can be found south of Zul'Farrak.",
  [41812] = "Traverse into the depths of Blackfathom Deeps and recover a 'Seed of Bloom' from within the Moonshrine Ruins. Once acquired, return to Aelennia Starbloom east of The Zoram Strand in Ashenvale.",
  [41813] = "Find the crate of moonshine at Vander Farmstead and return it to Olmir Halfhorn.",
  [41814] = "Return the Crown of Balor to Olmir Halfhorn.",
  [41815] = "Collect 20 Bilgerat Weapon from the pirates in Bilgewater Compound and return to Grexx in Stormbreaker Point.",
  [41816] = "Slay 10 Sorrowmore Crocolisk and return 5 of their tails to Gre'shka Wolfsbite at Stormbreaker Point in Balor.",
  [41817] = "Slay 5 Mistbark Spider and 6 Mistbark Webweaver return to Gre'shka Wolfbite in Stormbreaker Point.",
  [41818] = "Slay 6 Stormwing Buzzard and 9 Stormwing Vulture and return to Gre'shka Wolfbite in Stormbreaker Point.",
  [41819] = "Slay 5 Muckgill Hunter, 7 Muckgill Murloc and the Sea Herald and return to O'jin in Stormbreaker Point.",
