  [41827] = "Find Drak'thul in his hut, floating above the waters of Balor.",
  [41828] = "Slay 7 SI:7 Scouts and return to Kilrogg Deadeye in Stormbreaker Point.",
  [41829] = "Collect 30 Stormreaver Warlock Eye and return to Kilrogg Deadeye in Stormbreaker Point.",
  [41830] = "Slay 5 Stormreaver Necromancer, 8 Foul Overseer and 8 Spikebone Miner and return to Kilrogg Deadeye in Stormbreaker Point.",
  [41831] = "Slay 5 Stormreaver Outrunner, 10 Stormreaver Ravager, 5 Stormreaver Drone, 5 Stormreaver Raider and return to Kilrogg Deadeye in Stormbreaker Point.",
  [41832] = "Slay 6 Stormreaver Brute, 6 Stormreaver Torturer, 4 Stormreaver Shadowcaller, 2 Stormreaver Stormblade and return to Kilrogg Deadeye in Stormbreaker Point.",
