  [41838] = "Travel to Slickwick Oil Rig and talk to Assistant Steamflare, dispose of some oil creatures on your way there.",
  [41840] = "Bring the wooden toy sword to someone that knew its owner. You may have luck in Northwind, where all of this started.",
  [41841] = "Deliver the Bloodstone Pendant to Lady Sylvanas Windrunner in Undercity.",
